["Bay Sturr, sizi çıkaracağız."] = "BAY STURR, SİZİ ÇIKARACAĞIZ.",
["Bay Sturr. Onlara hiçbir şey vermeyin."] = "BAY STURR. ONLARA HİÇBİR ŞEY VERMEYİN.",
["Bay Sturr. İtaat edin, yoksa sizi indirmek zorunda kalacağız."] = "BAY STURR. İTAAT EDİN, YOKSA SİZİ İNDİRMEK ZORUNDA KALACAĞIZ.",
["Bay... Locke? Numaramı bulmanıza şaşırdım."] = "BAY... LOCKE? NUMARAMI BULMANIZA ŞAŞIRDIM.",
["Bayan Pizakuick'e anons yapabilir misiniz? Adı Ayneeda?"] = "BAYAN PİZAKUİCK'E ANONS YAPABİLİR MİSİNİZ? ADI AYNEEDA?",
["Bayan Sharke? Hâlâ orada mısınız?"] = "BAYAN SHARKE? HÂLÂ ORADA MISINIZ?",
["Bayan Shevchenko küçük oğlunu şimdi görse mezarında ters dönerdi."] = "BAYAN SHEVCHENKO KÜÇÜK OĞLUNU ŞİMDİ GÖRSE MEZARINDA TERS DÖNERDİ.",
["Bayanlar baylar, biraz patlayıcı yerleştirir misiniz lütfen?"] = "BAYANLAR BAYLAR, BİRAZ PATLAYICI YERLEŞTİRİR MİSİNİZ LÜTFEN?",
["Bayağı gerginler. Tabloları masaya koyun, tuhaf şeylere karşı iki gözünüz de açık olsun."] = "BAYAĞI GERGİNLER. TABLOLARI MASAYA KOYUN, TUHAF ŞEYLERE KARŞI İKİ GÖZÜNÜZ DE AÇIK OLSUN.",
["Bayağı gürültülü, ha?"] = "BAYAĞI GÜRÜLTÜLÜ, HA?",
["Bayağı güzelmiş. Kendiminkini neye harcayacağımı bilmiyorum. Belki uzun vadeli mevduat sertifikasına yatırırım."] = "BAYAĞI GÜZELMİŞ. KENDİMİNKİNİ NEYE HARCAYACAĞIMI BİLMİYORUM. BELKİ UZUN VADELİ MEVDUAT SERTİFİKASINA YATIRIRIM.",
["Bayağı uzaktayız ama polisler 60 saniyeye burada olur."] = "BAYAĞI UZAKTAYIZ AMA POLİSLER 60 SANİYEYE BURADA OLUR.",
["Bayağı yakınım. Bana birkaç dakika verin."] = "BAYAĞI YAKINIM. BANA BİRKAÇ DAKİKA VERİN.",
["Bayram döneminin tecrübeli soyguncusu Strinch, 1957’den beri Noelleri çalıyor. 1972’deki Halloween Heist ile de bağlantılı."] = "BAYRAM DÖNEMİNİN TECRÜBELİ SOYGUNCUSU STRİNCH, 1957’DEN BERİ NOELLERİ ÇALIYOR. 1972’DEKİ HALLOWEEN HEİST İLE DE BAĞLANTILI.",
["Bayram Özel"] = "BAYRAM ÖZEL",
["Bayıldı!"] = "BAYILDI!",
["Bayılmayın, burası ganimet dolu!"] = "BAYILMAYIN, BURASI GANİMET DOLU!",
["Bayılttınız mı? Ciddi misiniz?"] = "BAYILTTINIZ MI? CİDDİ MİSİNİZ?",
["Bazen ailen için geri dönmen gerekir. Bedeli ne olursa olsun, karşında kim olursa olsun. Suçun terazisini dengelemenin tek yolu budur."] = "BAZEN AİLEN İÇİN GERİ DÖNMEN GEREKİR. BEDELİ NE OLURSA OLSUN, KARŞINDA KİM OLURSA OLSUN. SUÇUN TERAZİSİNİ DENGELEMENİN TEK YOLU BUDUR.",
["Bazen azı karar. Üstelik bunu giydiğinde üstlerine atılmanı hiç beklemeyecekler."] = "BAZEN AZI KARAR. ÜSTELİK BUNU GİYDİĞİNDE ÜSTLERİNE ATILMANI HİÇ BEKLEMEYECEKLER.",
["Bazen bir işi makinelere bırakmak daha iyidir. Bu, tembellik edebileceğimiz anlamına gelmez ama işler yolunda giderse işi daha hızlı bitiririz."] = "BAZEN BİR İŞİ MAKİNELERE BIRAKMAK DAHA İYİDİR. BU, TEMBELLİK EDEBİLECEĞİMİZ ANLAMINA GELMEZ AMA İŞLER YOLUNDA GİDERSE İŞİ DAHA HIZLI BİTİRİRİZ.",
["Bazen bir klasiğin üstüne çıkamazsın. \"Deh kovboy!\" diyen bir şapka mı istiyorsun? Daha fazla arama."] = "BAZEN BİR KLASİĞİN ÜSTÜNE ÇIKAMAZSIN. \"DEH KOVBOY!\" DİYEN BİR ŞAPKA MI İSTİYORSUN? DAHA FAZLA ARAMA.",
["Bazen doğrudan yol incelikten yoksundur ama yine de son derece etkilidir."] = "BAZEN DOĞRUDAN YOL İNCELİKTEN YOKSUNDUR AMA YİNE DE SON DERECE ETKİLİDİR.",
["Bazen insan Ay’a kadar çıkıp neler olacağını görmek ister. Peki oraya varınca ne yaparsın? Uzay epey büyük sonuçta..."] = "BAZEN İNSAN AY’A KADAR ÇIKIP NELER OLACAĞINI GÖRMEK İSTER. PEKİ ORAYA VARINCA NE YAPARSIN? UZAY EPEY BÜYÜK SONUÇTA...",
["Bazen kader en büyük sorunlarının nerede olduğunu gösterir. Fazla özgüvene kapılmanı önler. Görünüşe göre Murkywater onlardan çalmamızdan bıkmış ve intikam istiyor. Bir Murky ajanı az önce Crimenet’e sızdı. Bizi kalıcı olarak devre dışı bırakabileceğini söylüyor; inanıyorum. Ama bizimle, Murkywater’a KARŞI çalışmak istediğini de söylüyor. Ne selamlama ama, değil mi? Bu adamın gerçekten ne istediğini kim bilir. Hakkında daha fazla öğrenene kadar uyum sağlamalıyız. Durumu değerlendirip biraz kâr çıkaralım. Ama bir an olsun gardını indirme."] = "BAZEN KADER EN BÜYÜK SORUNLARININ NEREDE OLDUĞUNU GÖSTERİR. FAZLA ÖZGÜVENE KAPILMANI ÖNLER. GÖRÜNÜŞE GÖRE MURKYWATER ONLARDAN ÇALMAMIZDAN BIKMIŞ VE İNTİKAM İSTİYOR. BİR MURKY AJANI AZ ÖNCE CRİMENET’E SIZDI. BİZİ KALICI OLARAK DEVRE DIŞI BIRAKABİLECEĞİNİ SÖYLÜYOR; İNANIYORUM. AMA BİZİMLE, MURKYWATER’A KARŞI ÇALIŞMAK İSTEDİĞİNİ DE SÖYLÜYOR. NE SELAMLAMA AMA, DEĞİL Mİ? BU ADAMIN GERÇEKTEN NE İSTEDİĞİNİ KİM BİLİR. HAKKINDA DAHA FAZLA ÖĞRENENE KADAR UYUM SAĞLAMALIYIZ. DURUMU DEĞERLENDİRİP BİRAZ KÂR ÇIKARALIM. AMA BİR AN OLSUN GARDINI İNDİRME.",
["Bazen kötücül, her zaman gizemli. The Baba Yaga, Slav mitlerinin karanlık ormanlarında dolaşır. Bir havanda uçar, havaneli kullanır ve dev tavuk bacakları üzerinde yürüyen bir kulübede yaşar."] = "BAZEN KÖTÜCÜL, HER ZAMAN GİZEMLİ. THE BABA YAGA, SLAV MİTLERİNİN KARANLIK ORMANLARINDA DOLAŞIR. BİR HAVANDA UÇAR, HAVANELİ KULLANIR VE DEV TAVUK BACAKLARI ÜZERİNDE YÜRÜYEN BİR KULÜBEDE YAŞAR.",
["Bazen mesele yalnızca sessiz olmak değildir. Bir profesyonel için hız da aynı derecede önemli olabilir. İş ne kadar büyükse, ikisini birden başarıyla uygulamanın getirdiği saygınlık da o kadar artar."] = "BAZEN MESELE YALNIZCA SESSİZ OLMAK DEĞİLDİR. BİR PROFESYONEL İÇİN HIZ DA AYNI DERECEDE ÖNEMLİ OLABİLİR. İŞ NE KADAR BÜYÜKSE, İKİSİNİ BİRDEN BAŞARIYLA UYGULAMANIN GETİRDİĞİ SAYGINLIK DA O KADAR ARTAR.",
["Bazen ne zaman elde kalacağını, ne zaman pas geçeceğini bilmek gerek."] = "BAZEN NE ZAMAN ELDE KALACAĞINI, NE ZAMAN PAS GEÇECEĞİNİ BİLMEK GEREK.",
["Bazen silah, yalnızca silah değildir. İçinde bir ruh taşır. Onu kavrayanın damarlarından güç hissi akar, içini yıkım arzusuyla doldurur. Sonra cehennem serbest kalır. İşte biz buna Demon deriz."] = "BAZEN SİLAH, YALNIZCA SİLAH DEĞİLDİR. İÇİNDE BİR RUH TAŞIR. ONU KAVRAYANIN DAMARLARINDAN GÜÇ HİSSİ AKAR, İÇİNİ YIKIM ARZUSUYLA DOLDURUR. SONRA CEHENNEM SERBEST KALIR. İŞTE BİZ BUNA DEMON DERİZ.",
["Bazen yeni yollar açmak için bazı kuralları çiğnemek gerekir."] = "BAZEN YENİ YOLLAR AÇMAK İÇİN BAZI KURALLARI ÇİĞNEMEK GEREKİR.",
["Bazen yeteneklerinin ne kadar üstün olduğunu düşmanlarına göstermenin, tamamen egodan gelen o hazzına kapılmakta sorun yoktur. Ateşli silaha karşı yay ve ok kullanmak kadar \"Seni tam istediğim yerden vururum\" diyen bir şey yok."] = "BAZEN YETENEKLERİNİN NE KADAR ÜSTÜN OLDUĞUNU DÜŞMANLARINA GÖSTERMENİN, TAMAMEN EGODAN GELEN O HAZZINA KAPILMAKTA SORUN YOKTUR. ATEŞLİ SİLAHA KARŞI YAY VE OK KULLANMAK KADAR \"SENİ TAM İSTEDİĞİM YERDEN VURURUM\" DİYEN BİR ŞEY YOK.",
["Bazen öldüresin gelmez ama soygunu yine de yapmak zorundasındır. O hâlde neden bunu bir oyuna çevirmeyesin?"] = "BAZEN ÖLDÜRESİN GELMEZ AMA SOYGUNU YİNE DE YAPMAK ZORUNDASINDIR. O HÂLDE NEDEN BUNU BİR OYUNA ÇEVİRMEYESİN?",
["Bazen üçte keramet vardır."] = "BAZEN ÜÇTE KERAMET VARDIR.",
["Bazı Vudu rahipleri sonsuz yaşamın sırrını bildiklerini iddia eder. Bu maskeyi takmanın onu sağlayacağının garantisi yok ama düşmanlarının ödünü muhtemelen koparır. Belki bir Jamaika barbeküsüne davet edilmeni de sağlar."] = "BAZI VUDU RAHİPLERİ SONSUZ YAŞAMIN SIRRINI BİLDİKLERİNİ İDDİA EDER. BU MASKEYİ TAKMANIN ONU SAĞLAYACAĞININ GARANTİSİ YOK AMA DÜŞMANLARININ ÖDÜNÜ MUHTEMELEN KOPARIR. BELKİ BİR JAMAİKA BARBEKÜSÜNE DAVET EDİLMENİ DE SAĞLAR.",
["Bazı adamlar sadece tekerleklerin yanışını izlemek ister."] = "BAZI ADAMLAR SADECE TEKERLEKLERİN YANIŞINI İZLEMEK İSTER.",
["Bazı atışlar cephaneni azaltmaz. Nasıl olduğunu bana sorma."] = "BAZI ATIŞLAR CEPHANENİ AZALTMAZ. NASIL OLDUĞUNU BANA SORMA.",
["Bazı bağlama halatları hâlâ çözülmedi. "] = "BAZI BAĞLAMA HALATLARI HÂLÂ ÇÖZÜLMEDİ. ",
["Bazı başarımlar Silah, Modifikasyon veya Maske açar."] = "BAZI BAŞARIMLAR SİLAH, MODİFİKASYON VEYA MASKE AÇAR.",
["Bazı bölümler Kolay zorlukta oynanamaz."] = "BAZI BÖLÜMLER KOLAY ZORLUKTA OYNANAMAZ.",
["Bazı durumlar soğuk bir bıçağın ustaca kullanılmasını gerektirir ama bu iş, yüksek atış hızından doğan vahşi ve kısa ölüm serileri istiyor."] = "BAZI DURUMLAR SOĞUK BİR BIÇAĞIN USTACA KULLANILMASINI GEREKTİRİR AMA BU İŞ, YÜKSEK ATIŞ HIZINDAN DOĞAN VAHŞİ VE KISA ÖLÜM SERİLERİ İSTİYOR.",
["Bazı durumlarda fazladan bir tıbbi yardım kiti, yaşamla ölüm arasındaki fark olabilir."] = "BAZI DURUMLARDA FAZLADAN BİR TIBBİ YARDIM KİTİ, YAŞAMLA ÖLÜM ARASINDAKİ FARK OLABİLİR.",
["Bazı düşmanlar vücut zırhı kullanır. Kafalarına nişan almalısın."] = "BAZI DÜŞMANLAR VÜCUT ZIRHI KULLANIR. KAFALARINA NİŞAN ALMALISIN.",
["Bazı erkeklerle arabaların derdi ne? Neyse, artık içeridesiniz. Öldürün onu."] = "BAZI ERKEKLERLE ARABALARIN DERDİ NE? NEYSE, ARTIK İÇERİDESİNİZ. ÖLDÜRÜN ONU.",
["Bazı eski bilgiler dijital sistemde tutulmuyor. Almak için Arşive eriş."] = "BAZI ESKİ BİLGİLER DİJİTAL SİSTEMDE TUTULMUYOR. ALMAK İÇİN ARŞİVE ERİŞ.",
["Bazı güvenli dosyalara erişmek için Direktörün onayı gerekiyor. Ofisini bulup dosyaları onaylamanın yolunu ara."] = "BAZI GÜVENLİ DOSYALARA ERİŞMEK İÇİN DİREKTÖRÜN ONAYI GEREKİYOR. OFİSİNİ BULUP DOSYALARI ONAYLAMANIN YOLUNU ARA.",
["Bazı kapıları kilitlerine ateş ederek açabilirsin."] = "BAZI KAPILARI KİLİTLERİNE ATEŞ EDEREK AÇABİLİRSİN.",
["Bazı klasiklerin modası asla geçmez!"] = "BAZI KLASİKLERİN MODASI ASLA GEÇMEZ!",
["Bazı konsollar hâlâ çevrim içi. Tabletleri üzerlerine yerleştir ve Bain'in alarm sistemini kırmasını bekle."] = "BAZI KONSOLLAR HÂLÂ ÇEVRİM İÇİ. TABLETLERİ ÜZERLERİNE YERLEŞTİR VE BAIN'İN ALARM SİSTEMİNİ KIRMASINI BEKLE.",
["Bazı muhafızlar Gizlilik sırasında sabit bir devriye güzergâhını izler. Bunu kendi lehine kullan."] = "BAZI MUHAFIZLAR GİZLİLİK SIRASINDA SABİT BİR DEVRİYE GÜZERGÂHINI İZLER. BUNU KENDİ LEHİNE KULLAN.",
["Bazı piçler D.C.'de kokain operasyonu kurmaya çalışıyor. Mallarını alın. İşlerini dağıtın. Tek bir küçük ayrıntı var..."] = "BAZI PİÇLER D.C.'DE KOKAİN OPERASYONU KURMAYA ÇALIŞIYOR. MALLARINI ALIN. İŞLERİNİ DAĞITIN. TEK BİR KÜÇÜK AYRINTI VAR...",
["Bazı ruhlar varoluşun kıyısında oyalanıp mobilyaları hareket ettirmekle, geceleri inlemekle yetinir. Bazılarıysa daha somut bir etki ister. D.C. Polisi daha geçenlerde şehirdeki büyük bankalarda, sanat müzelerinde ve kuyumcularda hayalet vakalarının keskin biçimde arttığını bildirdi. Tanıklar değerli eşyaların kendi kendine kapıdan süzülüp çıktığını söylüyor. Son bir vurgun için dönen, çoktan ölmüş soyguncuların hayaletleri olmalı."] = "BAZI RUHLAR VAROLUŞUN KIYISINDA OYALANIP MOBİLYALARI HAREKET ETTİRMEKLE, GECELERİ İNLEMEKLE YETİNİR. BAZILARIYSA DAHA SOMUT BİR ETKİ İSTER. D.C. POLİSİ DAHA GEÇENLERDE ŞEHİRDEKİ BÜYÜK BANKALARDA, SANAT MÜZELERİNDE VE KUYUMCULARDA HAYALET VAKALARININ KESKİN BİÇİMDE ARTTIĞINI BİLDİRDİ. TANIKLAR DEĞERLİ EŞYALARIN KENDİ KENDİNE KAPIDAN SÜZÜLÜP ÇIKTIĞINI SÖYLÜYOR. SON BİR VURGUN İÇİN DÖNEN, ÇOKTAN ÖLMÜŞ SOYGUNCULARIN HAYALETLERİ OLMALI.",
["Bazı sersemler para yakmayı izlemekten hoşlanır ama ben değil. Yine de Yufu Wang öğrenince çıldıracak, Vlad da buna bayılacak!"] = "BAZI SERSEMLER PARA YAKMAYI İZLEMEKTEN HOŞLANIR AMA BEN DEĞİL. YİNE DE YUFU WANG ÖĞRENİNCE ÇILDIRACAK, VLAD DA BUNA BAYILACAK!",
["Bazı silahlar sökülmüş gibi. Birleştirip hiçbir parçayı geride bırakmadığımızdan emin olmalıyız. İyi ki atölyeyi daha patlatmadık."] = "BAZI SİLAHLAR SÖKÜLMÜŞ GİBİ. BİRLEŞTİRİP HİÇBİR PARÇAYI GERİDE BIRAKMADIĞIMIZDAN EMİN OLMALIYIZ. İYİ Kİ ATÖLYEYİ DAHA PATLATMADIK.",
["Bazı silahlarda Tekli Atış ile Otomatik Atış arasında geçiş yapabileceğin alternatif atış modları bulunur."] = "BAZI SİLAHLARDA TEKLİ ATIŞ İLE OTOMATİK ATIŞ ARASINDA GEÇİŞ YAPABİLECEĞİN ALTERNATİF ATIŞ MODLARI BULUNUR.",
["Bazı soygunlar, muhafızları alarma geçirmeden Gizlilik yöntemiyle tamamlanabilir."] = "BAZI SOYGUNLAR, MUHAFIZLARI ALARMA GEÇİRMEDEN GİZLİLİK YÖNTEMİYLE TAMAMLANABİLİR.",
["Bazı tiplerin bu işte nasıl hayatta kaldığını merak edersin ama açık fikirli kalmaya çalışıyorum. Neyse, Jimmy bizimle çalışmak istiyor; büyük bir iş ayarlamış. Biraz araştırdım. Deli olsun olmasın, tanıdıklar sorun olmadığını söylüyor. Riske değer olabilir. Yine de emin olmalıyız; çünkü iş, kötü şöhretli Rus psikopat \"Akan\"a karşı gitmek. Duyduğuma göre hafife alınacak biri değil. Jimmy ilk olarak bir Murkywater sevkiyatına el koymamızı istiyor. Sıkı durun: EMP bombası! Sonraki aşamada gerekeceğini söylüyor."] = "BAZI TİPLERİN BU İŞTE NASIL HAYATTA KALDIĞINI MERAK EDERSİN AMA AÇIK FİKİRLİ KALMAYA ÇALIŞIYORUM. NEYSE, JIMMY BİZİMLE ÇALIŞMAK İSTİYOR; BÜYÜK BİR İŞ AYARLAMIŞ. BİRAZ ARAŞTIRDIM. DELİ OLSUN OLMASIN, TANIDIKLAR SORUN OLMADIĞINI SÖYLÜYOR. RİSKE DEĞER OLABİLİR. YİNE DE EMİN OLMALIYIZ; ÇÜNKÜ İŞ, KÖTÜ ŞÖHRETLİ RUS PSİKOPAT \"AKAN\"A KARŞI GİTMEK. DUYDUĞUMA GÖRE HAFİFE ALINACAK BİRİ DEĞİL. JIMMY İLK OLARAK BİR MURKYWATER SEVKİYATINA EL KOYMAMIZI İSTİYOR. SIKI DURUN: EMP BOMBASI! SONRAKİ AŞAMADA GEREKECEĞİNİ SÖYLÜYOR.",
["Bazı çantalar daha ağırdır. En hafif zırhlı oyuncu en ağır çantayı, en ağır zırhlı oyuncu en hafif çantayı taşısın."] = "BAZI ÇANTALAR DAHA AĞIRDIR. EN HAFİF ZIRHLI OYUNCU EN AĞIR ÇANTAYI, EN AĞIR ZIRHLI OYUNCU EN HAFİF ÇANTAYI TAŞISIN.",
["Bazı Şeyler Sonsuza Dek Sürer"] = "BAZI ŞEYLER SONSUZA DEK SÜRER",
["Bazı şeyler resmen \"gangster\" diye bağırır, değil mi? Bu tarz takım elbisenin tam doğru paltoyla birleşmesinde bir şey var. Parlak ve dayanıklı; soygunla geçen günün ya da gecen ne getirirse getirsin seni atlatmaya hazır. "] = "BAZI ŞEYLER RESMEN \"GANGSTER\" DİYE BAĞIRIR, DEĞİL Mİ? BU TARZ TAKIM ELBİSENİN TAM DOĞRU PALTOYLA BİRLEŞMESİNDE BİR ŞEY VAR. PARLAK VE DAYANIKLI; SOYGUNLA GEÇEN GÜNÜN YA DA GECEN NE GETİRİRSE GETİRSİN SENİ ATLATMAYA HAZIR. ",
["Bazı şeyler unutulmalıdır; yoksa taşıdıkları sırlar dünyayı yok eder. Karanlığı durdurmak için etini, kalbini sun. Uçuruma yeterince uzun bakarsan sonu memnuniyetle karşılarsın; çünkü çatlaklarda ve oyuklarda Dünya iyidir."] = "BAZI ŞEYLER UNUTULMALIDIR; YOKSA TAŞIDIKLARI SIRLAR DÜNYAYI YOK EDER. KARANLIĞI DURDURMAK İÇİN ETİNİ, KALBİNİ SUN. UÇURUMA YETERİNCE UZUN BAKARSAN SONU MEMNUNİYETLE KARŞILARSIN; ÇÜNKÜ ÇATLAKLARDA VE OYUKLARDA DÜNYA İYİDİR.",
["Bazıları Dünyanın Yanışını İzlemek İster"] = "BAZILARI DÜNYANIN YANIŞINI İZLEMEK İSTER",
["Bazıları asla tatmin olmaz. Elmas verirsin, yine daha fazlasını isterler. Soyguncular genellikle böyle insanlardır, değil mi?"] = "BAZILARI ASLA TATMİN OLMAZ. ELMAS VERİRSİN, YİNE DAHA FAZLASINI İSTERLER. SOYGUNCULAR GENELLİKLE BÖYLE İNSANLARDIR, DEĞİL Mİ?",
["Bazıları bu takımın kırmızı kollarının, düşmanın dikkatini ayaklarının yaptığından uzaklaştıracağını söyledi. Yeni bir fikir ama belki de körü körüne güvenmeye değmez!"] = "BAZILARI BU TAKIMIN KIRMIZI KOLLARININ, DÜŞMANIN DİKKATİNİ AYAKLARININ YAPTIĞINDAN UZAKLAŞTIRACAĞINI SÖYLEDİ. YENİ BİR FİKİR AMA BELKİ DE KÖRÜ KÖRÜNE GÜVENMEYE DEĞMEZ!",
["Bazıları gerçek erkekler tıraş olmaz der ama doğrusu gerçek erkekler tıraş olamaz. Sıradan jiletler, gür bir Almir sakalının sık, görkemli bitki örtüsünden sekip gider."] = "BAZILARI GERÇEK ERKEKLER TIRAŞ OLMAZ DER AMA DOĞRUSU GERÇEK ERKEKLER TIRAŞ OLAMAZ. SIRADAN JİLETLER, GÜR BİR ALMIR SAKALININ SIK, GÖRKEMLİ BİTKİ ÖRTÜSÜNDEN SEKİP GİDER.",
["Bazıları gölgelerde gizlice dolaşmaya katlanamaz. Etrafın Murky ajanlarıyla çevriliyken işi bitirip bir an önce oradan defolmak istemen şaşırtıcı değil."] = "BAZILARI GÖLGELERDE GİZLİCE DOLAŞMAYA KATLANAMAZ. ETRAFIN MURKY AJANLARIYLA ÇEVRİLİYKEN İŞİ BİTİRİP BİR AN ÖNCE ORADAN DEFOLMAK İSTEMEN ŞAŞIRTICI DEĞİL.",
["Bazıları hayatta bedavadan yol almak, yakışıklılıkla ve şansla ilerlemek ister. Bazen öyle görünse de dünya öyle işlemez. Yetenek yalnızca başlangıçtır; eğitim, adanmışlık, kararlılık gerekir. Lider olarak kendi kararını vermelisin. Kararlarına saygı duyarsan başkaları da duyar."] = "BAZILARI HAYATTA BEDAVADAN YOL ALMAK, YAKIŞIKLILIKLA VE ŞANSLA İLERLEMEK İSTER. BAZEN ÖYLE GÖRÜNSE DE DÜNYA ÖYLE İŞLEMEZ. YETENEK YALNIZCA BAŞLANGIÇTIR; EĞİTİM, ADANMIŞLIK, KARARLILIK GEREKİR. LİDER OLARAK KENDİ KARARINI VERMELİSİN. KARARLARINA SAYGI DUYARSAN BAŞKALARI DA DUYAR.",
["Bazıları senden zaten eski çağların trolü veya devi gibi korkuyor olabilir. Öyleyse kalelerinin kasasını boşaltırken neden o role de bürünmeyesin?"] = "BAZILARI SENDEN ZATEN ESKİ ÇAĞLARIN TROLÜ VEYA DEVİ GİBİ KORKUYOR OLABİLİR. ÖYLEYSE KALELERİNİN KASASINI BOŞALTIRKEN NEDEN O ROLE DE BÜRÜNMEYESİN?",
["Bazıları uzun paltoların 1990’larda demode olduğunu söyler. Ama Payday Gang modaya uymaz. Her şeyi havalı gösterebilirler."] = "BAZILARI UZUN PALTOLARIN 1990’LARDA DEMODE OLDUĞUNU SÖYLER. AMA PAYDAY GANG MODAYA UYMAZ. HER ŞEYİ HAVALI GÖSTEREBİLİRLER.",
["Bazıları yarış tulumunun ağartılmış yunus derisinden yapıldığını, yağlı salgılarının Çin tıbbında değer gördüğünü söylüyor. Tek bildiğimiz... Adı The Tids."] = "BAZILARI YARIŞ TULUMUNUN AĞARTILMIŞ YUNUS DERİSİNDEN YAPILDIĞINI, YAĞLI SALGILARININ ÇİN TIBBINDA DEĞER GÖRDÜĞÜNÜ SÖYLÜYOR. TEK BİLDİĞİMİZ... ADI THE TIDS.",
["Bazıları öfke sorunun olduğunu söylüyor. O insanlar artık ortalıkta yok."] = "BAZILARI ÖFKE SORUNUN OLDUĞUNU SÖYLÜYOR. O İNSANLAR ARTIK ORTALIKTA YOK.",
["Bazılarımız hayatta kalmayı bilir. Zorlu ortamlardaki zorlu görevler bizi yıkmaz. Kullanılırız ama atılmayız, yoldaşlık etsin diye tutuluruz. Sonra neredeyse unutulup ateşe terk edilir, son anda kurtarılırız. Sonunda fazlasıyla hak ettiğimiz onurlu yere geri döneriz."] = "BAZILARIMIZ HAYATTA KALMAYI BİLİR. ZORLU ORTAMLARDAKİ ZORLU GÖREVLER BİZİ YIKMAZ. KULLANILIRIZ AMA ATILMAYIZ, YOLDAŞLIK ETSİN DİYE TUTULURUZ. SONRA NEREDEYSE UNUTULUP ATEŞE TERK EDİLİR, SON ANDA KURTARILIRIZ. SONUNDA FAZLASIYLA HAK ETTİĞİMİZ ONURLU YERE GERİ DÖNERİZ.",
["Bazılarına göre deneyimler paylaştıkça güzelleşir; performans artırıcı aerosol aygıtlarında bile! Sevdiğin o özel soyguncuyla banka kasalarını boşaltıp iş bitirirken aranızdaki bağı güçlendirecek bir şey."] = "BAZILARINA GÖRE DENEYİMLER PAYLAŞTIKÇA GÜZELLEŞİR; PERFORMANS ARTIRICI AEROSOL AYGITLARINDA BİLE! SEVDİĞİN O ÖZEL SOYGUNCUYLA BANKA KASALARINI BOŞALTIP İŞ BİTİRİRKEN ARANIZDAKİ BAĞI GÜÇLENDİRECEK BİR ŞEY.",
["Bazılarının zevkleri çok özeldir; kendilerine ve başkalarına son derece katı hedefler koyarlar. Bazen insana sadece bir meydan okuma gerekir."] = "BAZILARININ ZEVKLERİ ÇOK ÖZELDİR; KENDİLERİNE VE BAŞKALARINA SON DERECE KATI HEDEFLER KOYARLAR. BAZEN İNSANA SADECE BİR MEYDAN OKUMA GEREKİR.",
["Bazılarınız koruma ateşi açarken diğerleri o kutularla uğraşırsa şansınız artar."] = "BAZILARINIZ KORUMA ATEŞİ AÇARKEN DİĞERLERİ O KUTULARLA UĞRAŞIRSA ŞANSINIZ ARTAR.",
["Bağlamak için bir çanta taşımalısın"] = "BAĞLAMAK İÇİN BİR ÇANTA TAŞIMALISIN",
["Bağlamışlar onu. Kesip kurtarmamız gerek."] = "BAĞLAMIŞLAR ONU. KESİP KURTARMAMIZ GEREK.",
["Bağlandı."] = "BAĞLANDI.",
["Bağlandık... Bakalım ne var."] = "BAĞLANDIK... BAKALIM NE VAR.",
["Bağlandım."] = "BAĞLANDIM.",
["Bağlanmamış siviller gözetimsiz kalırsa ayağa kalkıp kaçar. Bunu önlemek için Plastik Kelepçelerini kullan."] = "BAĞLANMAMIŞ SİVİLLER GÖZETİMSİZ KALIRSA AYAĞA KALKIP KAÇAR. BUNU ÖNLEMEK İÇİN PLASTİK KELEPÇELERİNİ KULLAN.",
["Bağlanmış"] = "BAĞLANMIŞ",
["Bağlantı Veritabanı"] = "BAĞLANTI VERİTABANI",
["Bağlantı gitti! Elektriği geri getirin, çabuk!"] = "BAĞLANTI GİTTİ! ELEKTRİĞİ GERİ GETİRİN, ÇABUK!",
["Bağlantı gitti. Elektrik kesildi. Lütfen geri verin, olur mu?"] = "BAĞLANTI GİTTİ. ELEKTRİK KESİLDİ. LÜTFEN GERİ VERİN, OLUR MU?",
["Bağlantı kesildi. Neler oluyor?"] = "BAĞLANTI KESİLDİ. NELER OLUYOR?",
["Bağlantı kuruldu. Çalışmaya devam."] = "BAĞLANTI KURULDU. ÇALIŞMAYA DEVAM.",
["Bağlantı listesini çalabilmek için Buluc’un kasasını aç."] = "BAĞLANTI LİSTESİNİ ÇALABİLMEK İÇİN BULUC’UN KASASINI AÇ.",
["Bağlantı:"] = "BAĞLANTI:",
["Bağlantılar"] = "BAĞLANTILAR",
["Bağlantıları kullandım; sizi almak için bir helikopter ayarladım."] = "BAĞLANTILARI KULLANDIM; SİZİ ALMAK İÇİN BİR HELİKOPTER AYARLADIM.",
["Bağlantılarım kullanımınız için tıbbi malzeme bırakılmasını sağlayabilir."] = "BAĞLANTILARIM KULLANIMINIZ İÇİN TIBBİ MALZEME BIRAKILMASINI SAĞLAYABİLİR.",
["Bağlantılarımız yeni bir icadın ortaya çıktığını söylüyor. Soğuk füzyon enerjisi, fosil yakıtların sonu ve petrol holdinglerinin ölümü. Bizim işimiz risk yönetimi."] = "BAĞLANTILARIMIZ YENİ BİR İCADIN ORTAYA ÇIKTIĞINI SÖYLÜYOR. SOĞUK FÜZYON ENERJİSİ, FOSİL YAKITLARIN SONU VE PETROL HOLDİNGLERİNİN ÖLÜMÜ. BİZİM İŞİMİZ RİSK YÖNETİMİ.",
["Bağlantım aracıyla olay yerinde olacak. Hazır olun."] = "BAĞLANTIM ARACIYLA OLAY YERİNDE OLACAK. HAZIR OLUN.",
["Bağlantım kesildi, elektriği geri getirmeniz gerekiyor."] = "BAĞLANTIM KESİLDİ, ELEKTRİĞİ GERİ GETİRMENİZ GEREKİYOR.",
["Bağlantım kesildi, yeniden kurmalısınız!"] = "BAĞLANTIM KESİLDİ, YENİDEN KURMALISINIZ!",
["Bağlantım koptu, beni tekrar içeri sokun."] = "BAĞLANTIM KOPTU, BENİ TEKRAR İÇERİ SOKUN.",
["Bağlantım o vagonları çatıdan yakarak açmanın daha kolay olacağını söylüyor."] = "BAĞLANTIM O VAGONLARI ÇATIDAN YAKARAK AÇMANIN DAHA KOLAY OLACAĞINI SÖYLÜYOR.",
["Bağlantım trenin zırhının çatıda daha ince olduğunu söylüyor. Yerinizde olsam orayı yakıp delmeyi denerdim."] = "BAĞLANTIM TRENİN ZIRHININ ÇATIDA DAHA İNCE OLDUĞUNU SÖYLÜYOR. YERİNİZDE OLSAM ORAYI YAKIP DELMEYİ DENERDİM.",
["Bağlantım, aradığım bilginin çiftlik evindeki bir dizüstü bilgisayarda olduğunu söylüyor. Sağdaki kapıdan doğrudan oraya gidebilirsiniz."] = "BAĞLANTIM, ARADIĞIM BİLGİNİN ÇİFTLİK EVİNDEKİ BİR DİZÜSTÜ BİLGİSAYARDA OLDUĞUNU SÖYLÜYOR. SAĞDAKİ KAPIDAN DOĞRUDAN ORAYA GİDEBİLİRSİNİZ.",
["Bağlantımız orada olacak."] = "BAĞLANTIMIZ ORADA OLACAK.",
["Bağlantımız partiyi başlatmak için gereken benzin ve ekipmanı sakladı. Bagajdalar. Arabaya yakıt doldurun, krikoyla da tekerlekleri kaldırın."] = "BAĞLANTIMIZ PARTİYİ BAŞLATMAK İÇİN GEREKEN BENZİN VE EKİPMANI SAKLADI. BAGAJDALAR. ARABAYA YAKIT DOLDURUN, KRİKOYLA DA TEKERLEKLERİ KALDIRIN.",
["Bağlantımıza göre çiftlikte bir yerde hidroklorik asit var. Delilleri yok etmek gerekirse diye tutuyorlar. Silah atölyesini mahvetmek için güzel yol, değil mi?"] = "BAĞLANTIMIZA GÖRE ÇİFTLİKTE BİR YERDE HİDROKLORİK ASİT VAR. DELİLLERİ YOK ETMEK GEREKİRSE DİYE TUTUYORLAR. SİLAH ATÖLYESİNİ MAHVETMEK İÇİN GÜZEL YOL, DEĞİL Mİ?",
["Bağlantıyı kaybettim, elektriği geri getirmeniz gerekiyor."] = "BAĞLANTIYI KAYBETTİM, ELEKTRİĞİ GERİ GETİRMENİZ GEREKİYOR.",
["Bağlanılıyor..."] = "BAĞLANILIYOR...",
["Bağlanıyor... Bir dakika sürebilir."] = "BAĞLANIYOR... BİR DAKİKA SÜREBİLİR.",
["Bağlanıyorum. Aynı anda sadece birini yapabiliriz. Umarım doğru olan budur."] = "BAĞLANIYORUM. AYNI ANDA SADECE BİRİNİ YAPABİLİRİZ. UMARIM DOĞRU OLAN BUDUR.",
["Bağlarından kurtulup bir silah almış gibi! Ona yardım etmelisiniz!"] = "BAĞLARINDAN KURTULUP BİR SİLAH ALMIŞ GİBİ! ONA YARDIM ETMELİSİNİZ!",
["Bağlarını kesin!"] = "BAĞLARINI KESİN!",
["Bağlarını kesmek için bir çeşit alet gerekecek."] = "BAĞLARINI KESMEK İÇİN BİR ÇEŞİT ALET GEREKECEK.",
["Bağlayın millet."] = "BAĞLAYIN MİLLET.",
["Bağır/Etkileşim"] = "BAĞIR/ETKİLEŞİM",
["Bağır/Etkileşim: kısa bas; Yapay Zekâyı Durdur: basılı tut"] = "BAĞIR/ETKİLEŞİM: KISA BAS; YAPAY ZEKÂYI DURDUR: BASILI TUT",
["Baş bilim insanı öldü mü? Siktir. Onsuz güvenliği geçemeyiz... Aslında teknik olarak ONA değil, ELİNE ihtiyacımız var..."] = "BAŞ BİLİM İNSANI ÖLDÜ MÜ? SİKTİR. ONSUZ GÜVENLİĞİ GEÇEMEYİZ... ASLINDA TEKNİK OLARAK ONA DEĞİL, ELİNE İHTİYACIMIZ VAR...",
["Baş bilim insanını bulup güvenlik kapısına götürün."] = "BAŞ BİLİM İNSANINI BULUP GÜVENLİK KAPISINA GÖTÜRÜN.",
["Baş küratörde ihtiyacın olan bir eşya var. Şık giyimli, kızıl saçlı bir kadın ara."] = "BAŞ KÜRATÖRDE İHTİYACIN OLAN BİR EŞYA VAR. ŞIK GİYİMLİ, KIZIL SAÇLI BİR KADIN ARA.",
["Baş küratörü bul"] = "BAŞ KÜRATÖRÜ BUL",
["Baş küratörü bulun. Onda ihtiyacımız olan bir şey var."] = "BAŞ KÜRATÖRÜ BULUN. ONDA İHTİYACIMIZ OLAN BİR ŞEY VAR.",
["Baş küratörün giriş kartı lazım, kadını bulun."] = "BAŞ KÜRATÖRÜN GİRİŞ KARTI LAZIM, KADINI BULUN.",
["Başabaş"] = "BAŞABAŞ",
["Başarabilen Küçük Soyguncu"] = "BAŞARABİLEN KÜÇÜK SOYGUNCU",
["Başaracaksınız... Parayı düşünün yeter!"] = "BAŞARACAKSINIZ... PARAYI DÜŞÜNÜN YETER!",
["Başardı millet. İsterseniz daha fazla ganimet toplayın, isterseniz motorlara atlayıp kaçın!"] = "BAŞARDI MİLLET. İSTERSENİZ DAHA FAZLA GANİMET TOPLAYIN, İSTERSENİZ MOTORLARA ATLAYIP KAÇIN!",
["Başardık be çocuklar! O beyaz saçlı ucubenin istediği verileri almasını engelledik. Ne dersiniz? Ne dersiniz? Yakalım mı? Yakıp cehennemin dibine gönderelim!"] = "BAŞARDIK BE ÇOCUKLAR! O BEYAZ SAÇLI UCUBENİN İSTEDİĞİ VERİLERİ ALMASINI ENGELLEDİK. NE DERSİNİZ? NE DERSİNİZ? YAKALIM MI? YAKIP CEHENNEMİN DİBİNE GÖNDERELİM!",
["Başardık! Şimdi kapıların sistemini kırıp açın ve çok geç olmadan buradan çıkın!"] = "BAŞARDIK! ŞİMDİ KAPILARIN SİSTEMİNİ KIRIP AÇIN VE ÇOK GEÇ OLMADAN BURADAN ÇIKIN!",
["Başardıklarına inanamıyorum. Bain'in bu kadar savunmasız olabileceğini hiç düşünmemiştim."] = "BAŞARDIKLARINA İNANAMIYORUM. BAIN'İN BU KADAR SAVUNMASIZ OLABİLECEĞİNİ HİÇ DÜŞÜNMEMİŞTİM.",
["Başardınız ama kamyonu yakmasaydınız bizim için daha iyi olurdu. Bir dahaki sefere biraz daha incelikli olun."] = "BAŞARDINIZ AMA KAMYONU YAKMASAYDINIZ BİZİM İÇİN DAHA İYİ OLURDU. BİR DAHAKİ SEFERE BİRAZ DAHA İNCELİKLİ OLUN.",
["Başardınız!"] = "BAŞARDINIZ!",
["Başardınız! Tam orada! Elması alın!"] = "BAŞARDINIZ! TAM ORADA! ELMASI ALIN!",
["Başardınız! Tamam, trene dönün de gün batımına doğru sürüp gidelim!"] = "BAŞARDINIZ! TAMAM, TRENE DÖNÜN DE GÜN BATIMINA DOĞRU SÜRÜP GİDELİM!",
["Başardınız! The Diamond! Bir de siktiğimin Payday Gang'i. Kendinizi tarihe yazdınız beyler."] = "BAŞARDINIZ! THE DIAMOND! BİR DE SİKTİĞİMİN PAYDAY GANG'İ. KENDİNİZİ TARİHE YAZDINIZ BEYLER.",
["Başardınız! Şimdi kokaini arkaya atın da gidelim."] = "BAŞARDINIZ! ŞİMDİ KOKAİNİ ARKAYA ATIN DA GİDELİM.",
["Başardınız! Şu an petrolü çekiyoruz. Gözden uzak durun."] = "BAŞARDINIZ! ŞU AN PETROLÜ ÇEKİYORUZ. GÖZDEN UZAK DURUN.",
["Başardınız. Bir ton para aldınız ve bütün dikkatleri üstünüze çektiniz. GenSec de herkesin önünde rezil olmayı hak ediyor."] = "BAŞARDINIZ. BİR TON PARA ALDINIZ VE BÜTÜN DİKKATLERİ ÜSTÜNÜZE ÇEKTİNİZ. GENSEC DE HERKESİN ÖNÜNDE REZİL OLMAYI HAK EDİYOR.",
["Başardınız. Bu arabalar için ederinden fazlasını ödeyecek birkaç Rus petrol zengini playboy buldum. İyi iş çıkardınız!"] = "BAŞARDINIZ. BU ARABALAR İÇİN EDERİNDEN FAZLASINI ÖDEYECEK BİRKAÇ RUS PETROL ZENGİNİ PLAYBOY BULDUM. İYİ İŞ ÇIKARDINIZ!",
["Başardığınıza inanamıyorum! Kalıplar, tren, her şey sizde. Beni şaşırtmaktan hiç vazgeçmiyorsunuz."] = "BAŞARDIĞINIZA İNANAMIYORUM! KALIPLAR, TREN, HER ŞEY SİZDE. BENİ ŞAŞIRTMAKTAN HİÇ VAZGEÇMİYORSUNUZ.",
["Başarmak istiyorsak artık hızlanmalıyız..."] = "BAŞARMAK İSTİYORSAK ARTIK HIZLANMALIYIZ...",
["Başarmak istiyorsanız polisi sigorta şalterlerinden uzak tutun!"] = "BAŞARMAK İSTİYORSANIZ POLİSİ SİGORTA ŞALTERLERİNDEN UZAK TUTUN!",
["Başarı böyle gelir, devam edin yeter."] = "BAŞARI BÖYLE GELİR, DEVAM EDİN YETER.",
["Başarı ekranında, hayatta kalan her ekip üyesi için bonus kazanırsın."] = "BAŞARI EKRANINDA, HAYATTA KALAN HER EKİP ÜYESİ İÇİN BONUS KAZANIRSIN.",
["Başarılı"] = "BAŞARILI",
["Başarılı Kaçışlar"] = "BAŞARILI KAÇIŞLAR",
["Başarılı bir banka soygunundan daha çok sevdiğim tek şey sonrasında içilen purodur. Sizin için bir tane yakıyorum millet."] = "BAŞARILI BİR BANKA SOYGUNUNDAN DAHA ÇOK SEVDİĞİM TEK ŞEY SONRASINDA İÇİLEN PURODUR. SİZİN İÇİN BİR TANE YAKIYORUM MİLLET.",
["Başarılı bir ganimet toplama operasyonu daha! Aferin dostlarım!"] = "BAŞARILI BİR GANİMET TOPLAMA OPERASYONU DAHA! AFERİN DOSTLARIM!",
