["Belki ofise bakın. Birkaç belge yakmak gerekirse diye pürmüz tutmak için hep iyi bir yerdir, ha?"] = "BELKİ OFİSE BAKIN. BİRKAÇ BELGE YAKMAK GEREKİRSE DİYE PÜRMÜZ TUTMAK İÇİN HEP İYİ BİR YERDİR, HA?",
["Belki oraya çıkan bir arka yol vardır."] = "BELKİ ORAYA ÇIKAN BİR ARKA YOL VARDIR.",
["Belki oyları değiştiremeyiz ama kullanılmalarını engelleyebiliriz. AVM'deki oy makinelerini vuracağız."] = "BELKİ OYLARI DEĞİŞTİREMEYİZ AMA KULLANILMALARINI ENGELLEYEBİLİRİZ. AVM'DEKİ OY MAKİNELERİNİ VURACAĞIZ.",
["Belki sana evcil hayvan diye birkaç tane getiririz Locke."] = "BELKİ SANA EVCİL HAYVAN DİYE BİRKAÇ TANE GETİRİRİZ LOCKE.",
["Belki sessizce yaparız diye düşünmüştüm ama olmayacak galiba. Yakında kesin bir sürü herif tepenizde olacak!"] = "BELKİ SESSİZCE YAPARIZ DİYE DÜŞÜNMÜŞTÜM AMA OLMAYACAK GALİBA. YAKINDA KESİN BİR SÜRÜ HERİF TEPENİZDE OLACAK!",
["Belki sisteme girip doğru iş istasyonuna sinyal gönderebilirim. Aramaya devam edin."] = "BELKİ SİSTEME GİRİP DOĞRU İŞ İSTASYONUNA SİNYAL GÖNDEREBİLİRİM. ARAMAYA DEVAM EDİN.",
["Belki sizi fark etmezler..."] = "BELKİ SİZİ FARK ETMEZLER...",
["Belki telsizde parazit olmuştur, tekrar edeyim. Şu siktiğimin patlayıcılarını kilitlere yerleştirin. Lütfen."] = "BELKİ TELSİZDE PARAZİT OLMUŞTUR, TEKRAR EDEYİM. ŞU SİKTİĞİMİN PATLAYICILARINI KİLİTLERE YERLEŞTİRİN. LÜTFEN.",
["Belki toplantı odasının yanındaki bir depo dolabı, dinleme cihazı için iyi yerdir, ha?"] = "BELKİ TOPLANTI ODASININ YANINDAKİ BİR DEPO DOLABI, DİNLEME CİHAZI İÇİN İYİ YERDİR, HA?",
["Belki uzaylıları vardır."] = "BELKİ UZAYLILARI VARDIR.",
["Belki yakında sigaraya falan çıkar. O zaman yakalarsınız."] = "BELKİ YAKINDA SİGARAYA FALAN ÇIKAR. O ZAMAN YAKALARSINIZ.",
["Belki yakınlarda elektriği keserseniz neler olduğunu araştırmaya gelir, ha?"] = "BELKİ YAKINLARDA ELEKTRİĞİ KESERSENİZ NELER OLDUĞUNU ARAŞTIRMAYA GELİR, HA?",
["Belki yakınlarda kullanabileceğiniz alet çantasının bulunduğu bir malzeme dolabı vardır. Gidip bakın."] = "BELKİ YAKINLARDA KULLANABİLECEĞİNİZ ALET ÇANTASININ BULUNDUĞU BİR MALZEME DOLABI VARDIR. GİDİP BAKIN.",
["Belki yakınlarda kullanabileceğiniz bir alet kutusu bulunan malzeme dolabı falan vardır. Gidip bir bakın."] = "BELKİ YAKINLARDA KULLANABİLECEĞİNİZ BİR ALET KUTUSU BULUNAN MALZEME DOLABI FALAN VARDIR. GİDİP BİR BAKIN.",
["Belki yeni Medic Dozer'larımız fikrinizi değiştirir..."] = "BELKİ YENİ MEDIC DOZER'LARIMIZ FİKRİNİZİ DEĞİŞTİRİR...",
["Belki çok bariz bir yere koymuştur, ha?"] = "BELKİ ÇOK BARİZ BİR YERE KOYMUŞTUR, HA?",
["Belki üst kata bakarsınız."] = "BELKİ ÜST KATA BAKARSINIZ.",
["Belki ışıkları söndürmek işe yarar. Etrafta bir sigorta kutusu arayın."] = "BELKİ IŞIKLARI SÖNDÜRMEK İŞE YARAR. ETRAFTA BİR SİGORTA KUTUSU ARAYIN.",
["Belki şarap ithalatına da başlamalıyım! Vlad'in Şarapları! Kulağa hoş geliyor."] = "BELKİ ŞARAP İTHALATINA DA BAŞLAMALIYIM! VLAD'İN ŞARAPLARI! KULAĞA HOŞ GELİYOR.",
["Belki şarap mahzeninde C4 vardır. Kontrollü bir ortamda tutulmalı."] = "BELKİ ŞARAP MAHZENİNDE C4 VARDIR. KONTROLLÜ BİR ORTAMDA TUTULMALI.",
["Belki şifre Crimenet'le ilgilidir?"] = "BELKİ ŞİFRE CRİMENET'LE İLGİLİDİR?",
["Belki... iki dakika. İşim kesilmezse TABİİ."] = "BELKİ... İKİ DAKİKA. İŞİM KESİLMEZSE TABİİ.",
["Belki... tuz ruhu?"] = "BELKİ... TUZ RUHU?",
["Bellek, oralardaki bütün dizüstü bilgisayarlarla uyumlu olmalı."] = "BELLEK, ORALARDAKİ BÜTÜN DİZÜSTÜ BİLGİSAYARLARLA UYUMLU OLMALI.",
["Belleği alıp ayrıl. Dallas, çıkarken seni görmelerine izin verme."] = "BELLEĞİ ALIP AYRIL. DALLAS, ÇIKARKEN SENİ GÖRMELERİNE İZİN VERME.",
["Belleği yanına alıp çık."] = "BELLEĞİ YANINA ALIP ÇIK.",
["Belleğin şifresini çöz ve güvenceye al"] = "BELLEĞİN ŞİFRESİNİ ÇÖZ VE GÜVENCEYE AL",
["Belli ki eksik parçalar var. Kapıyı açmak için onları bulmanız gerekiyor herhâlde. Etrafa bakın."] = "BELLİ Kİ EKSİK PARÇALAR VAR. KAPIYI AÇMAK İÇİN ONLARI BULMANIZ GEREKİYOR HERHÂLDE. ETRAFA BAKIN.",
["Belli ki o tabloları yeterince umursamıyor. Başka bir şey bulmanız gerek."] = "BELLİ Kİ O TABLOLARI YETERİNCE UMURSAMIYOR. BAŞKA BİR ŞEY BULMANIZ GEREK.",
["Ben 8. Karakol'dan Yüzbaşı Rogers. GenSec, şüpheli bir faaliyetle ilgili endişelerini bildirdi. Tedbir amaçlı memur yolluyorum."] = "BEN 8. KARAKOL'DAN YÜZBAŞI ROGERS. GENSEC, ŞÜPHELİ BİR FAALİYETLE İLGİLİ ENDİŞELERİNİ BİLDİRDİ. TEDBİR AMAÇLI MEMUR YOLLUYORUM.",
["Ben Bile, pilotunuz..."] = "BEN BILE, PİLOTUNUZ...",
["Ben Bir Kundakçıyım"] = "BEN BİR KUNDAKÇIYIM",
["Ben Bir İntikamcıyım!"] = "BEN BİR İNTİKAMCIYIM!",
["Ben Bronson, dört dakikaya oradayım!"] = "BEN BRONSON, DÖRT DAKİKAYA ORADAYIM!",
["Ben Bronson, kaçış şoförünüz! Ne gerekiyor?"] = "BEN BRONSON, KAÇIŞ ŞOFÖRÜNÜZ! NE GEREKİYOR?",
["Ben Bronson, ne gerekiyor?"] = "BEN BRONSON, NE GEREKİYOR?",
["Ben Dolandırıcı Değilim!"] = "BEN DOLANDIRICI DEĞİLİM!",
["Ben Ernesto Sosa'yım orospu çocukları!"] = "BEN ERNESTO SOSA'YIM OROSPU ÇOCUKLARI!",
["Ben GenSec'ten Hilary. Bir kontrol edeyim dedim. Barney orada mı?"] = "BEN GENSEC'TEN HİLARY. BİR KONTROL EDEYİM DEDİM. BARNEY ORADA MI?",
["Ben GenSec'ten Jen. Sistemlerimiz zaman kilidinizde plan dışı bir etkinleştirme tespit etti. Her şeyin yolunda olduğunu doğrulamak için arıyorum."] = "BEN GENSEC'TEN JEN. SİSTEMLERİMİZ ZAMAN KİLİDİNİZDE PLAN DIŞI BİR ETKİNLEŞTİRME TESPİT ETTİ. HER ŞEYİN YOLUNDA OLDUĞUNU DOĞRULAMAK İÇİN ARIYORUM.",
["Ben Hem Şifacı Hem Tank Hem Hasarcıyım"] = "BEN HEM ŞİFACI HEM TANK HEM HASARCIYIM",
["Ben John Henry Simmons. Daha fazlasını öğrenmek isterseniz... konuşmalıyız. Biraz siyasi entrika sizi rahatsız etmiyorsa ilginizi çekebilecek bir şeyim olabilir..."] = "BEN JOHN HENRY SİMMONS. DAHA FAZLASINI ÖĞRENMEK İSTERSENİZ... KONUŞMALIYIZ. BİRAZ SİYASİ ENTRİKA SİZİ RAHATSIZ ETMİYORSA İLGİNİZİ ÇEKEBİLECEK BİR ŞEYİM OLABİLİR...",
["Ben Julian."] = "BEN JULİAN.",
["Ben MPDC'den Yüzbaşı Rogers. GenSec'ten telefon aldık. Orada olanlarla ilgili bazı endişeleri varmış. Her şeyin yolunda olduğundan emin olmak için üniformalı memurlar gönderiyorum."] = "BEN MPDC'DEN YÜZBAŞI ROGERS. GENSEC'TEN TELEFON ALDIK. ORADA OLANLARLA İLGİLİ BAZI ENDİŞELERİ VARMIŞ. HER ŞEYİN YOLUNDA OLDUĞUNDAN EMİN OLMAK İÇİN ÜNİFORMALI MEMURLAR GÖNDERİYORUM.",
["Ben Mortimer. Bankadan. Paranız güvende. Size nasıl yardım edebilirim?"] = "BEN MORTİMER. BANKADAN. PARANIZ GÜVENDE. SİZE NASIL YARDIM EDEBİLİRİM?",
["Ben Ninjayım"] = "BEN NİNJAYIM",
["Ben Orada Bile Değildim!"] = "BEN ORADA BILE DEĞİLDİM!",
["Ben Profesyonelim"] = "BEN PROFESYONELİM",
["Ben Randolph. Roberts Bank size hizmet etmekten mutluluk duyar."] = "BEN RANDOLPH. ROBERTS BANK SİZE HİZMET ETMEKTEN MUTLULUK DUYAR.",
["Ben Sallanırım"] = "BEN SALLANIRIM",
["Ben bir şey içmeye gidiyorum. Kutuyu alınca haber verin, olur mu?"] = "BEN BİR ŞEY İÇMEYE GİDİYORUM. KUTUYU ALINCA HABER VERİN, OLUR MU?",
["Ben bir şeyi söylersin, sonsuza kadar hatırlarım diyen insanlardanım. Uzun bir hafızam var, kütüphane gibi."] = "BEN BİR ŞEYİ SÖYLERSİN, SONSUZA KADAR HATIRLARIM DİYEN İNSANLARDANIM. UZUN BİR HAFIZAM VAR, KÜTÜPHANE GİBİ.",
["Ben bu konuda ne yapabileceğimize bakarken etrafta işe yarar bir şey arayın."] = "BEN BU KONUDA NE YAPABİLECEĞİMİZE BAKARKEN ETRAFTA İŞE YARAR BİR ŞEY ARAYIN.",
["Ben buna razı olmadım! Gidiyorum buradan!"] = "BEN BUNA RAZI OLMADIM! GİDİYORUM BURADAN!",
["Ben bunu yaparken Murky'leri kollayın."] = "BEN BUNU YAPARKEN MURKY'LERİ KOLLAYIN.",
["Ben bunu yaparken siz kod parçalarının olduğu üç dizüstü bilgisayarı bulun."] = "BEN BUNU YAPARKEN SİZ KOD PARÇALARININ OLDUĞU ÜÇ DİZÜSTÜ BİLGİSAYARI BULUN.",
["Ben burada bir yıl dayanırım, domuz siken piçler!"] = "BEN BURADA BİR YIL DAYANIRIM, DOMUZ SİKEN PİÇLER!",
["Ben de Kasa'ya saklardım. Ama ben kuşkucu bir adamım."] = "BEN DE KASA'YA SAKLARDIM. AMA BEN KUŞKUCU BİR ADAMIM.",
["Ben de aşağı yukarı öyle dedim. Ama bizim Vlad eski ayakkabı gibi sağlamdır."] = "BEN DE AŞAĞI YUKARI ÖYLE DEDİM. AMA BİZİM VLAD ESKİ AYAKKABI GİBİ SAĞLAMDIR.",
["Ben de aşağı yukarı öyle dedim. Ama dayanıklıdır. Bizim Vlad eski ayakkabı gibi sağlamdır."] = "BEN DE AŞAĞI YUKARI ÖYLE DEDİM. AMA DAYANIKLIDIR. BİZİM VLAD ESKİ AYAKKABI GİBİ SAĞLAMDIR.",
["Ben de burada nezaket gösteriyordum. Ağzına biraz kurşun tıksam nasıl olur?"] = "BEN DE BURADA NEZAKET GÖSTERİYORDUM. AĞZINA BİRAZ KURŞUN TIKSAM NASIL OLUR?",
["Ben de böyle yapardım."] = "BEN DE BÖYLE YAPARDIM.",
["Ben de ona dedim ki, hani, ‘Mitchell... Michelle değil. Kanadalı değilim amına koyayım!’ Anladın mı?"] = "BEN DE ONA DEDİM Kİ, HANİ, ‘MITCHELL... MİCHELLE DEĞİL. KANADALI DEĞİLİM AMINA KOYAYIM!’ ANLADIN MI?",
["Ben değil, ben değil, beeen değiiil!"] = "BEN DEĞİL, BEN DEĞİL, BEEEN DEĞİİİL!",
["Ben hallederim, siz Murky hödüklerine göz kulak olun."] = "BEN HALLEDERİM, SİZ MURKY HÖDÜKLERİNE GÖZ KULAK OLUN.",
["Ben içerideyken... geride bıraktığım paramı toplayacak ortak lazım."] = "BEN İÇERİDEYKEN... GERİDE BIRAKTIĞIM PARAMI TOPLAYACAK ORTAK LAZIM.",
["Ben kim miyim? Tanıdığınız bütün siyasetçilerin tam tersiyim. "] = "BEN KİM MİYİM? TANIDIĞINIZ BÜTÜN SİYASETÇİLERİN TAM TERSİYİM. ",
["Ben kim miyim? Tanıdığınız bütün siyasetçilerin tam tersiyim... Orospu çocuğu!"] = "BEN KİM MİYİM? TANIDIĞINIZ BÜTÜN SİYASETÇİLERİN TAM TERSİYİM... OROSPU ÇOCUĞU!",
["Ben kostik soda diyorum."] = "BEN KOSTİK SODA DİYORUM.",
["Ben malç... şey, gübreyi şarap mahzeninde tutardım."] = "BEN MALÇ... ŞEY, GÜBREYİ ŞARAP MAHZENİNDE TUTARDIM.",
["Ben nereden bilecektim lan? Orospu çocuğu bana araba aküsüyle masaj yapıyordu!"] = "BEN NEREDEN BİLECEKTİM LAN? OROSPU ÇOCUĞU BANA ARABA AKÜSÜYLE MASAJ YAPIYORDU!",
["Ben nereden bileyim lan sersem!"] = "BEN NEREDEN BİLEYİM LAN SERSEM!",
["Ben neredeyim lan? Gördüğüm... Depolar mı?"] = "BEN NEREDEYİM LAN? GÖRDÜĞÜM... DEPOLAR MI?",
["Ben olsam girmeden biraz keşif yapardım."] = "BEN OLSAM GİRMEDEN BİRAZ KEŞİF YAPARDIM.",
["Ben olsam kokaini çantalayıp çıkardım."] = "BEN OLSAM KOKAİNİ ÇANTALAYIP ÇIKARDIM.",
["Ben olsam önemli bir şeyi bir lambaya falan saklayabilirdim."] = "BEN OLSAM ÖNEMLİ BİR ŞEYİ BİR LAMBAYA FALAN SAKLAYABİLİRDİM.",
["Ben olsam şarap mahzenine bakardım, belki oraya C4 saklamışlardır."] = "BEN OLSAM ŞARAP MAHZENİNE BAKARDIM, BELKİ ORAYA C4 SAKLAMIŞLARDIR.",
["Ben paramı çekince diğer bütün götler de aynısını yaptı. Ama akıllıydım. İlk çıkan bendim, anlıyor musun? Bir anda bir milyon dolar kazandım."] = "BEN PARAMI ÇEKİNCE DİĞER BÜTÜN GÖTLER DE AYNISINI YAPTI. AMA AKILLIYDIM. İLK ÇIKAN BENDİM, ANLIYOR MUSUN? BİR ANDA BİR MİLYON DOLAR KAZANDIM.",
["Ben polislerle anlaşırken siz şimdilik rahat olun."] = "BEN POLİSLERLE ANLAŞIRKEN SİZ ŞİMDİLİK RAHAT OLUN.",
["Ben sadece, bilirsin, epeydir konuşmadık. Bir hâl hatır sorayım dedim."] = "BEN SADECE, BİLİRSİN, EPEYDİR KONUŞMADIK. BİR HÂL HATIR SORAYIM DEDİM.",
["Ben sistemi kırarken siz o şifre parçalarını bulun. Unutmayın, her dizüstü bilgisayarda bir parça."] = "BEN SİSTEMİ KIRARKEN SİZ O ŞİFRE PARÇALARINI BULUN. UNUTMAYIN, HER DİZÜSTÜ BİLGİSAYARDA BİR PARÇA.",
["Ben votkayı sevmiyorum ama o beni pek seviyor."] = "BEN VOTKAYI SEVMİYORUM AMA O BENİ PEK SEVİYOR.",
["Ben vururum, sen ölürsün!"] = "BEN VURURUM, SEN ÖLÜRSÜN!",
["Ben yalnızca güvenilir ortaklar seçerim. Biri sizi bekliyor olacak."] = "BEN YALNIZCA GÜVENİLİR ORTAKLAR SEÇERİM. BİRİ SİZİ BEKLİYOR OLACAK.",
["Ben yokken neler kaçırdım bakalım? "] = "BEN YOKKEN NELER KAÇIRDIM BAKALIM? ",
["Ben, anlamıyorum. Neden bilgisayarlara sızmıyorsunuz?"] = "BEN, ANLAMIYORUM. NEDEN BİLGİSAYARLARA SIZMIYORSUNUZ?",
["Ben, şey, Craig. Şey, Müşteri Memnuniyeti Bölümünden arıyorum."] = "BEN, ŞEY, CRAİG. ŞEY, MÜŞTERİ MEMNUNİYETİ BÖLÜMÜNDEN ARIYORUM.",
["Ben... Gerd. Sizi The Golden Grin Müşteri Memnuniyeti Bölümünden arıyorum."] = "BEN... GERD. SİZİ THE GOLDEN GRİN MÜŞTERİ MEMNUNİYETİ BÖLÜMÜNDEN ARIYORUM.",
["Ben... nerede olduğumuzu bilmiyorum..."] = "BEN... NEREDE OLDUĞUMUZU BİLMİYORUM...",
["Ben... onları atlatamıyorum!"] = "BEN... ONLARI ATLATAMIYORUM!",
["Ben... size söylüyorum. En iyi matkapları Ukrayna yapar. Bir dahakine oradan al Locky, bozulmaz."] = "BEN... SİZE SÖYLÜYORUM. EN İYİ MATKAPLARI UKRAYNA YAPAR. BİR DAHAKİNE ORADAN AL LOCKY, BOZULMAZ.",
["Ben... şey... tamam. Demek nükleer savaş başlığı çalıyoruz. Millet, onlara çok ama çok nazik davranın."] = "BEN... ŞEY... TAMAM. DEMEK NÜKLEER SAVAŞ BAŞLIĞI ÇALIYORUZ. MİLLET, ONLARA ÇOK AMA ÇOK NAZİK DAVRANIN.",
