["Bende Bu İş"] = "BENDE BU İŞ",
["Benden aldıklarınızı geri verecek, sonra içten bir özür mesajı göndereceksiniz. Belki o zaman işimiz biter."] = "BENDEN ALDIKLARINIZI GERİ VERECEK, SONRA İÇTEN BİR ÖZÜR MESAJI GÖNDERECEKSİNİZ. BELKİ O ZAMAN İŞİMİZ BİTER.",
