["Benden ne istiyorsun? DAHA FAZLA DENEYİM BONUSU MU? Belki buraya daha sonra başka bir şey ekleriz..."] = "BENDEN NE İSTİYORSUN? DAHA FAZLA DENEYİM BONUSU MU? BELKİ BURAYA DAHA SONRA BAŞKA BİR ŞEY EKLERİZ...",
["Benden tek kelime alamazsınız!"] = "BENDEN TEK KELİME ALAMAZSINIZ!",
["Benden uzak tutmalısınız şunları amına koyayım!"] = "BENDEN UZAK TUTMALISINIZ ŞUNLARI AMINA KOYAYIM!",
["Beneath the Mountain işinde kasalardaki ve dağın tepesindeki tüm ganimeti kaçış helikopterine yükle."] = "BENEATH THE MOUNTAIN İŞİNDE KASALARDAKİ VE DAĞIN TEPESİNDEKİ TÜM GANİMETİ KAÇIŞ HELİKOPTERİNE YÜKLE.",
["Beneath the Mountain işini OVERKILL veya üzeri zorlukta hiçbir oyuncu yere düşmeden tamamla."] = "BENEATH THE MOUNTAIN İŞİNİ OVERKILL VEYA ÜZERİ ZORLUKTA HİÇBİR OYUNCU YERE DÜŞMEDEN TAMAMLA.",
["Beneath the Mountain soygununda OVERKILL veya üzeri zorlukta, soygunun başlangıcından itibaren 10 dakika içinde ganimet içeren 4 kasayı aç."] = "BENEATH THE MOUNTAIN SOYGUNUNDA OVERKILL VEYA ÜZERİ ZORLUKTA, SOYGUNUN BAŞLANGICINDAN İTİBAREN 10 DAKİKA İÇİNDE GANİMET İÇEREN 4 KASAYI AÇ.",
["Beneath the Mountain soygununu Death Sentence zorlukta One Down kuralı etkinken tamamla."] = "BENEATH THE MOUNTAIN SOYGUNUNU DEATH SENTENCE ZORLUKTA ONE DOWN KURALI ETKİNKEN TAMAMLA.",
["Beneath the Mountain soygununu Death Sentence zorlukta tamamla."] = "BENEATH THE MOUNTAIN SOYGUNUNU DEATH SENTENCE ZORLUKTA TAMAMLA.",
["Beneath the Mountain soygununu Death Wish veya daha yüksek zorlukta tamamla."] = "BENEATH THE MOUNTAIN SOYGUNUNU DEATH WISH VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Beneath the Mountain soygununu MAYHEM veya üzeri zorlukta hiçbir Medic öldürmeden tamamla."] = "BENEATH THE MOUNTAIN SOYGUNUNU MAYHEM VEYA ÜZERİ ZORLUKTA HİÇBİR MEDIC ÖLDÜRMEDEN TAMAMLA.",
["Beneath the Mountain soygununu Mayhem veya daha yüksek zorlukta tamamla."] = "BENEATH THE MOUNTAIN SOYGUNUNU MAYHEM VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Beneath the Mountain soygununu Normal veya daha yüksek zorlukta tamamla."] = "BENEATH THE MOUNTAIN SOYGUNUNU NORMAL VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Beneath the Mountain soygununu OVERKILL veya daha yüksek zorlukta tamamla."] = "BENEATH THE MOUNTAIN SOYGUNUNU OVERKILL VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Beneath the Mountain soygununu Zor veya daha yüksek zorlukta tamamla."] = "BENEATH THE MOUNTAIN SOYGUNUNU ZOR VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Beneath the Mountain soygununu Çok Zor veya daha yüksek zorlukta tamamla."] = "BENEATH THE MOUNTAIN SOYGUNUNU ÇOK ZOR VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Benevolent Bank'e gidiyoruz. Bu kez kasa dairesinin peşinde değiliz; bir rehine alıp onu kurtarmaya çalışan polislerin kendilerini kan revan içinde bırakmasını izleyeceğiz. Soğukkanlı kalın, bu işten güzel para çıkaracağız."] = "BENEVOLENT BANK'E GİDİYORUZ. BU KEZ KASA DAİRESİNİN PEŞİNDE DEĞİLİZ; BİR REHİNE ALIP ONU KURTARMAYA ÇALIŞAN POLİSLERİN KENDİLERİNİ KAN REVAN İÇİNDE BIRAKMASINI İZLEYECEĞİZ. SOĞUKKANLI KALIN, BU İŞTEN GÜZEL PARA ÇIKARACAĞIZ.",
["Benevolent Bank'e gir."] = "BENEVOLENT BANK'E GİR.",
["Benevolent Bank'in geçmişi köklü. ABD'nin en eski bankası. 1812'de İngilizler yağmaladı, İç Savaş altınını tuttu, FDR'nin ilk tahvillerini çıkardı. Hatta on dolarlıkların arkasında bile bulursunuz. Tahmin edin ne oldu: Bunca zamanda hiç başarıyla soyulmadı. ‘Başarıyla.’ Bugün bunu değiştirmeyi deneme sırası sizde. Ön kapıdan gireceksiniz. Lobiden ilerideki kasa dairelerine en iyi geçiş yolunu bulmak için keşif yapın. Onca ganimeti nasıl çıkaracağımıza dair fikirlerim var. Güvenin bana. Tarih yazın millet."] = "BENEVOLENT BANK'İN GEÇMİŞİ KÖKLÜ. ABD'NİN EN ESKİ BANKASI. 1812'DE İNGİLİZLER YAĞMALADI, İÇ SAVAŞ ALTININI TUTTU, FDR'NİN İLK TAHVİLLERİNİ ÇIKARDI. HATTA ON DOLARLIKLARIN ARKASINDA BİLE BULURSUNUZ. TAHMİN EDİN NE OLDU: BUNCA ZAMANDA HİÇ BAŞARIYLA SOYULMADI. ‘BAŞARIYLA.’ BUGÜN BUNU DEĞİŞTİRMEYİ DENEME SIRASI SİZDE. ÖN KAPIDAN GİRECEKSİNİZ. LOBİDEN İLERİDEKİ KASA DAİRELERİNE EN İYİ GEÇİŞ YOLUNU BULMAK İÇİN KEŞİF YAPIN. ONCA GANİMETİ NASIL ÇIKARACAĞIMIZA DAİR FİKİRLERİM VAR. GÜVENİN BANA. TARİH YAZIN MİLLET.",
["Benevolent Bank, 1500 Pennsylvania adresinde. Onu soyacaksınız. Hazırlık hayati önem taşıyor. Planınızı kurun, sonra uygulayın. İnşaatta çalışan bir hastam aracılığıyla bankanın yakınına vinç kurulmasını ayarladım. Kullanmanızı öneririm."] = "BENEVOLENT BANK, 1500 PENNSYLVANİA ADRESİNDE. ONU SOYACAKSINIZ. HAZIRLIK HAYATİ ÖNEM TAŞIYOR. PLANINIZI KURUN, SONRA UYGULAYIN. İNŞAATTA ÇALIŞAN BİR HASTAM ARACILIĞIYLA BANKANIN YAKININA VİNÇ KURULMASINI AYARLADIM. KULLANMANIZI ÖNERİRİM.",
["Benevolent Bank, Washington şehir merkezinde. Bugün önemli bir para çekme işlemi yapacaksınız. Hazırlık her şeydir. Planınızı kurun. Uygulayın. İyi niyet göstergesi olarak bankanın yanına bir vinç hazırlattım. Uygun gördüğünüz şekilde kullanın. Hepsi bu."] = "BENEVOLENT BANK, WASHINGTON ŞEHİR MERKEZİNDE. BUGÜN ÖNEMLİ BİR PARA ÇEKME İŞLEMİ YAPACAKSINIZ. HAZIRLIK HER ŞEYDİR. PLANINIZI KURUN. UYGULAYIN. İYİ NİYET GÖSTERGESİ OLARAK BANKANIN YANINA BİR VİNÇ HAZIRLATTIM. UYGUN GÖRDÜĞÜNÜZ ŞEKİLDE KULLANIN. HEPSİ BU.",
["Benevolent Bank. Neoklasik bir güzellik. Ama iş bizi bekler. Birkaç şifre gerekecek, sunucularına gidin. "] = "BENEVOLENT BANK. NEOKLASİK BİR GÜZELLİK. AMA İŞ BİZİ BEKLER. BİRKAÇ ŞİFRE GEREKECEK, SUNUCULARINA GİDİN. ",
["Beni Bir Kere Kandırırsan Ayıp... Sana Ayıp. Beni Kandır... Bir Daha Kandırılamazsın"] = "BENİ BİR KERE KANDIRIRSAN AYIP... SANA AYIP. BENİ KANDIR... BİR DAHA KANDIRILAMAZSIN",
