["Beni bir telefona bağlayın dostlar."] = "BENİ BİR TELEFONA BAĞLAYIN DOSTLAR.",
["Beni bulabilirseniz denemekte serbestsiniz."] = "BENİ BULABİLİRSENİZ DENEMEKTE SERBESTSİNİZ.",
["Beni burada istedin, geldim. Şu işi bitirelim."] = "BENİ BURADA İSTEDİN, GELDİM. ŞU İŞİ BİTİRELİM.",
