["Beni bırakmazsanız bu iş iyi bitmeyecek."] = "BENİ BIRAKMAZSANIZ BU İŞ İYİ BİTMEYECEK.",
["Beni depo odasının güvenlik kutularına bağlarsanız kapılarını açabilirim."] = "BENİ DEPO ODASININ GÜVENLİK KUTULARINA BAĞLARSANIZ KAPILARINI AÇABİLİRİM.",
["Beni deponun güvenlik panolarına bağlarsanız kapılarının kilidini açabilirim."] = "BENİ DEPONUN GÜVENLİK PANOLARINA BAĞLARSANIZ KAPILARININ KİLİDİNİ AÇABİLİRİM.",
["Beni dinleyin, hayatta kalmanız için kritik bir bilgiye sahibim."] = "BENİ DİNLEYİN, HAYATTA KALMANIZ İÇİN KRİTİK BİR BİLGİYE SAHİBİM.",
