["Beyin sınıfında uzmanlaşmış bir oyuncu, polisleri önce rehine alarak kendi tarafına geçirebilir."] = "BEYİN SINIFINDA UZMANLAŞMIŞ BİR OYUNCU, POLİSLERİ ÖNCE REHİNE ALARAK KENDİ TARAFINA GEÇİREBİLİR.",
["Beyler, C4 çatıda."] = "BEYLER, C4 ÇATIDA.",
["Beyler, DC'de oy verme işlemi başlamak üzere. Birkaç seçmeni doğru tarafa çekmeliyiz. Yardımınız dokunabilir."] = "BEYLER, DC'DE OY VERME İŞLEMİ BAŞLAMAK ÜZERE. BİRKAÇ SEÇMENİ DOĞRU TARAFA ÇEKMELİYİZ. YARDIMINIZ DOKUNABİLİR.",
["Beyler, bir rakibi siyaset sahnesinden silmek için becerikli ellerinize ihtiyacım var. Ödül altın değerinde."] = "BEYLER, BİR RAKİBİ SİYASET SAHNESİNDEN SİLMEK İÇİN BECERİKLİ ELLERİNİZE İHTİYACIM VAR. ÖDÜL ALTIN DEĞERİNDE.",
["Beyler, birinin servetini partimin en iyi... çıkarlarına hizmet edecek şekilde aktarmama yardım etmelisiniz."] = "BEYLER, BİRİNİN SERVETİNİ PARTİMİN EN İYİ... ÇIKARLARINA HİZMET EDECEK ŞEKİLDE AKTARMAMA YARDIM ETMELİSİNİZ.",
["Beyler, birinin servetini partimin en iyi... çıkarlarına hizmet edecek şekilde aktarmamda yardımınıza ihtiyacım var."] = "BEYLER, BİRİNİN SERVETİNİ PARTİMİN EN İYİ... ÇIKARLARINA HİZMET EDECEK ŞEKİLDE AKTARMAMDA YARDIMINIZA İHTİYACIM VAR.",
["Beyler, bugün oy kullanıyoruz. Derler ki: Bir adam, bir oy. Ben diyorum ki: Dört adam, bir sürü oy. Bölgemdeki oy makinelerine hile karıştırmanızı istiyorum."] = "BEYLER, BUGÜN OY KULLANIYORUZ. DERLER Kİ: BİR ADAM, BİR OY. BEN DİYORUM Kİ: DÖRT ADAM, BİR SÜRÜ OY. BÖLGEMDEKİ OY MAKİNELERİNE HİLE KARIŞTIRMANIZI İSTİYORUM.",
["Beyler, dünyayı değiştirme fırsatı sizi bekliyor. Emeğinizin karşılığı olacak!"] = "BEYLER, DÜNYAYI DEĞİŞTİRME FIRSATI SİZİ BEKLİYOR. EMEĞİNİZİN KARŞILIĞI OLACAK!",
["Beyler, enerji politikasının mevcut çizgisini korumak isteyen lobicilerin yardımınıza ihtiyacı var. Gerçekten çok kazançlı. Bence çağrılarına cevap verelim."] = "BEYLER, ENERJİ POLİTİKASININ MEVCUT ÇİZGİSİNİ KORUMAK İSTEYEN LOBİCİLERİN YARDIMINIZA İHTİYACI VAR. GERÇEKTEN ÇOK KAZANÇLI. BENCE ÇAĞRILARINA CEVAP VERELİM.",
["Beyler, havada bir şeyler var sanki... Para!"] = "BEYLER, HAVADA BİR ŞEYLER VAR SANKİ... PARA!",
["Beyler, kafa parçalama aletinizi seçin ve ceset üretmeye başlayın. Yalnız, patlayan cesetlere dikkat edin."] = "BEYLER, KAFA PARÇALAMA ALETİNİZİ SEÇİN VE CESET ÜRETMEYE BAŞLAYIN. YALNIZ, PATLAYAN CESETLERE DİKKAT EDİN.",
["Beyler, kısa süreliğine gelebileceğim bir açıklık görüyorum. Güvene alacak ganimetiniz varsa tam zamanı. Trenin arkasında olacağım."] = "BEYLER, KISA SÜRELİĞİNE GELEBİLECEĞİM BİR AÇIKLIK GÖRÜYORUM. GÜVENE ALACAK GANİMETİNİZ VARSA TAM ZAMANI. TRENİN ARKASINDA OLACAĞIM.",
["Beyler, mevcut enerji politikasını sürdürmek isteyen lobiciler yardımınızı istiyor. Oldukça kârlı bir iş. Bence çağrılarına cevap verelim."] = "BEYLER, MEVCUT ENERJİ POLİTİKASINI SÜRDÜRMEK İSTEYEN LOBİCİLER YARDIMINIZI İSTİYOR. OLDUKÇA KÂRLI BİR İŞ. BENCE ÇAĞRILARINA CEVAP VERELİM.",
["Beyler, mızrağı getirin!"] = "BEYLER, MIZRAĞI GETİRİN!",
["Beyler, ortak dostlarımız oldukça memnun kalmış görünüyor. Bu icadı hızlıca teslim ettiğiniz için teşekkürler. Dünya artık her zamanki işleyişine dönecek."] = "BEYLER, ORTAK DOSTLARIMIZ OLDUKÇA MEMNUN KALMIŞ GÖRÜNÜYOR. BU İCADI HIZLICA TESLİM ETTİĞİNİZ İÇİN TEŞEKKÜRLER. DÜNYA ARTIK HER ZAMANKİ İŞLEYİŞİNE DÖNECEK.",
["Beyler, petrol dünyamızın kanıdır. Onsuz ölürüz. Akmaya devam etmesini sağlama vakti."] = "BEYLER, PETROL DÜNYAMIZIN KANIDIR. ONSUZ ÖLÜRÜZ. AKMAYA DEVAM ETMESİNİ SAĞLAMA VAKTİ.",
["Beyler, petrol dünyamızın kanıdır. Onsuz ölürüz. Akmaya devam ettiğinden emin olma vakti."] = "BEYLER, PETROL DÜNYAMIZIN KANIDIR. ONSUZ ÖLÜRÜZ. AKMAYA DEVAM ETTİĞİNDEN EMİN OLMA VAKTİ.",
