["Bir engel daha. Güvenlik kilidi devrede. Sunucu odasındaki ana bilgisayara gidip sızın, tamam mı?"] = "BİR ENGEL DAHA. GÜVENLİK KİLİDİ DEVREDE. SUNUCU ODASINDAKİ ANA BİLGİSAYARA GİDİP SIZIN, TAMAM MI?",
["Bir engeli termitle eritip geçmek asla eskimez. O madde fena eğlencelidir. Ama aynı aptal polisleri tekrar tekrar dövmek sıkar. Yine de sonuna kadar gitmek gerek. Bu adamlar bir türlü yerde kalmıyor."] = "BİR ENGELİ TERMİTLE ERİTİP GEÇMEK ASLA ESKİMEZ. O MADDE FENA EĞLENCELİDİR. AMA AYNI APTAL POLİSLERİ TEKRAR TEKRAR DÖVMEK SIKAR. YİNE DE SONUNA KADAR GİTMEK GEREK. BU ADAMLAR BİR TÜRLÜ YERDE KALMIYOR.",
["Bir fail yakalandı, tamam."] = "BİR FAİL YAKALANDI, TAMAM.",
["Bir fikir: Buluc'un araba dolu garajı var. Belki biriyle tareti indirebilirsiniz."] = "BİR FİKİR: BULUC'UN ARABA DOLU GARAJI VAR. BELKİ BİRİYLE TARETİ İNDİREBİLİRSİNİZ.",
["Bir fikrim var. Ana sisteme sızalım. Birkaç koruma katmanı olsa bile muhtemelen girebiliriz."] = "BİR FİKRİM VAR. ANA SİSTEME SIZALIM. BİRKAÇ KORUMA KATMANI OLSA BİLE MUHTEMELEN GİREBİLİRİZ.",
["Bir fikrim var. Telefon numarası bende. Arayıp dikkatini dağıtacağım. Siz bardağını doldurmaya hazır olun."] = "BİR FİKRİM VAR. TELEFON NUMARASI BENDE. ARAYIP DİKKATİNİ DAĞITACAĞIM. SİZ BARDAĞINI DOLDURMAYA HAZIR OLUN.",
["Bir ganimet çantasını asansör boşluğundaki çelik halata bağla. Locke onu güvende tutacak."] = "BİR GANİMET ÇANTASINI ASANSÖR BOŞLUĞUNDAKİ ÇELİK HALATA BAĞLA. LOCKE ONU GÜVENDE TUTACAK.",
["Bir gazetenin içine anahtar kart gizlenecek"] = "BİR GAZETENİN İÇİNE ANAHTAR KART GİZLENECEK",
["Bir geçiş kartı mı yolluyor? Ne demek bu?"] = "BİR GEÇİŞ KARTI MI YOLLUYOR? NE DEMEK BU?",
["Bir giriş merdiveni, kapağın kilidi de açık. Bu dikkatsiz pislikler soyulmayı hak ediyor."] = "BİR GİRİŞ MERDİVENİ, KAPAĞIN KİLİDİ DE AÇIK. BU DİKKATSİZ PİSLİKLER SOYULMAYI HAK EDİYOR.",
["Bir gülümseme en ölümcül düşünceyi saklayabilir ama gözler asla yalan söylemez. Birini okumak, çoğunlukla doğrudan gözlerine bakmaktır. Asıl korkunç olan, düşünceleri yüzüne yansıyan insanlardır; bakan kişi bir saniye içinde çığlığını bastırmakta zorlanır."] = "BİR GÜLÜMSEME EN ÖLÜMCÜL DÜŞÜNCEYİ SAKLAYABİLİR AMA GÖZLER ASLA YALAN SÖYLEMEZ. BİRİNİ OKUMAK, ÇOĞUNLUKLA DOĞRUDAN GÖZLERİNE BAKMAKTIR. ASIL KORKUNÇ OLAN, DÜŞÜNCELERİ YÜZÜNE YANSIYAN İNSANLARDIR; BAKAN KİŞİ BİR SANİYE İÇİNDE ÇIĞLIĞINI BASTIRMAKTA ZORLANIR.",
["Bir gün bunun filmini yazacağım. Belki dizi olur."] = "BİR GÜN BUNUN FİLMİNİ YAZACAĞIM. BELKİ DİZİ OLUR.",
["Bir gün için bu kadar şirket casusluğu yeter! Çıkma vakti."] = "BİR GÜN İÇİN BU KADAR ŞİRKET CASUSLUĞU YETER! ÇIKMA VAKTİ.",
["Bir güvenlik duvarı kaldı."] = "BİR GÜVENLİK DUVARI KALDI.",
["Bir güvenlik görevlisinden anahtarı al ve güvenlik odasına gir."] = "BİR GÜVENLİK GÖREVLİSİNDEN ANAHTARI AL VE GÜVENLİK ODASINA GİR.",
["Bir güvenlik kilidi devresi kızardı. Yukarı çıkın!"] = "BİR GÜVENLİK KİLİDİ DEVRESİ KIZARDI. YUKARI ÇIKIN!",
["Bir güvenlik kutusu bulup sistem kırma cihazını takmalısınız. Böylece sisteme kaba kuvvet saldırısı yapabilirim. Kimse kurcalamasın diye koruyun."] = "BİR GÜVENLİK KUTUSU BULUP SİSTEM KIRMA CİHAZINI TAKMALISINIZ. BÖYLECE SİSTEME KABA KUVVET SALDIRISI YAPABİLİRİM. KİMSE KURCALAMASIN DİYE KORUYUN.",
["Bir güvenlik kutusu tamam."] = "BİR GÜVENLİK KUTUSU TAMAM.",
["Bir güvenlik önlemini tetiklemiş olmalısınız. Çıkmak için matkap kullanın!"] = "BİR GÜVENLİK ÖNLEMİNİ TETİKLEMİŞ OLMALISINIZ. ÇIKMAK İÇİN MATKAP KULLANIN!",
["Bir hademe yönetici ofisinin kapısını kapatmayı unutmuş. Şanslısın."] = "BİR HADEME YÖNETİCİ OFİSİNİN KAPISINI KAPATMAYI UNUTMUŞ. ŞANSLISIN.",
["Bir hademeye pencereyi açık bırakması için rüşvet verildi"] = "BİR HADEMEYE PENCEREYİ AÇIK BIRAKMASI İÇİN RÜŞVET VERİLDİ",
["Bir hafta süren, fazla ileri gitmiş bir Vegas âleminin hüzünlü (ve komik) kalıntısı. Kötü şansın ve kötü hayat kararlarının gücüyle polisleri patakla."] = "BİR HAFTA SÜREN, FAZLA İLERİ GİTMİŞ BİR VEGAS ÂLEMİNİN HÜZÜNLÜ (VE KOMİK) KALINTISI. KÖTÜ ŞANSIN VE KÖTÜ HAYAT KARARLARININ GÜCÜYLE POLİSLERİ PATAKLA.",
["Bir hain var. Ekibe yakın. Ya da içimizde. Var, biliyorum."] = "BİR HAİN VAR. EKİBE YAKIN. YA DA İÇİMİZDE. VAR, BİLİYORUM.",
["Bir hamle, sonra bir hamle daha. Rakibin hamle yapar, sen karşılık verirsin. Altın dağının tepesinde duruyor, gelip meydan okumasını kabul etmen için sana kafa tutuyor. Bu maskeyi takarak boyun eğmediğini ilan edersin; oyun sürer, rekabet bitmez."] = "BİR HAMLE, SONRA BİR HAMLE DAHA. RAKİBİN HAMLE YAPAR, SEN KARŞILIK VERİRSİN. ALTIN DAĞININ TEPESİNDE DURUYOR, GELİP MEYDAN OKUMASINI KABUL ETMEN İÇİN SANA KAFA TUTUYOR. BU MASKEYİ TAKARAK BOYUN EĞMEDİĞİNİ İLAN EDERSİN; OYUN SÜRER, REKABET BİTMEZ.",
["Bir hece daha söylemem!"] = "BİR HECE DAHA SÖYLEMEM!",
["Bir hedef görürsen hareketlerini takip etmek için onu \"işaretleyebilirsin\"."] = "BİR HEDEF GÖRÜRSEN HAREKETLERİNİ TAKİP ETMEK İÇİN ONU \"İŞARETLEYEBİLİRSİN\".",
["Bir helikopter ayarlamaya çalışacağım."] = "BİR HELİKOPTER AYARLAMAYA ÇALIŞACAĞIM.",
["Bir helikopter yaklaşıyor. Lanet olsun, Alex'i görecekler!"] = "BİR HELİKOPTER YAKLAŞIYOR. LANET OLSUN, ALEX'İ GÖRECEKLER!",
["Bir helikopter yola çıkardım. Ganimeti çatıya taşımaya başlayın."] = "BİR HELİKOPTER YOLA ÇIKARDIM. GANİMETİ ÇATIYA TAŞIMAYA BAŞLAYIN.",
["Bir helikopter, inşaat alanının duvarını açmak için gereken C4'ü bırakacak."] = "BİR HELİKOPTER, İNŞAAT ALANININ DUVARINI AÇMAK İÇİN GEREKEN C4'Ü BIRAKACAK.",
["Bir iki saniyeye açılır. Sonra da... "] = "BİR İKİ SANİYEYE AÇILIR. SONRA DA... ",
["Bir iki vezneyi vuralım. Bir bankayı çantalayalım."] = "BİR İKİ VEZNEYİ VURALIM. BİR BANKAYI ÇANTALAYALIM.",
["Bir ilk yardım dolabı. Çünkü tıp mesleğini önemsiyoruz."] = "BİR İLK YARDIM DOLABI. ÇÜNKÜ TIP MESLEĞİNİ ÖNEMSİYORUZ.",
["Bir insanın dişlerine nasıl baktığı, onun hakkında çok şey söyler. Bu sayede insan sarrafı sayılırım."] = "BİR İNSANIN DİŞLERİNE NASIL BAKTIĞI, ONUN HAKKINDA ÇOK ŞEY SÖYLER. BU SAYEDE İNSAN SARRAFI SAYILIRIM.",
["Bir içkiden daha ne çıkar?"] = "BİR İÇKİDEN DAHA NE ÇIKAR?",
["Bir işaret fişeği yakın!"] = "BİR İŞARET FİŞEĞİ YAKIN!",
["Bir işçinin el telsizini ele geçirebilir misiniz? İkinci kapıyı parmağımızı oynatmadan geçebiliriz belki."] = "BİR İŞÇİNİN EL TELSİZİNİ ELE GEÇİREBİLİR MİSİNİZ? İKİNCİ KAPIYI PARMAĞIMIZI OYNATMADAN GEÇEBİLİRİZ BELKİ.",
["Bir kabin banyosuna saklanmış evrak çantasında güncel istihbarat alacaktık. Gidip arayın."] = "BİR KABİN BANYOSUNA SAKLANMIŞ EVRAK ÇANTASINDA GÜNCEL İSTİHBARAT ALACAKTIK. GİDİP ARAYIN.",
["Bir kahve fincanı arayın. Bütün müdürler kahve içer. Ben öyle duydum."] = "BİR KAHVE FİNCANI ARAYIN. BÜTÜN MÜDÜRLER KAHVE İÇER. BEN ÖYLE DUYDUM.",
["Bir kamera şüpheli bir hareket görürse alarmın önüne geçemezsin."] = "BİR KAMERA ŞÜPHELİ BİR HAREKET GÖRÜRSE ALARMIN ÖNÜNE GEÇEMEZSİN.",
["Bir kamyon açıldı! İçine bakın!"] = "BİR KAMYON AÇILDI! İÇİNE BAKIN!",
["Bir kapı daha. Muhafızlara ve kameralara dikkat edin millet..."] = "BİR KAPI DAHA. MUHAFIZLARA VE KAMERALARA DİKKAT EDİN MİLLET...",
["Bir kapı kaldı, sonra sunucuyu alıyoruz. FBI altına sıçacak."] = "BİR KAPI KALDI, SONRA SUNUCUYU ALIYORUZ. FBI ALTINA SIÇACAK.",
["Bir kapı olmalı, değil mi?"] = "BİR KAPI OLMALI, DEĞİL Mİ?",
["Bir kapı ya da pencere açar açmaz alarm sayacı başlayacak. Alarmı devre dışı bırakmanız için birkaç saniyeniz olacak."] = "BİR KAPI YA DA PENCERE AÇAR AÇMAZ ALARM SAYACI BAŞLAYACAK. ALARMI DEVRE DIŞI BIRAKMANIZ İÇİN BİRKAÇ SANİYENİZ OLACAK.",
["Bir kar fırtınasının yaklaştığını hissediyorsun..."] = "BİR KAR FIRTINASININ YAKLAŞTIĞINI HİSSEDİYORSUN...",
["Bir karakol için olabilecek en çetin yerlerden biri burası."] = "BİR KARAKOL İÇİN OLABİLECEK EN ÇETİN YERLERDEN BİRİ BURASI.",
["Bir karar verin ve ilerleyin."] = "BİR KARAR VERİN VE İLERLEYİN.",
["Bir kart okutuldu ama Kasa Dairesi iki tane istiyor. Aramaya devam edin."] = "BİR KART OKUTULDU AMA KASA DAİRESİ İKİ TANE İSTİYOR. ARAMAYA DEVAM EDİN.",
["Bir kart okuyucu var gibi. Buralarda bir yerde Anahtar Kartı olmalı."] = "BİR KART OKUYUCU VAR GİBİ. BURALARDA BİR YERDE ANAHTAR KARTI OLMALI.",
["Bir kart seç"] = "BİR KART SEÇ",
["Bir kasa dairesi daha açılıyor. Bravo!"] = "BİR KASA DAİRESİ DAHA AÇILIYOR. BRAVO!",
["Bir kasa dairesinin planları. İlginç."] = "BİR KASA DAİRESİNİN PLANLARI. İLGİNÇ.",
["Bir kasaya girmek için gereken tüm plan ve emeği düşününce, buna değmesi için olabildiğince fazla altın çıkarmak iyi bir fikirdir."] = "BİR KASAYA GİRMEK İÇİN GEREKEN TÜM PLAN VE EMEĞİ DÜŞÜNÜNCE, BUNA DEĞMESİ İÇİN OLABİLDİĞİNCE FAZLA ALTIN ÇIKARMAK İYİ BİR FİKİRDİR.",
["Bir kaynak lambası bul"] = "BİR KAYNAK LAMBASI BUL",
["Bir kaçakçılık operasyonunu dağıtmanızı istiyorum. Kokaini alın. Sadece küçük bir pürüz var..."] = "BİR KAÇAKÇILIK OPERASYONUNU DAĞITMANIZI İSTİYORUM. KOKAİNİ ALIN. SADECE KÜÇÜK BİR PÜRÜZ VAR...",
["Bir kedi kadar çevik, onun kadar da şanslı olarak her soyguna cesaret eder, her savunmayı aşarsın. İşler sarpa sardığında hep sıyrılır, dört ayak üstüne düşersin. Dokuz canını harcamanın daha iyi bir yolu yok; sen soğukkanlı bir katilsin, herkes de biliyor."] = "BİR KEDİ KADAR ÇEVİK, ONUN KADAR DA ŞANSLI OLARAK HER SOYGUNA CESARET EDER, HER SAVUNMAYI AŞARSIN. İŞLER SARPA SARDIĞINDA HEP SIYRILIR, DÖRT AYAK ÜSTÜNE DÜŞERSİN. DOKUZ CANINI HARCAMANIN DAHA İYİ BİR YOLU YOK; SEN SOĞUKKANLI BİR KATİLSİN, HERKES DE BİLİYOR.",
["Bir kere olsun bu işi polissiz yaparız diye ummuştum."] = "BİR KERE OLSUN BU İŞİ POLİSSİZ YAPARIZ DİYE UMMUŞTUM.",
["Bir kere yaptık, yine yaparız. İçeri girip o sanat eserlerini aşırın palyaçolar."] = "BİR KERE YAPTIK, YİNE YAPARIZ. İÇERİ GİRİP O SANAT ESERLERİNİ AŞIRIN PALYAÇOLAR.",
["Bir keresinde Beyaz Saray'ı gezdiğimi biliyor muydunuz? Mobilyaları berbat ötesi, değil mi?"] = "BİR KERESİNDE BEYAZ SARAY'I GEZDİĞİMİ BİLİYOR MUYDUNUZ? MOBİLYALARI BERBAT ÖTESİ, DEĞİL Mİ?",
["Bir keresinde Sangres, Brezilya ile Meksika arasında uçakla çalıntı silah taşınmasına eşlik ediyordu. Bu takımı giyen ortağı uçuş sırasında ona ihanet etti. Kısa bir boğuşmanın ardından Sangres onu kargo kapısından dışarı tekmeledi. Artık eski olan ortağı kollarını çılgınca savurup çığlıklarla düşerken Sangres, takımın mavisinin parlak mavi gökyüzünde ne kadar iyi kamuflaj olduğunu fark etmeden edemedi. Sonra yere \"şlap\" diye çarptı ve görüntü bozuldu."] = "BİR KERESİNDE SANGRES, BREZİLYA İLE MEKSİKA ARASINDA UÇAKLA ÇALINTI SİLAH TAŞINMASINA EŞLİK EDİYORDU. BU TAKIMI GİYEN ORTAĞI UÇUŞ SIRASINDA ONA İHANET ETTİ. KISA BİR BOĞUŞMANIN ARDINDAN SANGRES ONU KARGO KAPISINDAN DIŞARI TEKMELEDİ. ARTIK ESKİ OLAN ORTAĞI KOLLARINI ÇILGINCA SAVURUP ÇIĞLIKLARLA DÜŞERKEN SANGRES, TAKIMIN MAVİSİNİN PARLAK MAVİ GÖKYÜZÜNDE NE KADAR İYİ KAMUFLAJ OLDUĞUNU FARK ETMEDEN EDEMEDİ. SONRA YERE \"ŞLAP\" DİYE ÇARPTI VE GÖRÜNTÜ BOZULDU.",
["Bir keskin nişancı ekibi geliyor!"] = "BİR KESKİN NİŞANCI EKİBİ GELİYOR!",
["Bir keskin nişancı ekibi yaklaşıyor!"] = "BİR KESKİN NİŞANCI EKİBİ YAKLAŞIYOR!",
["Bir keskin nişancı otoyolun diğer tarafındaki çatıya mevzilenmeye gidiyor. Sizi durdurmasına izin vermeyin."] = "BİR KESKİN NİŞANCI OTOYOLUN DİĞER TARAFINDAKİ ÇATIYA MEVZİLENMEYE GİDİYOR. SİZİ DURDURMASINA İZİN VERMEYİN.",
["Bir keskin nişancı tüfeği. Bazıları bununla neler yapılabileceğini gerçekten hafife alıyor."] = "BİR KESKİN NİŞANCI TÜFEĞİ. BAZILARI BUNUNLA NELER YAPILABİLECEĞİNİ GERÇEKTEN HAFİFE ALIYOR.",
["Bir kez daha"] = "BİR KEZ DAHA",
["Bir kez daha, dostlarım, bana büyük hizmet ettiniz. Buluc artık balıkların bokuna dönüştüğüne göre Coyopa'ların işi bitti sanıyorum. Dentist'in de Meksika'da yardımı kalmadı, çaresiz ve savunmasız olacak. Sıradaki işiniz her neyse size daha kolay gelmeli. Vlad'i unutmayın yeter, tamam mı? Çok şey oluyor, ileride bizim için tehlikeli olabilecek şeyler. Ama daha çok konuşacağız... Yakında. Şerefe, hoşça kalın."] = "BİR KEZ DAHA, DOSTLARIM, BANA BÜYÜK HİZMET ETTİNİZ. BULUC ARTIK BALIKLARIN BOKUNA DÖNÜŞTÜĞÜNE GÖRE COYOPA'LARIN İŞİ BİTTİ SANIYORUM. DENTİST'İN DE MEKSİKA'DA YARDIMI KALMADI, ÇARESİZ VE SAVUNMASIZ OLACAK. SIRADAKİ İŞİNİZ HER NEYSE SİZE DAHA KOLAY GELMELİ. VLAD'İ UNUTMAYIN YETER, TAMAM MI? ÇOK ŞEY OLUYOR, İLERİDE BİZİM İÇİN TEHLİKELİ OLABİLECEK ŞEYLER. AMA DAHA ÇOK KONUŞACAĞIZ... YAKINDA. ŞEREFE, HOŞÇA KALIN.",
["Bir kez daha, kod..."] = "BİR KEZ DAHA, KOD...",
["Bir kez daha. Şans bizden yana olsun."] = "BİR KEZ DAHA. ŞANS BİZDEN YANA OLSUN.",
["Bir kez daha: Gizlice girin, kameralara, muhafızlara ve diğer bütün alarmlara dikkat edin. Hızlı ama dikkatli girin. İşi gevşetmeyin."] = "BİR KEZ DAHA: GİZLİCE GİRİN, KAMERALARA, MUHAFIZLARA VE DİĞER BÜTÜN ALARMLARA DİKKAT EDİN. HIZLI AMA DİKKATLİ GİRİN. İŞİ GEVŞETMEYİN.",
["Bir kez olsun polissiz yaparız diye ummuştum."] = "BİR KEZ OLSUN POLİSSİZ YAPARIZ DİYE UMMUŞTUM.",
["Bir keçi daha güvene alındı."] = "BİR KEÇİ DAHA GÜVENE ALINDI.",
["Bir keçi yukarıdaki daireye girdi. Peşine düşün! İçeri girmenin bir yolunu arayın."] = "BİR KEÇİ YUKARIDAKİ DAİREYE GİRDİ. PEŞİNE DÜŞÜN! İÇERİ GİRMENİN BİR YOLUNU ARAYIN.",
["Bir kilit daha kaldı."] = "BİR KİLİT DAHA KALDI.",
["Bir kişinin ne kadar taşıyabildiğine şaşırırsın. Kasaya kaç kez gidip gelmeye dayanabilirsin?"] = "BİR KİŞİNİN NE KADAR TAŞIYABİLDİĞİNE ŞAŞIRIRSIN. KASAYA KAÇ KEZ GİDİP GELMEYE DAYANABİLİRSİN?",
["Bir komşu sizi gördü. 911'i aradı."] = "BİR KOMŞU SİZİ GÖRDÜ. 911'İ ARADI.",
["Bir konteynere benzin bidonu yerleştir."] = "BİR KONTEYNERE BENZİN BİDONU YERLEŞTİR.",
["Bir kumarhanenin güvenlik seviyesi genellikle içindeki servetin büyüklüğünü yansıtır. The Golden Grin Casino, Strip'teki en güvenli kumarhanedir."] = "BİR KUMARHANENİN GÜVENLİK SEVİYESİ GENELLİKLE İÇİNDEKİ SERVETİN BÜYÜKLÜĞÜNÜ YANSITIR. THE GOLDEN GRIN CASINO, STRİP'TEKİ EN GÜVENLİ KUMARHANEDİR.",
["Bir kutu daha kaldı. Ana bilgisayara dönüp arayın, tamam mı?"] = "BİR KUTU DAHA KALDI. ANA BİLGİSAYARA DÖNÜP ARAYIN, TAMAM MI?",
["Bir kutu tamam, bir tane kaldı."] = "BİR KUTU TAMAM, BİR TANE KALDI.",
["Bir kutuyu daha devre dışı bırakmak yeterli olmalı."] = "BİR KUTUYU DAHA DEVRE DIŞI BIRAKMAK YETERLİ OLMALI.",
["Bir kuş, Mendoza'ların Hector'la savaşa hazırlanırken uçakla daha fazla silah getirdiğini söyledi. Havaalanlarına gidip silahları bulacağız. Ya hepsini alacağız ya yok edeceğiz."] = "BİR KUŞ, MENDOZA'LARIN HECTOR'LA SAVAŞA HAZIRLANIRKEN UÇAKLA DAHA FAZLA SİLAH GETİRDİĞİNİ SÖYLEDİ. HAVAALANLARINA GİDİP SİLAHLARI BULACAĞIZ. YA HEPSİNİ ALACAĞIZ YA YOK EDECEĞİZ.",
["Bir kırmızı ışık geçeyim, oradayım!"] = "BİR KIRMIZI IŞIK GEÇEYİM, ORADAYIM!",
["Bir lastik yığınını yakıp dumanıyla helikopterin görüşünü kapat!"] = "BİR LASTİK YIĞININI YAKIP DUMANIYLA HELİKOPTERİN GÖRÜŞÜNÜ KAPAT!",
["Bir levye bulmaya çalışın."] = "BİR LEVYE BULMAYA ÇALIŞIN.",
["Bir levye bulup sandıkları açın ama dikkat edin. Jiu Feng genelde tuzaklı olduklarını söyledi!"] = "BİR LEVYE BULUP SANDIKLARI AÇIN AMA DİKKAT EDİN. JIU FENG GENELDE TUZAKLI OLDUKLARINI SÖYLEDİ!",
["Bir levye. İyi buldunuz. Her zaman işe yarar."] = "BİR LEVYE. İYİ BULDUNUZ. HER ZAMAN İŞE YARAR.",
["Bir lider olarak kariyeri boyunca çok şeyden vazgeçmek zorunda kaldı. İşler, ekip üyeleri, kişisel hedefler; işi bitirmek için ne gerekiyorsa. Mezoamerika kültürleri tanrıları hoşnut etmek için nasıl kurban verdiyse Dallas da soygun tanrılarına, yani işverenlere öyle kurbanlar verdi."] = "BİR LİDER OLARAK KARİYERİ BOYUNCA ÇOK ŞEYDEN VAZGEÇMEK ZORUNDA KALDI. İŞLER, EKİP ÜYELERİ, KİŞİSEL HEDEFLER; İŞİ BİTİRMEK İÇİN NE GEREKİYORSA. MEZOAMERİKA KÜLTÜRLERİ TANRILARI HOŞNUT ETMEK İÇİN NASIL KURBAN VERDİYSE DALLAS DA SOYGUN TANRILARINA, YANİ İŞVERENLERE ÖYLE KURBANLAR VERDİ.",
["Bir limuzin güvenliği yarıp geçecek. Maskeli ve silahlı olarak inin."] = "BİR LİMUZİN GÜVENLİĞİ YARIP GEÇECEK. MASKELİ VE SİLAHLI OLARAK İNİN.",
["Bir limuzin güvenliği yarıp geçecek. Maskeli ve silahlı olarak inin. Limuzinde C4 bulunacak."] = "BİR LİMUZİN GÜVENLİĞİ YARIP GEÇECEK. MASKELİ VE SİLAHLI OLARAK İNİN. LİMUZİNDE C4 BULUNACAK.",
["Bir limuzin seni dışarıda bırakacak. Ekipmanın veya masken olmayacak."] = "BİR LİMUZİN SENİ DIŞARIDA BIRAKACAK. EKİPMANIN VEYA MASKEN OLMAYACAK.",
["Bir lokomotiften daha güçlü kimdir? Onu yöneten kişi. Trenin ne zaman kalkacağına, ne kadar hızlı gideceğine, biri için duracaksa kimin için duracağına sen karar verirsin. İstesen bütün operasyonu raydan çıkarabilirsin ama yapmıyorsun. Seni başa bu yüzden koydular."] = "BİR LOKOMOTİFTEN DAHA GÜÇLÜ KİMDİR? ONU YÖNETEN KİŞİ. TRENİN NE ZAMAN KALKACAĞINA, NE KADAR HIZLI GİDECEĞİNE, BİRİ İÇİN DURACAKSA KİMİN İÇİN DURACAĞINA SEN KARAR VERİRSİN. İSTESEN BÜTÜN OPERASYONU RAYDAN ÇIKARABİLİRSİN AMA YAPMIYORSUN. SENİ BAŞA BU YÜZDEN KOYDULAR.",
["Bir mafya adamı daha halledildi. Devam edin."] = "BİR MAFYA ADAMI DAHA HALLEDİLDİ. DEVAM EDİN.",
["Bir mafya adamının elinde nükleer savaş başlıkları mı? Sorma. Vlad bir üst seviyeye çıkmana yardım etmeye hazır. Kartellerle bağlantı kurmanı sağlayabileceğini söylüyor ama federaller kayıp savaş başlıkları için sokakları didik didik ediyor. Bırak seni bulmak için DC’yi söksünler. Vlad’ın başka bir işi var ve bu acil. LA’e git; hızlı."] = "BİR MAFYA ADAMININ ELİNDE NÜKLEER SAVAŞ BAŞLIKLARI MI? SORMA. VLAD BİR ÜST SEVİYEYE ÇIKMANA YARDIM ETMEYE HAZIR. KARTELLERLE BAĞLANTI KURMANI SAĞLAYABİLECEĞİNİ SÖYLÜYOR AMA FEDERALLER KAYIP SAVAŞ BAŞLIKLARI İÇİN SOKAKLARI DİDİK DİDİK EDİYOR. BIRAK SENİ BULMAK İÇİN DC’Yİ SÖKSÜNLER. VLAD’IN BAŞKA BİR İŞİ VAR VE BU ACİL. LA’E GİT; HIZLI.",
["Bir malzeme eklemelisiniz. Yanlış olanı kullanmayın sakın. Tek bir yanlış adımda laboratuvar Noel ağacı gibi alev alır."] = "BİR MALZEME EKLEMELİSİNİZ. YANLIŞ OLANI KULLANMAYIN SAKIN. TEK BİR YANLIŞ ADIMDA LABORATUVAR NOEL AĞACI GİBİ ALEV ALIR.",
["Bir malzeme eklemeniz gerekiyor, yanlış olanı kullanmadığınızdan emin olun. Tek bir yanlış adımda laboratuvar Noel ağacı gibi alev alır."] = "BİR MALZEME EKLEMENİZ GEREKİYOR, YANLIŞ OLANI KULLANMADIĞINIZDAN EMİN OLUN. TEK BİR YANLIŞ ADIMDA LABORATUVAR NOEL AĞACI GİBİ ALEV ALIR.",
["Bir matkap bu kapıyı çabucak açar. Bir tane bulmaya çalışın."] = "BİR MATKAP BU KAPIYI ÇABUCAK AÇAR. BİR TANE BULMAYA ÇALIŞIN.",
["Bir matkap kurun, tamam mı?"] = "BİR MATKAP KURUN, TAMAM MI?",
["Bir merdiven yardımıyla ana binaya gizlice gir."] = "BİR MERDİVEN YARDIMIYLA ANA BİNAYA GİZLİCE GİR.",
["Bir meselede yardımınıza ihtiyacım var..."] = "BİR MESELEDE YARDIMINIZA İHTİYACIM VAR...",
["Bir metamfetamin fabrikası! Yakın orayı. Ya da bir formül bulabilirseniz pişirmeye başlayın. Fazladan malı her zaman satarız."] = "BİR METAMFETAMİN FABRİKASI! YAKIN ORAYI. YA DA BİR FORMÜL BULABİLİRSENİZ PİŞİRMEYE BAŞLAYIN. FAZLADAN MALI HER ZAMAN SATARIZ.",
["Bir motorcudan sessiz olmasını isteyebilirsin ama onu buna zorlayamazsın."] = "BİR MOTORCUDAN SESSİZ OLMASINI İSTEYEBİLİRSİN AMA ONU BUNA ZORLAYAMAZSIN.",
["Bir muhafız daha var. Gözden uzak dur."] = "BİR MUHAFIZ DAHA VAR. GÖZDEN UZAK DUR.",
["Bir muhafız daha. Gizli kalın."] = "BİR MUHAFIZ DAHA. GİZLİ KALIN.",
["Bir muhafızı indirirseniz fark edilmesin diye cesedini trenin altına saklayabilirsiniz."] = "BİR MUHAFIZI İNDİRİRSENİZ FARK EDİLMESİN DİYE CESEDİNİ TRENİN ALTINA SAKLAYABİLİRSİNİZ.",
["Bir nesne olması dışında tam olarak ne aradığımızı bilmiyoruz. Muhtemelen görünce anlayacağımız türden bir şey. Ama Garrett onu kanıt deposundan alıp ofisinde bir yere saklamış olabilir. İçerideki bağlantım, orada olduğunu ve... dikkati dağınık göründüğünü söyledi. Buluşma kesinlikle yakın. Eşyayı burnunun dibinden çalma şansımız olsun istiyorsak hemen gizlice girmeliyiz. İçeri sessizce girip sessiz kalmamız önemli. Garrett'ı da öldürmeyin; o salağa muhtemelen sonra ihtiyacımız olacak."] = "BİR NESNE OLMASI DIŞINDA TAM OLARAK NE ARADIĞIMIZI BİLMİYORUZ. MUHTEMELEN GÖRÜNCE ANLAYACAĞIMIZ TÜRDEN BİR ŞEY. AMA GARRETT ONU KANIT DEPOSUNDAN ALIP OFİSİNDE BİR YERE SAKLAMIŞ OLABİLİR. İÇERİDEKİ BAĞLANTIM, ORADA OLDUĞUNU VE... DİKKATİ DAĞINIK GÖRÜNDÜĞÜNÜ SÖYLEDİ. BULUŞMA KESİNLİKLE YAKIN. EŞYAYI BURNUNUN DİBİNDEN ÇALMA ŞANSIMIZ OLSUN İSTİYORSAK HEMEN GİZLİCE GİRMELİYİZ. İÇERİ SESSİZCE GİRİP SESSİZ KALMAMIZ ÖNEMLİ. GARRETT'I DA ÖLDÜRMEYİN; O SALAĞA MUHTEMELEN SONRA İHTİYACIMIZ OLACAK.",
["Bir numara."] = "BİR NUMARA.",
["Bir odayı geliştirmeye yetecek kadar sikken var!"] = "BİR ODAYI GELİŞTİRMEYE YETECEK KADAR SİKKEN VAR!",
["Bir okulu bombaladı. İyi ki geberdi."] = "BİR OKULU BOMBALADI. İYİ Kİ GEBERDİ.",
