["Bir oyun oynamak ister misiniz? Met pişirme oyunu?"] = "BİR OYUN OYNAMAK İSTER MİSİNİZ? MET PİŞİRME OYUNU?",
["Bir oyuna katıldığında çalması için seçebileceğin kötü şöhretli bir katılma melodisi. Böyle destansı bir girişi ancak en deneyimli soyguncular yapabilir."] = "BİR OYUNA KATILDIĞINDA ÇALMASI İÇİN SEÇEBİLECEĞİN KÖTÜ ŞÖHRETLİ BİR KATILMA MELODİSİ. BÖYLE DESTANSI BİR GİRİŞİ ANCAK EN DENEYİMLİ SOYGUNCULAR YAPABİLİR.",
["Bir paket daha yere düştü, palyaçolar. Bulmaya çalışın."] = "BİR PAKET DAHA YERE DÜŞTÜ, PALYAÇOLAR. BULMAYA ÇALIŞIN.",
["Bir parti daha tamam!"] = "BİR PARTİ DAHA TAMAM!",
["Bir parti tamam."] = "BİR PARTİ TAMAM.",
["Bir parça toplandı. Tamirciye götürün."] = "BİR PARÇA TOPLANDI. TAMİRCİYE GÖTÜRÜN.",
["Bir parçası kaldıysa belki şu avizeyi Vlad için çalarsınız, ha?"] = "BİR PARÇASI KALDIYSA BELKİ ŞU AVİZEYİ VLAD İÇİN ÇALARSINIZ, HA?",
["Bir pencereyi kırarsan, geçen muhafızları ve sivilleri kandırmak için onu kapatacak tahtalar bulmaya çalış."] = "BİR PENCEREYİ KIRARSAN, GEÇEN MUHAFIZLARI VE SİVİLLERİ KANDIRMAK İÇİN ONU KAPATACAK TAHTALAR BULMAYA ÇALIŞ.",
["Bir personelden anahtarı al ve alt güvertedeki yük odasına gizlenmiş matkabı bul."] = "BİR PERSONELDEN ANAHTARI AL VE ALT GÜVERTEDEKİ YÜK ODASINA GİZLENMİŞ MATKABI BUL.",
["Bir polis bile suça yönlendirilebilir. Bain’e sor. Dragan’a sor."] = "BİR POLİS BİLE SUÇA YÖNLENDİRİLEBİLİR. BAIN’E SOR. DRAGAN’A SOR.",
["Bir polis dalgası daha geliyor!"] = "BİR POLİS DALGASI DAHA GELİYOR!",
["Bir polis devriyesine çağrı yakaladım. Her şeyin yolunda olduğunu kontrol etmeleri istenmiş. Yoldalar."] = "BİR POLİS DEVRİYESİNE ÇAĞRI YAKALADIM. HER ŞEYİN YOLUNDA OLDUĞUNU KONTROL ETMELERİ İSTENMİŞ. YOLDALAR.",
["Bir polis helikopteri geliyor. Onu halletmelisiniz."] = "BİR POLİS HELİKOPTERİ GELİYOR. ONU HALLETMELİSİNİZ.",
["Bir polisi kolayca teslim almak için, ona bağırmadan önce biraz hasar vermeyi dene."] = "BİR POLİSİ KOLAYCA TESLİM ALMAK İÇİN, ONA BAĞIRMADAN ÖNCE BİRAZ HASAR VERMEYİ DENE.",
["Bir polisi teslim olmaya zorlayıp rehine almak için \"Bağır/Etkileşime Gir\" tuşuna basabilirsin."] = "BİR POLİSİ TESLİM OLMAYA ZORLAYIP REHİNE ALMAK İÇİN \"BAĞIR/ETKİLEŞİME GİR\" TUŞUNA BASABİLİRSİN.",
["Bir priz tamam ama o kocaman güzel kıza bir tane daha lazım."] = "BİR PRİZ TAMAM AMA O KOCAMAN GÜZEL KIZA BİR TANE DAHA LAZIM.",
["Bir robotun olabileceği kadar ölümcül tasarlandı. Great Purge’den tek başına Drone sorumluydu. Tüm zihinlere ve tarihî veri sunucularına sonsuza dek kazındı. Drone, gözden çıkarılabilir bir erden beklenenin ötesine geçecek becerilere sahipti; sonunda paha biçilemez oldu. Great Purge savaşın yönünü değiştirdi: uyuyan hücreler ortaya çıktı, robotların bağlantısı kesildi, Hive Mind binlerce zettabayt kaybetti. Drone, Ming Ji Memorial Park’ta bakılıp hayranlık duyulan bir heykele dönüştü. "] = "BİR ROBOTUN OLABİLECEĞİ KADAR ÖLÜMCÜL TASARLANDI. GREAT PURGE’DEN TEK BAŞINA DRONE SORUMLUYDU. TÜM ZİHİNLERE VE TARİHÎ VERİ SUNUCULARINA SONSUZA DEK KAZINDI. DRONE, GÖZDEN ÇIKARILABİLİR BİR ERDEN BEKLENENİN ÖTESİNE GEÇECEK BECERİLERE SAHİPTİ; SONUNDA PAHA BİÇİLEMEZ OLDU. GREAT PURGE SAVAŞIN YÖNÜNÜ DEĞİŞTİRDİ: UYUYAN HÜCRELER ORTAYA ÇIKTI, ROBOTLARIN BAĞLANTISI KESİLDİ, HİVE MİND BİNLERCE ZETTABAYT KAYBETTİ. DRONE, MİNG Jİ MEMORİAL PARK’TA BAKILIP HAYRANLIK DUYULAN BİR HEYKELE DÖNÜŞTÜ. ",
["Bir sabit disk ele geçirirsek kasa dairesinin sistemini kırabiliriz belki."] = "BİR SABİT DİSK ELE GEÇİRİRSEK KASA DAİRESİNİN SİSTEMİNİ KIRABİLİRİZ BELKİ.",
["Bir saldırı dalgası daha geliyor!"] = "BİR SALDIRI DALGASI DAHA GELİYOR!",
["Bir saldırı geliyor."] = "BİR SALDIRI GELİYOR.",
["Bir saldırı helikopteri daha millet! Tetikte olun!"] = "BİR SALDIRI HELİKOPTERİ DAHA MİLLET! TETİKTE OLUN!",
["Bir saldırı helikopteri daha! Dikkat millet!"] = "BİR SALDIRI HELİKOPTERİ DAHA! DİKKAT MİLLET!",
["Bir saldırı helikopteri geliyor! Sıkı tutunun!"] = "BİR SALDIRI HELİKOPTERİ GELİYOR! SIKI TUTUNUN!",
["Bir saldırıdan sıyrılmak zırhını doldurur."] = "BİR SALDIRIDAN SIYRILMAK ZIRHINI DOLDURUR.",
["Bir sanatçının çalışma alanı eksik hissettirirse orada yapılan iş de eksik kalır. Washington’ın en şık maske yapım atölyesi işte burada."] = "BİR SANATÇININ ÇALIŞMA ALANI EKSİK HİSSETTİRİRSE ORADA YAPILAN İŞ DE EKSİK KALIR. WASHINGTON’IN EN ŞIK MASKE YAPIM ATÖLYESİ İŞTE BURADA.",
["Bir saniye bekleyin..."] = "BİR SANİYE BEKLEYİN...",
["Bir santrifüj bulun."] = "BİR SANTRİFÜJ BULUN.",
