["Bir tanıdık, gizlice geçebilmen için bir pencerenin kilidini açar."] = "BİR TANIDIK, GİZLİCE GEÇEBİLMEN İÇİN BİR PENCERENİN KİLİDİNİ AÇAR.",
["Bir tanıdık, kasanın içindeki kapıların anahtarlarının yerini işaretler."] = "BİR TANIDIK, KASANIN İÇİNDEKİ KAPILARIN ANAHTARLARININ YERİNİ İŞARETLER.",
["Bir tanıdık, soygundan önce seçilen noktaya Beast matkabının yedek parçalarını içeren bir çanta bırakır."] = "BİR TANIDIK, SOYGUNDAN ÖNCE SEÇİLEN NOKTAYA BEAST MATKABININ YEDEK PARÇALARINI İÇEREN BİR ÇANTA BIRAKIR.",
["Bir tanıdık, üzerinden atlayabilmen için duvarın yanına araba park edecek."] = "BİR TANIDIK, ÜZERİNDEN ATLAYABİLMEN İÇİN DUVARIN YANINA ARABA PARK EDECEK.",
["Bir tanıdığıma güvenlik sisteminin bağlantılarını değiştirterek girişinizi kolaylaştırabilirim."] = "BİR TANIDIĞIMA GÜVENLİK SİSTEMİNİN BAĞLANTILARINI DEĞİŞTİRTEREK GİRİŞİNİZİ KOLAYLAŞTIRABİLİRİM.",
["Bir tanıdığıma, tıbbi malzemeleri istediğiniz yere bıraktırabilirim."] = "BİR TANIDIĞIMA, TIBBİ MALZEMELERİ İSTEDİĞİNİZ YERE BIRAKTIRABİLİRİM.",
["Bir tanıdığın ağa bağladığı aygıttan tüm kameralara eriş"] = "BİR TANIDIĞIN AĞA BAĞLADIĞI AYGITTAN TÜM KAMERALARA ERİŞ",
["Bir tanıdığın ağa bağladığı aygıttan tüm kameralara eriş."] = "BİR TANIDIĞIN AĞA BAĞLADIĞI AYGITTAN TÜM KAMERALARA ERİŞ.",
["Bir taret yerleştirdiler! Başınızı eğin!"] = "BİR TARET YERLEŞTİRDİLER! BAŞINIZI EĞİN!",
["Bir taç arıyorsunuz, gözünüzü açık tutun. Kasada değilse herhangi bir yerde olabilir."] = "BİR TAÇ ARIYORSUNUZ, GÖZÜNÜZÜ AÇIK TUTUN. KASADA DEĞİLSE HERHANGİ BİR YERDE OLABİLİR.",
["Bir televizyon haber ekibine benziyor. Televizyona çıkmak istemezsiniz millet, kameralarından uzak durun."] = "BİR TELEVİZYON HABER EKİBİNE BENZİYOR. TELEVİZYONA ÇIKMAK İSTEMEZSİNİZ MİLLET, KAMERALARINDAN UZAK DURUN.",
["Bir telsiz bul"] = "BİR TELSİZ BUL",
["Bir telsiz bulun, ben de birini kapıyı açmaya ikna edeyim."] = "BİR TELSİZ BULUN, BEN DE BİRİNİ KAPIYI AÇMAYA İKNA EDEYİM.",
["Bir terminal buldum. Gidip sistemini kırın, manyetik kilidi indirelim."] = "BİR TERMİNAL BULDUM. GİDİP SİSTEMİNİ KIRIN, MANYETİK KİLİDİ İNDİRELİM.",
["Bir terminal bulun millet."] = "BİR TERMİNAL BULUN MİLLET.",
["Bir terslik var. O boruları tekrar kontrol edin."] = "BİR TERSLİK VAR. O BORULARI TEKRAR KONTROL EDİN.",
["Bir tren hazırladım. Çok uzakta değil. Savaş başlıklarını getirin. Çabuk!"] = "BİR TREN HAZIRLADIM. ÇOK UZAKTA DEĞİL. SAVAŞ BAŞLIKLARINI GETİRİN. ÇABUK!",
["Bir tur daha atıyorum. Bunu sizin için yola bırakacağım."] = "BİR TUR DAHA ATIYORUM. BUNU SİZİN İÇİN YOLA BIRAKACAĞIM.",
["Bir tür koda benziyor, işe yarar."] = "BİR TÜR KODA BENZİYOR, İŞE YARAR.",
["Bir tür patlayıcı hızlandırıcı gerekecek. Gübre, mazot... belki bu insanların etrafta C4'ü bile vardır. Bakın bakalım ne bulabileceksiniz."] = "BİR TÜR PATLAYICI HIZLANDIRICI GEREKECEK. GÜBRE, MAZOT... BELKİ BU İNSANLARIN ETRAFTA C4'Ü BİLE VARDIR. BAKIN BAKALIM NE BULABİLECEKSİNİZ.",
["Bir uyarı: Sunucu odasında kullandıkları güvenlik sistemi yüzünden, yakınlarda çalışan bir ECM Karıştırıcı varsa kapıyı açmak zorlaşır."] = "BİR UYARI: SUNUCU ODASINDA KULLANDIKLARI GÜVENLİK SİSTEMİ YÜZÜNDEN, YAKINLARDA ÇALIŞAN BİR ECM KARIŞTIRICI VARSA KAPIYI AÇMAK ZORLAŞIR.",
["Bir uçak, Fulton Extraction Cage parçalarını getirmek üzere yolda. Çantalar bırakılınca parçaları çıkarıp kafesi kur."] = "BİR UÇAK, FULTON EXTRACTİON CAGE PARÇALARINI GETİRMEK ÜZERE YOLDA. ÇANTALAR BIRAKILINCA PARÇALARI ÇIKARIP KAFESİ KUR.",
["Bir uçağın anahtarlarına benziyor."] = "BİR UÇAĞIN ANAHTARLARINA BENZİYOR.",
["Bir varmış bir yokmuş, neşeli bir hırsız çetesinin üyesi Küçük Yaşlı Wolf varmış. Wolf pek öfkeli, dengesiz bir adammış; şiddet nöbetleri geçirir, küçük yaşlı kadınların kılığına girer, altın için yanıp tutuşurmuş. Bir gün Wolf’un aklına bir fikir gelmiş. Siyah kadife bir takım çalıp yerel üniversitedeki bir derse sızmaya çalışmış; servetinden ayırabileceği bir sürü zengin olacağını düşünmüş. Ama ne yazık ki girerken bahçıvana çatmış. Bahçıvan alarmı verince Wolf mağarasına kaçmak zorunda kalmış."] = "BİR VARMIŞ BİR YOKMUŞ, NEŞELİ BİR HIRSIZ ÇETESİNİN ÜYESİ KÜÇÜK YAŞLI WOLF VARMIŞ. WOLF PEK ÖFKELİ, DENGESİZ BİR ADAMMIŞ; ŞİDDET NÖBETLERİ GEÇİRİR, KÜÇÜK YAŞLI KADINLARIN KILIĞINA GİRER, ALTIN İÇİN YANIP TUTUŞURMUŞ. BİR GÜN WOLF’UN AKLINA BİR FİKİR GELMİŞ. SİYAH KADİFE BİR TAKIM ÇALIP YEREL ÜNİVERSİTEDEKİ BİR DERSE SIZMAYA ÇALIŞMIŞ; SERVETİNDEN AYIRABİLECEĞİ BİR SÜRÜ ZENGİN OLACAĞINI DÜŞÜNMÜŞ. AMA NE YAZIK Kİ GİRERKEN BAHÇIVANA ÇATMIŞ. BAHÇIVAN ALARMI VERİNCE WOLF MAĞARASINA KAÇMAK ZORUNDA KALMIŞ.",
["Bir veya daha fazla hedef DLC gerektiriyor. Crime.net’te soyguna sahip birini bulup ona katılabilir veya bu görevi çevrim dışı modda oynayabilirsin."] = "BİR VEYA DAHA FAZLA HEDEF DLC GEREKTİRİYOR. CRIME.NET’TE SOYGUNA SAHİP BİRİNİ BULUP ONA KATILABİLİR VEYA BU GÖREVİ ÇEVRİM DIŞI MODDA OYNAYABİLİRSİN.",
["Bir veya daha fazla hedef DLC gerektiriyor. Crime.net’te soyguna sahip birini bulup ona katılabilir veya görevi atlayabilirsin."] = "BİR VEYA DAHA FAZLA HEDEF DLC GEREKTİRİYOR. CRIME.NET’TE SOYGUNA SAHİP BİRİNİ BULUP ONA KATILABİLİR VEYA GÖREVİ ATLAYABİLİRSİN.",
["Bir veya daha fazla oyuncuyla bağlantı kurulamadı."] = "BİR VEYA DAHA FAZLA OYUNCUYLA BAĞLANTI KURULAMADI.",
["Bir veya daha fazla silah modifikasyonu nedeniyle kilitli."] = "BİR VEYA DAHA FAZLA SİLAH MODİFİKASYONU NEDENİYLE KİLİTLİ.",
["Bir vites daha atar mısınız? O kokain yığını korkutucu hızla küçülüyor!"] = "BİR VİTES DAHA ATAR MISINIZ? O KOKAİN YIĞINI KORKUTUCU HIZLA KÜÇÜLÜYOR!",
["Bir yakıt bidonu bulup güvertede işaret ateşi yakın!"] = "BİR YAKIT BİDONU BULUP GÜVERTEDE İŞARET ATEŞİ YAKIN!",
["Bir yanında kılıfı, omzunda gitarıyla yalnız bir atlı kasabaya girdi. Beyaz takımının yıpranmış etekleri, tozlu yollarda uzun bir yolculuk anlattı. Atının yanında, adımlarına uyarak bir çakal yürüyordu; uzun bacaklarıyla toprağa ağır ağır basıyordu. Adam döküntü bir barın önünde durup silahını çekti, açık kapıdan içeri nişan aldı. Ateş etti. Bir çığlık duyulunca çakal içeri fırladı. Birkaç saniye sonra serseri görünüşlü birinin cesedini sürükleyerek döndü. Adam attan inip cansız bedeni atın arkasına attı, şerifin ofisine doğru yola koyuldu..."] = "BİR YANINDA KILIFI, OMZUNDA GİTARIYLA YALNIZ BİR ATLI KASABAYA GİRDİ. BEYAZ TAKIMININ YIPRANMIŞ ETEKLERİ, TOZLU YOLLARDA UZUN BİR YOLCULUK ANLATTI. ATININ YANINDA, ADIMLARINA UYARAK BİR ÇAKAL YÜRÜYORDU; UZUN BACAKLARIYLA TOPRAĞA AĞIR AĞIR BASIYORDU. ADAM DÖKÜNTÜ BİR BARIN ÖNÜNDE DURUP SİLAHINI ÇEKTİ, AÇIK KAPIDAN İÇERİ NİŞAN ALDI. ATEŞ ETTİ. BİR ÇIĞLIK DUYULUNCA ÇAKAL İÇERİ FIRLADI. BİRKAÇ SANİYE SONRA SERSERİ GÖRÜNÜŞLÜ BİRİNİN CESEDİNİ SÜRÜKLEYEREK DÖNDÜ. ADAM ATTAN İNİP CANSIZ BEDENİ ATIN ARKASINA ATTI, ŞERİFİN OFİSİNE DOĞRU YOLA KOYULDU...",
["Bir yaya devriye polisi bankayı kontrol ediyor. Güzelce... karşılandığından emin olun."] = "BİR YAYA DEVRİYE POLİSİ BANKAYI KONTROL EDİYOR. GÜZELCE... KARŞILANDIĞINDAN EMİN OLUN.",
["Bir yerde Anahtar Kartı olmalı"] = "BİR YERDE ANAHTAR KARTI OLMALI",
["Bir yerde denekleri taramak için kullanabileceğimiz bir tarayıcı olmalı. Bul."] = "BİR YERDE DENEKLERİ TARAMAK İÇİN KULLANABİLECEĞİMİZ BİR TARAYICI OLMALI. BUL.",
["Bir yerde kasayı açan bir mekanizma ya da düğme olmalı. Bulabilir misiniz, bakın."] = "BİR YERDE KASAYI AÇAN BİR MEKANİZMA YA DA DÜĞME OLMALI. BULABİLİR MİSİNİZ, BAKIN.",
["Bir yerde kilit altında daha fazla malzeme olmalı."] = "BİR YERDE KİLİT ALTINDA DAHA FAZLA MALZEME OLMALI.",
["Bir yerde takılmayın, yukarı ilerlemeye devam! Değecek ama hızla ziyan oluyor!"] = "BİR YERDE TAKILMAYIN, YUKARI İLERLEMEYE DEVAM! DEĞECEK AMA HIZLA ZİYAN OLUYOR!",
["Bir yerlerde Anahtar Kartı olmalı."] = "BİR YERLERDE ANAHTAR KARTI OLMALI.",
["Bir yerlerde ateşe verilebilecek benzin ya da deterjan vardır muhtemelen."] = "BİR YERLERDE ATEŞE VERİLEBİLECEK BENZİN YA DA DETERJAN VARDIR MUHTEMELEN.",
["Bir yerlerde daha fazla silah zulası olmalı, bulmaya çalışın."] = "BİR YERLERDE DAHA FAZLA SİLAH ZULASI OLMALI, BULMAYA ÇALIŞIN.",
["Bir yerlerde kaynak lambası bulabilirseniz işinizi görür. Triad'ın ortalıkta bırakacağı türden bir şey gibi!"] = "BİR YERLERDE KAYNAK LAMBASI BULABİLİRSENİZ İŞİNİZİ GÖRÜR. TRİAD'IN ORTALIKTA BIRAKACAĞI TÜRDEN BİR ŞEY GİBİ!",
["Bir yerlere geliyorsun. Silahının görünüşünü değiştir ve gelişini duyurmanın yeni bir yolunu edin."] = "BİR YERLERE GELİYORSUN. SİLAHININ GÖRÜNÜŞÜNÜ DEĞİŞTİR VE GELİŞİNİ DUYURMANIN YENİ BİR YOLUNU EDİN.",
["Bir yol seç"] = "BİR YOL SEÇ",
["Bir yön seçin millet. Taş, kâğıt, kertenkele... Her neyse... Hangisi olursa."] = "BİR YÖN SEÇİN MİLLET. TAŞ, KÂĞIT, KERTENKELE... HER NEYSE... HANGİSİ OLURSA.",
["Bir yönlendirici devre dışı!"] = "BİR YÖNLENDİRİCİ DEVRE DIŞI!",
["Bir yıldan uzun süre önce"] = "BİR YILDAN UZUN SÜRE ÖNCE",
["Bir zamanlar August Lindenhurst takma adını kullanan Duke, Payday Gang ekibine katılırken bu adı bırakıp yalnızca \"Duke\" adını benimsedi. Son birkaç yıldır suç dünyasının derinliklerindeki örüntüleri ve söylentileri araştırıyor. Geçmişin ünlü soyguncularıyla birlikte tarih kitaplarına geçmesini sağlayacak destansı bir soygun gerçekleştirmeye doğuştan bir ihtiyaç, hatta saplantı duyuyor. Bain’in çetesinin bu amacına ulaşmasına yardım edebileceğine inanıyor."] = "BİR ZAMANLAR AUGUST LİNDENHURST TAKMA ADINI KULLANAN DUKE, PAYDAY GANG EKİBİNE KATILIRKEN BU ADI BIRAKIP YALNIZCA \"DUKE\" ADINI BENİMSEDİ. SON BİRKAÇ YILDIR SUÇ DÜNYASININ DERİNLİKLERİNDEKİ ÖRÜNTÜLERİ VE SÖYLENTİLERİ ARAŞTIRIYOR. GEÇMİŞİN ÜNLÜ SOYGUNCULARIYLA BİRLİKTE TARİH KİTAPLARINA GEÇMESİNİ SAĞLAYACAK DESTANSI BİR SOYGUN GERÇEKLEŞTİRMEYE DOĞUŞTAN BİR İHTİYAÇ, HATTA SAPLANTI DUYUYOR. BAIN’İN ÇETESİNİN BU AMACINA ULAŞMASINA YARDIM EDEBİLECEĞİNE İNANIYOR.",
["Bir zamanlar Steve adlı bir düzenbaz vardı, cebinde bir plan saklardı. Dost çetesiyle bir akım başlattı; pek uzun sürmedi. Şakadan fazlası bir banka soygununda, sıradan boyacılarınkinden daha havalı mavi tulumlar giydiler. Rehineleri tutup oyun oynamaya zorladılar; biri zemini parçalayana dek. Polis kapıdan gelmesin diye umuyorlardı."] = "BİR ZAMANLAR STEVE ADLI BİR DÜZENBAZ VARDI, CEBİNDE BİR PLAN SAKLARDI. DOST ÇETESİYLE BİR AKIM BAŞLATTI; PEK UZUN SÜRMEDİ. ŞAKADAN FAZLASI BİR BANKA SOYGUNUNDA, SIRADAN BOYACILARINKİNDEN DAHA HAVALI MAVİ TULUMLAR GİYDİLER. REHİNELERİ TUTUP OYUN OYNAMAYA ZORLADILAR; BİRİ ZEMİNİ PARÇALAYANA DEK. POLİS KAPIDAN GELMESİN DİYE UMUYORLARDI.",
["Bir zamanlar aramızda yürürlerdi. Kuleler kadar uzun, devasa varlıklar. Primat atalarımız ateşe ulurken onlar zaten yaşlıydı. Artık yoklar; yalnızca gölgeleri, yarı düşlenmiş tür hatıralarında bize ulaşıyor."] = "BİR ZAMANLAR ARAMIZDA YÜRÜRLERDİ. KULELER KADAR UZUN, DEVASA VARLIKLAR. PRİMAT ATALARIMIZ ATEŞE ULURKEN ONLAR ZATEN YAŞLIYDI. ARTIK YOKLAR; YALNIZCA GÖLGELERİ, YARI DÜŞLENMİŞ TÜR HATIRALARINDA BİZE ULAŞIYOR.",
["Bir zamanlar büyük bir oyuncu, içine şeytani bir ruh girdiğini iddia edip deforme olmuş görünümünü saklamak için maske takmaya başladı. Bir gün maske kırıldı; altında gizlenen şey bir daha asla hapsedilemedi."] = "BİR ZAMANLAR BÜYÜK BİR OYUNCU, İÇİNE ŞEYTANİ BİR RUH GİRDİĞİNİ İDDİA EDİP DEFORME OLMUŞ GÖRÜNÜMÜNÜ SAKLAMAK İÇİN MASKE TAKMAYA BAŞLADI. BİR GÜN MASKE KIRILDI; ALTINDA GİZLENEN ŞEY BİR DAHA ASLA HAPSEDİLEMEDİ.",
["Bir zamanlar zengin bir deniz subayına ait olup sorumsuz evladının elinde savrulan bu güzel ve pahalı pompalı tüfek, sonunda suç dünyasına ulaştı. Ölüm ve yıkımdan oluşan kaderini nihayet orada gerçekleştirecek."] = "BİR ZAMANLAR ZENGİN BİR DENİZ SUBAYINA AİT OLUP SORUMSUZ EVLADININ ELİNDE SAVRULAN BU GÜZEL VE PAHALI POMPALI TÜFEK, SONUNDA SUÇ DÜNYASINA ULAŞTI. ÖLÜM VE YIKIMDAN OLUŞAN KADERİNİ NİHAYET ORADA GERÇEKLEŞTİRECEK.",
["Bir Çeşit Kumbara"] = "BİR ÇEŞİT KUMBARA",
["Bir Çin bankasının yatırım yaptığı söylentilerini yorumlayamam ama şahsen Asyalı efendilerimize hoş geldiniz derim. "] = "BİR ÇİN BANKASININ YATIRIM YAPTIĞI SÖYLENTİLERİNİ YORUMLAYAMAM AMA ŞAHSEN ASYALI EFENDİLERİMİZE HOŞ GELDİNİZ DERİM. ",
["Bir çanta aldın"] = "BİR ÇANTA ALDIN",
["Bir çanta daha, sonra gidebilirsiniz."] = "BİR ÇANTA DAHA, SONRA GİDEBİLİRSİNİZ.",
["Bir çanta dolusu mal topladınız mı? Almaya birini göndereceğim. Yakında bekleyin."] = "BİR ÇANTA DOLUSU MAL TOPLADINIZ MI? ALMAYA BİRİNİ GÖNDERECEĞİM. YAKINDA BEKLEYİN.",
["Bir çanta kokain daha gitti. Bir tane daha... Ve... Devam edeyim mi? İçler acısı."] = "BİR ÇANTA KOKAİN DAHA GİTTİ. BİR TANE DAHA... VE... DEVAM EDEYİM Mİ? İÇLER ACISI.",
["Bir çanta mı?! Hadi soyguncu. Daha fazlasını yapabilirsin!"] = "BİR ÇANTA MI?! HADİ SOYGUNCU. DAHA FAZLASINI YAPABİLİRSİN!",
["Bir çanta oldu!"] = "BİR ÇANTA OLDU!",
["Bir çanta para, harika. Ama önce o şerefsize ödeyelim. Oto tamircisinin yanındaki sarı duvar. Merak etmeyin, onu sonra bulup hallederiz."] = "BİR ÇANTA PARA, HARİKA. AMA ÖNCE O ŞEREFSİZE ÖDEYELİM. OTO TAMİRCİSİNİN YANINDAKİ SARI DUVAR. MERAK ETMEYİN, ONU SONRA BULUP HALLEDERİZ.",
["Bir çanta tamam! Asgari gayreti gösterdiniz!"] = "BİR ÇANTA TAMAM! ASGARİ GAYRETİ GÖSTERDİNİZ!",
["Bir çanta. Kızımızın patlayıcıları olabilir. İçine bakın, hemen!"] = "BİR ÇANTA. KIZIMIZIN PATLAYICILARI OLABİLİR. İÇİNE BAKIN, HEMEN!",
["Bir çantayı havadayken yakala."] = "BİR ÇANTAYI HAVADAYKEN YAKALA.",
["Bir çay dükkânı vakası daha istemiyoruz."] = "BİR ÇAY DÜKKÂNI VAKASI DAHA İSTEMİYORUZ.",
["Bir çekme vinci yolda. Gelir gelmez avluya kurun."] = "BİR ÇEKME VİNCİ YOLDA. GELİR GELMEZ AVLUYA KURUN.",
["Bir çelik halat kurarsanız daha hızlı yapabilirsiniz."] = "BİR ÇELİK HALAT KURARSANIZ DAHA HIZLI YAPABİLİRSİNİZ.",
["Bir çıkış yolu bul ve elması güvenceye al."] = "BİR ÇIKIŞ YOLU BUL VE ELMASI GÜVENCEYE AL.",
["Bir öğrenci geliyor, kredisini yeniden yapılandırmak istiyor. Biliyorum! Hahahahaha. Ne aptal ama!"] = "BİR ÖĞRENCİ GELİYOR, KREDİSİNİ YENİDEN YAPILANDIRMAK İSTİYOR. BİLİYORUM! HAHAHAHAHA. NE APTAL AMA!",
["Bir ızgara daha ama sorun değil. Bir parti daha termal macun kullanın."] = "BİR IZGARA DAHA AMA SORUN DEĞİL. BİR PARTİ DAHA TERMAL MACUN KULLANIN.",
