["Bu bir uyarıdır. Öldürme yetkimiz var ve süreniz doldu. Sıra sizde pislikler."] = "BU BİR UYARIDIR. ÖLDÜRME YETKİMİZ VAR VE SÜRENİZ DOLDU. SIRA SİZDE PİSLİKLER.",
["Bu bir yarısı, aklınızda tutun."] = "BU BİR YARISI, AKLINIZDA TUTUN.",
["Bu bir Özel eşya!"] = "BU BİR ÖZEL EŞYA!",
["Bu biraz sürecek. Hünerlerini gösterirken çekme vinçlerini koruyun."] = "BU BİRAZ SÜRECEK. HÜNERLERİNİ GÖSTERİRKEN ÇEKME VİNÇLERİNİ KORUYUN.",
["Bu bizde kalacak. Kusura bakmayın..."] = "BU BİZDE KALACAK. KUSURA BAKMAYIN...",
["Bu bizi zayıf gösterir."] = "BU BİZİ ZAYIF GÖSTERİR.",
["Bu boka inanamıyorum amına koyayım!"] = "BU BOKA İNANAMIYORUM AMINA KOYAYIM!",
["Bu boka inanamıyorum!"] = "BU BOKA İNANAMIYORUM!",
["Bu boklara zarar veriyorken bir de aşağılayalım bari. Kalan paraya mürekkep bombası koymak çifte darbe olur, ha?"] = "BU BOKLARA ZARAR VERİYORKEN BİR DE AŞAĞILAYALIM BARİ. KALAN PARAYA MÜREKKEP BOMBASI KOYMAK ÇİFTE DARBE OLUR, HA?",
["Bu boktan dünyada sahte para bile çok para ediyor. Harika iş!"] = "BU BOKTAN DÜNYADA SAHTE PARA BİLE ÇOK PARA EDİYOR. HARİKA İŞ!",
["Bu boktan işleri yaptırıyorsun, bir de fazladan birkaç Ceset Torbası için teşekkür mü bekliyorsun? Siktir git Bain."] = "BU BOKTAN İŞLERİ YAPTIRIYORSUN, BİR DE FAZLADAN BİRKAÇ CESET TORBASI İÇİN TEŞEKKÜR MÜ BEKLİYORSUN? SİKTİR GİT BAIN.",
["Bu boku bir kitap için mi yapıyoruz lan?"] = "BU BOKU BİR KİTAP İÇİN Mİ YAPIYORUZ LAN?",
["Bu boku bitirmek için otuz saniyeniz var."] = "BU BOKU BİTİRMEK İÇİN OTUZ SANİYENİZ VAR.",
["Bu boku dün gece hallettim Bain. Beni kim sanıyorsun lan?"] = "BU BOKU DÜN GECE HALLETTİM BAIN. BENİ KİM SANIYORSUN LAN?",
["Bu bokun faturasını bana kesmeyi de aklınızdan geçirmeyin."] = "BU BOKUN FATURASINI BANA KESMEYİ DE AKLINIZDAN GEÇİRMEYİN.",
["Bu boruları petrol numunemizle eşleşen tanka bağlamalıyız. Hazır olunca tankın kolunu çekin. Geminin konumda olmasını sağlayacağım."] = "BU BORULARI PETROL NUMUNEMİZLE EŞLEŞEN TANKA BAĞLAMALIYIZ. HAZIR OLUNCA TANKIN KOLUNU ÇEKİN. GEMİNİN KONUMDA OLMASINI SAĞLAYACAĞIM.",
["Bu bronz madalyon 19. yüzyılda yapılmış. Üzerinde Fleur De Lis ve Peridot kristali tasvir edilmiş; kenarlarında antik çivi yazısı var. Kurşun kaplı bir kutuda 100 yıldan uzun süre gömülü kalmış."] = "BU BRONZ MADALYON 19. YÜZYILDA YAPILMIŞ. ÜZERİNDE FLEUR DE LİS VE PERİDOT KRİSTALİ TASVİR EDİLMİŞ; KENARLARINDA ANTİK ÇİVİ YAZISI VAR. KURŞUN KAPLI BİR KUTUDA 100 YILDAN UZUN SÜRE GÖMÜLÜ KALMIŞ.",
["Bu bölge şununla eşleşiyor... Hımm, biraz daha zaman verin..."] = "BU BÖLGE ŞUNUNLA EŞLEŞİYOR... HIMM, BİRAZ DAHA ZAMAN VERİN...",
["Bu bölgede bir sürü inşaat var. Etrafı araştırın, o çelik kapıyı aşmamıza yardım edecek bir şey bulabilir misiniz bakın."] = "BU BÖLGEDE BİR SÜRÜ İNŞAAT VAR. ETRAFI ARAŞTIRIN, O ÇELİK KAPIYI AŞMAMIZA YARDIM EDECEK BİR ŞEY BULABİLİR MİSİNİZ BAKIN.",
["Bu canavar gibi olacak!"] = "BU CANAVAR GİBİ OLACAK!",
["Bu canavarı süreceğiniz için sizi kıskanıyorum."] = "BU CANAVARI SÜRECEĞİNİZ İÇİN SİZİ KISKANIYORUM.",
["Bu cihaz bulunup müşterime... 'değerlendirme' için teslim edilmeli. Ayrıca yanlış ellere geçmesin diye teknik bilgiler de silinmeli."] = "BU CİHAZ BULUNUP MÜŞTERİME... 'DEĞERLENDİRME' İÇİN TESLİM EDİLMELİ. AYRICA YANLIŞ ELLERE GEÇMESİN DİYE TEKNİK BİLGİLER DE SİLİNMELİ.",
["Bu da buraya kadarmış. B planı lazım. Hâlâ seçime bir şekilde müdahale etmeliyiz... Alışveriş merkezine gitme vakti."] = "BU DA BURAYA KADARMIŞ. B PLANI LAZIM. HÂLÂ SEÇİME BİR ŞEKİLDE MÜDAHALE ETMELİYİZ... ALIŞVERİŞ MERKEZİNE GİTME VAKTİ.",
["Bu da ikinci parti C4. Az kaldı. Son partiyi bulun."] = "BU DA İKİNCİ PARTİ C4. AZ KALDI. SON PARTİYİ BULUN.",
["Bu daha çok benim tarzım."] = "BU DAHA ÇOK BENİM TARZIM.",
["Bu dairenin içinde. Açın."] = "BU DAİRENİN İÇİNDE. AÇIN.",
["Bu dalgada ZEAL keskin nişancıları gönderiyorlar."] = "BU DALGADA ZEAL KESKİN NİŞANCILARI GÖNDERİYORLAR.",
["Bu dalgayı durdurmak için gerekeni yapın!"] = "BU DALGAYI DURDURMAK İÇİN GEREKENİ YAPIN!",
["Bu dava özel. Ben neden özelim? Bunları kim sızdırıyor?"] = "BU DAVA ÖZEL. BEN NEDEN ÖZELİM? BUNLARI KİM SIZDIRIYOR?",
["Bu delilik, hastanenin etrafını sarmışlar. Özel askerî birlik gibi... Paralı askerler. Gitmeniz gerek... HEMEN."] = "BU DELİLİK, HASTANENİN ETRAFINI SARMIŞLAR. ÖZEL ASKERÎ BİRLİK GİBİ... PARALI ASKERLER. GİTMENİZ GEREK... HEMEN.",
["Bu deprem kim bilir kaç kirli sırrı gün yüzüne çıkaracak."] = "BU DEPREM KİM BİLİR KAÇ KİRLİ SIRRI GÜN YÜZÜNE ÇIKARACAK.",
["Bu desteği kullanmak akıllıca bir hamle, söylemiş olayım."] = "BU DESTEĞİ KULLANMAK AKILLICA BİR HAMLE, SÖYLEMİŞ OLAYIM.",
["Bu desteği satın almak bence akıllıca bir karar."] = "BU DESTEĞİ SATIN ALMAK BENCE AKILLICA BİR KARAR.",
["Bu değil. Başka bir numune alın!"] = "BU DEĞİL. BAŞKA BİR NUMUNE ALIN!",
["Bu değildi. Devam edin. Kasa Dairesi burada bir yerde."] = "BU DEĞİLDİ. DEVAM EDİN. KASA DAİRESİ BURADA BİR YERDE.",
["Bu değildi. Sıfırlanması için biraz bekleyin, sonra yine deneyin."] = "BU DEĞİLDİ. SIFIRLANMASI İÇİN BİRAZ BEKLEYİN, SONRA YİNE DENEYİN.",
["Bu dipçiğin tasarımı isabeti biraz artırır."] = "BU DİPÇİĞİN TASARIMI İSABETİ BİRAZ ARTIRIR.",
["Bu doldurma süresiyle her atışını değerlendirsen iyi olur."] = "BU DOLDURMA SÜRESİYLE HER ATIŞINI DEĞERLENDİRSEN İYİ OLUR.",
["Bu dolgun yanaklı, pembe, sağlıklı yüz; Amerika’daki sinema lobilerinde bulunan kızarmış hamurla şekerin o harika, sihirli simyasını temsil ediyor."] = "BU DOLGUN YANAKLI, PEMBE, SAĞLIKLI YÜZ; AMERİKA’DAKİ SİNEMA LOBİLERİNDE BULUNAN KIZARMIŞ HAMURLA ŞEKERİN O HARİKA, SİHİRLİ SİMYASINI TEMSİL EDİYOR.",
["Bu domuzcukları pastırmaya çevirin!"] = "BU DOMUZCUKLARI PASTIRMAYA ÇEVİRİN!",
["Bu dosyaların arasında muhtemelen işe yarar bilgiler var..."] = "BU DOSYALARIN ARASINDA MUHTEMELEN İŞE YARAR BİLGİLER VAR...",
["Bu doğru adres olamaz, başka bir adresle tekrar deneyin."] = "BU DOĞRU ADRES OLAMAZ, BAŞKA BİR ADRESLE TEKRAR DENEYİN.",
["Bu doğru değil. Federaller bile böyle boklar yapmaz."] = "BU DOĞRU DEĞİL. FEDERALLER BİLE BÖYLE BOKLAR YAPMAZ.",
["Bu doğru değildi. Başka bir kombinasyon denemeniz gerekiyor, tamam mı?"] = "BU DOĞRU DEĞİLDİ. BAŞKA BİR KOMBİNASYON DENEMENİZ GEREKİYOR, TAMAM MI?",
["Bu doğru gibi görünüyor. Açın."] = "BU DOĞRU GİBİ GÖRÜNÜYOR. AÇIN.",
["Bu durumda hareketlerini izlemek için hedefini ‘işaretlemek’ akıllıca olabilir."] = "BU DURUMDA HAREKETLERİNİ İZLEMEK İÇİN HEDEFİNİ ‘İŞARETLEMEK’ AKILLICA OLABİLİR.",
["Bu döküntü yerde daha fazlası olmalı. The Dentist, Commissar'ın en iyi ganimetini güçlendirilmiş bir bodrumda tuttuğunu söylüyor. İçindekileri merak ettiğinize eminim. Zemin kattaki odaları arayın. Şüpheli bir şey bulabilecek misiniz, bakın."] = "BU DÖKÜNTÜ YERDE DAHA FAZLASI OLMALI. THE DENTIST, COMMİSSAR'IN EN İYİ GANİMETİNİ GÜÇLENDİRİLMİŞ BİR BODRUMDA TUTTUĞUNU SÖYLÜYOR. İÇİNDEKİLERİ MERAK ETTİĞİNİZE EMİNİM. ZEMİN KATTAKİ ODALARI ARAYIN. ŞÜPHELİ BİR ŞEY BULABİLECEK MİSİNİZ, BAKIN.",
["Bu döner platform kumandalarının giriş kartı sanırım. İşe yarar."] = "BU DÖNER PLATFORM KUMANDALARININ GİRİŞ KARTI SANIRIM. İŞE YARAR.",
["Bu dövmeyi görüyor musun? Bizzat kral yaptı. Müthiş be dostum."] = "BU DÖVMEYİ GÖRÜYOR MUSUN? BİZZAT KRAL YAPTI. MÜTHİŞ BE DOSTUM.",
["Bu dükkân mücevherle tıka basa dolu görünüyor. Herkes tatil dönemi için hazırlanıyor herhâlde. Neyse, en az dört çanta mücevher istiyorum. Bu bize gayet iyi yeter."] = "BU DÜKKÂN MÜCEVHERLE TIKA BASA DOLU GÖRÜNÜYOR. HERKES TATİL DÖNEMİ İÇİN HAZIRLANIYOR HERHÂLDE. NEYSE, EN AZ DÖRT ÇANTA MÜCEVHER İSTİYORUM. BU BİZE GAYET İYİ YETER.",
["Bu dükkândan en az iki çanta mücevher istiyoruz. Anlaşıldı mı?"] = "BU DÜKKÂNDAN EN AZ İKİ ÇANTA MÜCEVHER İSTİYORUZ. ANLAŞILDI MI?",
["Bu dükkânın sahibi bir ay sigorta evrakıyla uğraşacak. Güzel vurgun çocuklar, eve dönelim."] = "BU DÜKKÂNIN SAHİBİ BİR AY SİGORTA EVRAKIYLA UĞRAŞACAK. GÜZEL VURGUN ÇOCUKLAR, EVE DÖNELİM.",
["Bu dünyada fazla vaktin kalmadı!"] = "BU DÜNYADA FAZLA VAKTİN KALMADI!",
["Bu erişim etiketi Ar-Ge deposuna ait. Saklayın, tamam mı?"] = "BU ERİŞİM ETİKETİ AR-GE DEPOSUNA AİT. SAKLAYIN, TAMAM MI?",
["Bu eski sistemler, elektrik kesildiğinde çıkış sağlamak üzere tasarlanmış. Öyle bir durum yaratalım. O kabloları dışarıdaki elektrik kutusuyla köprüleyin."] = "BU ESKİ SİSTEMLER, ELEKTRİK KESİLDİĞİNDE ÇIKIŞ SAĞLAMAK ÜZERE TASARLANMIŞ. ÖYLE BİR DURUM YARATALIM. O KABLOLARI DIŞARIDAKİ ELEKTRİK KUTUSUYLA KÖPRÜLEYİN.",
["Bu eski usul motosiklet kaskı, dünyanın her yanındaki motorcuların değer verdiği bir mirasın parçası. Tarzdan çok nostaljiyle ilgili. Bu kask seni motorculuğun altın çağı olan 1940’lara götürüyor."] = "BU ESKİ USUL MOTOSİKLET KASKI, DÜNYANIN HER YANINDAKİ MOTORCULARIN DEĞER VERDİĞİ BİR MİRASIN PARÇASI. TARZDAN ÇOK NOSTALJİYLE İLGİLİ. BU KASK SENİ MOTORCULUĞUN ALTIN ÇAĞI OLAN 1940’LARA GÖTÜRÜYOR.",
["Bu etkileyici boynuzlarla her soygunu sendeleye sendeleye aşabilen efsanevi Thomoose gibi, avken avcıya dönüş."] = "BU ETKİLEYİCİ BOYNUZLARLA HER SOYGUNU SENDELEYE SENDELEYE AŞABİLEN EFSANEVİ THOMOOSE GİBİ, AVKEN AVCIYA DÖNÜŞ.",
["Bu eşya 1990’larda Kuzey Fransa’daki bir açık artırmada ortaya çıktı. Katılanlar arasında ellili yaşlarında bir kadın vardı. Onu tanıdı; takan subayın adını hatırlamasa da yüklü bir para ödedi. Genç bir kızken sebze almak için meydana gitmişti. Derken paraşütçüler inmeye başladı. Silah sesleri, patlamalar, korku ve acı çığlıkları havayı doldurdu. Subay onu bir devlet binasındaki sığınağa götürdü. Onu kurtarmak için iyilikten başka nedeni yoktu. Ama kendi canı tehlikedeyken bile onun canını kurtarmak için riske girdi. Kadın o zaman küçücük bir kızdı ama şapkayı yine de tanıdı."] = "BU EŞYA 1990’LARDA KUZEY FRANSA’DAKİ BİR AÇIK ARTIRMADA ORTAYA ÇIKTI. KATILANLAR ARASINDA ELLİLİ YAŞLARINDA BİR KADIN VARDI. ONU TANIDI; TAKAN SUBAYIN ADINI HATIRLAMASA DA YÜKLÜ BİR PARA ÖDEDİ. GENÇ BİR KIZKEN SEBZE ALMAK İÇİN MEYDANA GİTMİŞTİ. DERKEN PARAŞÜTÇÜLER İNMEYE BAŞLADI. SİLAH SESLERİ, PATLAMALAR, KORKU VE ACI ÇIĞLIKLARI HAVAYI DOLDURDU. SUBAY ONU BİR DEVLET BİNASINDAKİ SIĞINAĞA GÖTÜRDÜ. ONU KURTARMAK İÇİN İYİLİKTEN BAŞKA NEDENİ YOKTU. AMA KENDİ CANI TEHLİKEDEYKEN BİLE ONUN CANINI KURTARMAK İÇİN RİSKE GİRDİ. KADIN O ZAMAN KÜÇÜCÜK BİR KIZDI AMA ŞAPKAYI YİNE DE TANIDI.",
