["Bu federal heriflerin etrafında çörek ve turtadan daha ilginç şeyler var. Bize iyi para kazandırıp işleri yürütmemizi sağlayacak şeyler. Güzel bir şey görürseniz kapın gitsin. "] = "BU FEDERAL HERİFLERİN ETRAFINDA ÇÖREK VE TURTADAN DAHA İLGİNÇ ŞEYLER VAR. BİZE İYİ PARA KAZANDIRIP İŞLERİ YÜRÜTMEMİZİ SAĞLAYACAK ŞEYLER. GÜZEL BİR ŞEY GÖRÜRSENİZ KAPIN GİTSİN. ",
["Bu frekanslar sonra işe yarayacak. Şimdilik işe odaklanın."] = "BU FREKANSLAR SONRA İŞE YARAYACAK. ŞİMDİLİK İŞE ODAKLANIN.",
["Bu gaz! Çıkın oradan!"] = "BU GAZ! ÇIKIN ORADAN!",
["Bu gece Garrett adına ayrılmış mermi yok, tamam mı dostlar?"] = "BU GECE GARRETT ADINA AYRILMIŞ MERMİ YOK, TAMAM MI DOSTLAR?",
["Bu gece New York'a gidiyorsunuz. The Continental aradı. Kilit çalışanlarından biri pusuya düşürülmüş, Brooklyn'deki bir adreste kimliği belirsiz saldırganlarca tutuluyor. Yakalanırken yaptığı aramadan konumu aldık. Hedefin adı Charon. Oraya çabuk gidip onu tutanları indirmeli ve sağ salim Continental'a geri göndermeliyiz."] = "BU GECE NEW YORK'A GİDİYORSUNUZ. THE CONTINENTAL ARADI. KİLİT ÇALIŞANLARINDAN BİRİ PUSUYA DÜŞÜRÜLMÜŞ, BROOKLYN'DEKİ BİR ADRESTE KİMLİĞİ BELİRSİZ SALDIRGANLARCA TUTULUYOR. YAKALANIRKEN YAPTIĞI ARAMADAN KONUMU ALDIK. HEDEFİN ADI CHARON. ORAYA ÇABUK GİDİP ONU TUTANLARI İNDİRMELİ VE SAĞ SALİM CONTINENTAL'A GERİ GÖNDERMELİYİZ.",
["Bu gece geç saatte laboratuvardayız, gözlerinize tekinsiz bir manzara sunarız. Masada pişirin, köpürsün, kaynasın. Polis de gelip başımıza bela salmasın."] = "BU GECE GEÇ SAATTE LABORATUVARDAYIZ, GÖZLERİNİZE TEKİNSİZ BİR MANZARA SUNARIZ. MASADA PİŞİRİN, KÖPÜRSÜN, KAYNASIN. POLİS DE GELİP BAŞIMIZA BELA SALMASIN.",
["Bu gece hepinizden kusursuz iş istiyorum, göt herifler! Özellikle de yukarıda, kabindeki senden."] = "BU GECE HEPİNİZDEN KUSURSUZ İŞ İSTİYORUM, GÖT HERİFLER! ÖZELLİKLE DE YUKARIDA, KABİNDEKİ SENDEN.",
["Bu gece kalabalık kaynıyor. Onlara harika bir gösteri yapalım."] = "BU GECE KALABALIK KAYNIYOR. ONLARA HARİKA BİR GÖSTERİ YAPALIM.",
["Bu gece kazandıkları paranın hakkını versinler, ha? Kesinlikle."] = "BU GECE KAZANDIKLARI PARANIN HAKKINI VERSİNLER, HA? KESİNLİKLE.",
["Bu gece orman karanlık ve ürkütücü ekip. Hadi biraz met pişirelim."] = "BU GECE ORMAN KARANLIK VE ÜRKÜTÜCÜ EKİP. HADİ BİRAZ MET PİŞİRELİM.",
["Bu gece ortalık sakin. Öyle kalsın."] = "BU GECE ORTALIK SAKİN. ÖYLE KALSIN.",
["Bu gece rock and roll tarihine geçiyoruz ekip."] = "BU GECE ROCK AND ROLL TARİHİNE GEÇİYORUZ EKİP.",
["Bu gece yanlış Rus'la uğraştınız maskeli dostlarım."] = "BU GECE YANLIŞ RUS'LA UĞRAŞTINIZ MASKELİ DOSTLARIM.",
["Bu gece öleceğini biliyordu. İçine doğmuştu."] = "BU GECE ÖLECEĞİNİ BİLİYORDU. İÇİNE DOĞMUŞTU.",
["Bu geliştirme için yeterli Sikken yok."] = "BU GELİŞTİRME İÇİN YETERLİ SİKKEN YOK.",
["Bu geliştirme kullanılamıyor"] = "BU GELİŞTİRME KULLANILAMIYOR",
