["Bu gerilim Vlad'i öldürüyor! Yapın, yapın!"] = "BU GERİLİM VLAD'İ ÖLDÜRÜYOR! YAPIN, YAPIN!",
["Bu gerçekten çetin ceviz. St. Clair’in suçlu yanı, karanlık bir gecede cehennemi yaşarken doğdu. Sonra yasadışı dünyanın derinlerine daldı. Ama sivil haklar ve polis yolsuzluğu konusunda da sesini duyuruyordu. Bir bakıma Robin Hood’un modern, çarpık bir sürümü denebilir."] = "BU GERÇEKTEN ÇETİN CEVİZ. ST. CLAİR’İN SUÇLU YANI, KARANLIK BİR GECEDE CEHENNEMİ YAŞARKEN DOĞDU. SONRA YASADIŞI DÜNYANIN DERİNLERİNE DALDI. AMA SİVİL HAKLAR VE POLİS YOLSUZLUĞU KONUSUNDA DA SESİNİ DUYURUYORDU. BİR BAKIMA ROBİN HOOD’UN MODERN, ÇARPIK BİR SÜRÜMÜ DENEBİLİR.",
["Bu giriş kartıyla Belge Arşivine girebiliriz."] = "BU GİRİŞ KARTIYLA BELGE ARŞİVİNE GİREBİLİRİZ.",
["Bu görkemli yüz örtüsünü takıp kudretli bir kükremeyle küresel ısınmaya karşı savaş."] = "BU GÖRKEMLİ YÜZ ÖRTÜSÜNÜ TAKIP KUDRETLİ BİR KÜKREMEYLE KÜRESEL ISINMAYA KARŞI SAVAŞ.",
["Bu göz alıcı kask sana akıcı, aerodinamik bir görünüm verir. Tasarımcısının onu yaparken son ses vaporwave dinlediğine şüphe yok."] = "BU GÖZ ALICI KASK SANA AKICI, AERODİNAMİK BİR GÖRÜNÜM VERİR. TASARIMCISININ ONU YAPARKEN SON SES VAPORWAVE DİNLEDİĞİNE ŞÜPHE YOK.",
["Bu gün suç dünyası için hep özel kalacak. Payday Gang'in Benevolent'ı dize getirdiği gün."] = "BU GÜN SUÇ DÜNYASI İÇİN HEP ÖZEL KALACAK. PAYDAY GANG'İN BENEVOLENT'I DİZE GETİRDİĞİ GÜN.",
["Bu güvenlik düzenini tanıyorum. Konsolun giriş şifresini yakınlarda bir şifre üretim paneli oluşturuyor. Bulalım onu."] = "BU GÜVENLİK DÜZENİNİ TANIYORUM. KONSOLUN GİRİŞ ŞİFRESİNİ YAKINLARDA BİR ŞİFRE ÜRETİM PANELİ OLUŞTURUYOR. BULALIM ONU.",
["Bu güzel olacak."] = "BU GÜZEL OLACAK.",
["Bu güzel silahlardan birkaçını yanımızda götüreceğiz. Ama nasıl, mesele bu..."] = "BU GÜZEL SİLAHLARDAN BİRKAÇINI YANIMIZDA GÖTÜRECEĞİZ. AMA NASIL, MESELE BU...",
["Bu güzelliği almak için bazı tekerlekleri patlatman gerekti."] = "BU GÜZELLİĞİ ALMAK İÇİN BAZI TEKERLEKLERİ PATLATMAN GEREKTİ.",
["Bu güzelliği piyasaya sürünce Rainey sadece parayı kürekle toplamamı izleyebilecek... Ha! Düşüncesi bile içimi ısıtıyor."] = "BU GÜZELLİĞİ PİYASAYA SÜRÜNCE RAİNEY SADECE PARAYI KÜREKLE TOPLAMAMI İZLEYEBİLECEK... HA! DÜŞÜNCESİ BİLE İÇİMİ ISITIYOR.",
["Bu hapishaneyi biliyorsunuz, ne yapacağınızı da biliyorsunuz."] = "BU HAPİSHANEYİ BİLİYORSUNUZ, NE YAPACAĞINIZI DA BİLİYORSUNUZ.",
["Bu harika! Arkadaşlarımla ve ailemle paylaşmayı düşünüyorum."] = "BU HARİKA! ARKADAŞLARIMLA VE AİLEMLE PAYLAŞMAYI DÜŞÜNÜYORUM.",
["Bu hassas bir işlem. Basınç çok düşük olursa hiçbir şey patlamaz. Çok yüksek olursa her şey çok erken patlar. Tam kıvamında olmalı."] = "BU HASSAS BİR İŞLEM. BASINÇ ÇOK DÜŞÜK OLURSA HİÇBİR ŞEY PATLAMAZ. ÇOK YÜKSEK OLURSA HER ŞEY ÇOK ERKEN PATLAR. TAM KIVAMINDA OLMALI.",
["Bu hassas makinenin elektriğe ihtiyacı var. Bir prize bağlayıp çalıştırın."] = "BU HASSAS MAKİNENİN ELEKTRİĞE İHTİYACI VAR. BİR PRİZE BAĞLAYIP ÇALIŞTIRIN.",
["Bu hatunlar, bilirsiniz, kaça patlıyor biliyor musunuz? Her gün? Ama hey, değer."] = "BU HATUNLAR, BİLİRSİNİZ, KAÇA PATLIYOR BİLİYOR MUSUNUZ? HER GÜN? AMA HEY, DEĞER.",
