["Bu iş Teuer galerisine baskın. Üst sınıf bir mekân."] = "BU İŞ TEUER GALERİSİNE BASKIN. ÜST SINIF BİR MEKÂN.",
["Bu iş benim için çok önemli. Batırmadığınızdan emin olmak için buradayım, tamam mı?"] = "BU İŞ BENİM İÇİN ÇOK ÖNEMLİ. BATIRMADIĞINIZDAN EMİN OLMAK İÇİN BURADAYIM, TAMAM MI?",
["Bu iş bitince Bain'in bahsettiği şu plajı satın alalım mı amına koyayım?"] = "BU İŞ BİTİNCE BAIN'İN BAHSETTİĞİ ŞU PLAJI SATIN ALALIM MI AMINA KOYAYIM?",
["Bu iş görür, şimdi matkabı yerleştirebilirsiniz."] = "BU İŞ GÖRÜR, ŞİMDİ MATKABI YERLEŞTİREBİLİRSİNİZ.",
["Bu iş hızlı ve temiz olmalı; hastanelerde güvenlik zayıftır."] = "BU İŞ HIZLI VE TEMİZ OLMALI; HASTANELERDE GÜVENLİK ZAYIFTIR.",
["Bu iş için ateşliyim ekip. Chavez neye uğradığını anlamayacak."] = "BU İŞ İÇİN ATEŞLİYİM EKİP. CHAVEZ NEYE UĞRADIĞINI ANLAMAYACAK.",
["Bu iş için gereken birkaç aleti ayarlamayı başardım. Sandıklarda bulabilirsiniz. Üzerlerinde küçük bir flaş ışığı var."] = "BU İŞ İÇİN GEREKEN BİRKAÇ ALETİ AYARLAMAYI BAŞARDIM. SANDIKLARDA BULABİLİRSİNİZ. ÜZERLERİNDE KÜÇÜK BİR FLAŞ IŞIĞI VAR.",
["Bu iş için yanımıza altı çanta almamız gerek."] = "BU İŞ İÇİN YANIMIZA ALTI ÇANTA ALMAMIZ GEREK.",
["Bu iş için yanımıza sekiz çanta almamız gerek."] = "BU İŞ İÇİN YANIMIZA SEKİZ ÇANTA ALMAMIZ GEREK.",
["Bu iş planlandığı gibi gitmedi millet!"] = "BU İŞ PLANLANDIĞI GİBİ GİTMEDİ MİLLET!",
["Bu iş resmen 'uluslararası kriz' diye bağırıyor."] = "BU İŞ RESMEN 'ULUSLARARASI KRİZ' DİYE BAĞIRIYOR.",
["Bu iş senin için iyi bitmeyecek salak!"] = "BU İŞ SENİN İÇİN İYİ BİTMEYECEK SALAK!",
["Bu iş çok baş ağrıtacak!"] = "BU İŞ ÇOK BAŞ AĞRITACAK!",
["Bu iş önemli. Kamyonlardaki Kasaları çıkarmanız gerek... Şey, sağ salim. Duydunuz mu?"] = "BU İŞ ÖNEMLİ. KAMYONLARDAKİ KASALARI ÇIKARMANIZ GEREK... ŞEY, SAĞ SALİM. DUYDUNUZ MU?",
["Bu iş, sizden bile beklediğimden iyi gidiyor."] = "BU İŞ, SİZDEN BİLE BEKLEDİĞİMDEN İYİ GİDİYOR.",
["Bu işe yaramadı. Başka birini deneyin."] = "BU İŞE YARAMADI. BAŞKA BİRİNİ DENEYİN.",
["Bu işe yaramalı, yeni ayarları onaylayın."] = "BU İŞE YARAMALI, YENİ AYARLARI ONAYLAYIN.",
["Bu işe yarar gibi."] = "BU İŞE YARAR GİBİ.",
["Bu işe yarar. Yakında dönmez. Bozuk chili için mutfak ruhlarına şükürler olsun, ha?"] = "BU İŞE YARAR. YAKINDA DÖNMEZ. BOZUK CHİLİ İÇİN MUTFAK RUHLARINA ŞÜKÜRLER OLSUN, HA?",
["Bu işe yarayabilir."] = "BU İŞE YARAYABİLİR.",
["Bu işe yarayabilir. Aklımızda tutalım dostlar."] = "BU İŞE YARAYABİLİR. AKLIMIZDA TUTALIM DOSTLAR.",
["Bu işe yarayabilir. Oradaki ağa bağlı bir terminal bulun; masaüstü, dizüstü, ne olursa. Veri tabanlarına girersem belki manifestodan bilgi çekebilirim."] = "BU İŞE YARAYABİLİR. ORADAKİ AĞA BAĞLI BİR TERMİNAL BULUN; MASAÜSTÜ, DİZÜSTÜ, NE OLURSA. VERİ TABANLARINA GİRERSEM BELKİ MANİFESTODAN BİLGİ ÇEKEBİLİRİM.",
["Bu işi artık kesin olarak bitirin!"] = "BU İŞİ ARTIK KESİN OLARAK BİTİRİN!",
["Bu işi batıramayız dostlar. Doğru düzgün halletmemiz gerek."] = "BU İŞİ BATIRAMAYIZ DOSTLAR. DOĞRU DÜZGÜN HALLETMEMİZ GEREK.",
["Bu işi benim için çözerseniz size güzel Noel hediyeleri alırım."] = "BU İŞİ BENİM İÇİN ÇÖZERSENİZ SİZE GÜZEL NOEL HEDİYELERİ ALIRIM.",
["Bu işi bitirin. Suç, işi sonuca ulaştıranlara göredir."] = "BU İŞİ BİTİRİN. SUÇ, İŞİ SONUCA ULAŞTIRANLARA GÖREDİR.",
["Bu işi bitiriyorum. Şoför giderken yanında olun, yoksa eve uzun bir yürüyüş var."] = "BU İŞİ BİTİRİYORUM. ŞOFÖR GİDERKEN YANINDA OLUN, YOKSA EVE UZUN BİR YÜRÜYÜŞ VAR.",
["Bu işi bitirme vakti! Yangın alarmını çekin."] = "BU İŞİ BİTİRME VAKTİ! YANGIN ALARMINI ÇEKİN.",
["Bu işi dikkat çekmeden yapalım."] = "BU İŞİ DİKKAT ÇEKMEDEN YAPALIM.",
["Bu işi eski usulle bitirelim, olur mu? Bağlanabilmem için panolara bir sistem kırma bağlantısı takın."] = "BU İŞİ ESKİ USULLE BİTİRELİM, OLUR MU? BAĞLANABİLMEM İÇİN PANOLARA BİR SİSTEM KIRMA BAĞLANTISI TAKIN.",
["Bu işi gürültülü yapıyoruz galiba beyler! Panik odası tecritte, zor yoldan gireceğiz. Bile bize termal mızrak getirecek. Dayanın."] = "BU İŞİ GÜRÜLTÜLÜ YAPIYORUZ GALİBA BEYLER! PANİK ODASI TECRİTTE, ZOR YOLDAN GİRECEĞİZ. BILE BİZE TERMAL MIZRAK GETİRECEK. DAYANIN.",
["Bu işi güzelce, sessizce yapacağız. Aradığımız bilgisayar ikinci katta olmalı."] = "BU İŞİ GÜZELCE, SESSİZCE YAPACAĞIZ. ARADIĞIMIZ BİLGİSAYAR İKİNCİ KATTA OLMALI.",
["Bu işi kolaymış gibi gösteriyorsun."] = "BU İŞİ KOLAYMIŞ GİBİ GÖSTERİYORSUN.",
["Bu işi kârlı kılacak kadar çanta aldık. Harika iş."] = "BU İŞİ KÂRLI KILACAK KADAR ÇANTA ALDIK. HARİKA İŞ.",
["Bu işi nasıl yapacağınız size kalmış..."] = "BU İŞİ NASIL YAPACAĞINIZ SİZE KALMIŞ...",
["Bu işi sağlam bitirelim!"] = "BU İŞİ SAĞLAM BİTİRELİM!",
["Bu işi senden iyi bilen yok."] = "BU İŞİ SENDEN İYİ BİLEN YOK.",
["Bu işi şimdi bitirebilir ya da şık bir şekilde bitirip burayı tamamen boşaltabilirsiniz."] = "BU İŞİ ŞİMDİ BİTİREBİLİR YA DA ŞIK BİR ŞEKİLDE BİTİRİP BURAYI TAMAMEN BOŞALTABİLİRSİNİZ.",
["Bu işin iki yolu var beyler. Gürültülü gidebilirsiniz, onu nasıl yapacağınızı biliyorsunuz. Ama seviyenizi yükseltmek istiyorsanız iki anahtar kartı arayıp kasa dairesini açın. Araba bagajlarına bakmak iyi fikir."] = "BU İŞİN İKİ YOLU VAR BEYLER. GÜRÜLTÜLÜ GİDEBİLİRSİNİZ, ONU NASIL YAPACAĞINIZI BİLİYORSUNUZ. AMA SEVİYENİZİ YÜKSELTMEK İSTİYORSANIZ İKİ ANAHTAR KARTI ARAYIP KASA DAİRESİNİ AÇIN. ARABA BAGAJLARINA BAKMAK İYİ FİKİR.",
["Bu işin şerefine içkiler benden... Mükemmel soygundu millet. "] = "BU İŞİN ŞEREFİNE İÇKİLER BENDEN... MÜKEMMEL SOYGUNDU MİLLET. ",
["Bu işle ilgili tuhaf bir his var içimde. Sanki... bir şekilde kişisel."] = "BU İŞLE İLGİLİ TUHAF BİR HİS VAR İÇİMDE. SANKİ... BİR ŞEKİLDE KİŞİSEL.",
["Bu işlem en yüksek Suç Serisi rütbeni sıfırlar"] = "BU İŞLEM EN YÜKSEK SUÇ SERİSİ RÜTBENİ SIFIRLAR",
["Bu işlem paranı, itibarını ve geliştirmelerini sıfırlar."] = "BU İŞLEM PARANI, İTİBARINI VE GELİŞTİRMELERİNİ SIFIRLAR.",
["Bu işlem silahını varsayılan yapılandırmasına döndürecek."] = "BU İŞLEM SİLAHINI VARSAYILAN YAPILANDIRMASINA DÖNDÜRECEK.",
["Bu işleri kolaylaştırır. İçinizden biri benim için de işaret fişeği yaksa nasıl olur?"] = "BU İŞLERİ KOLAYLAŞTIRIR. İÇİNİZDEN BİRİ BENİM İÇİN DE İŞARET FİŞEĞİ YAKSA NASIL OLUR?",
["Bu işte Locke'un talimatlarına uysak iyi olur. Patlayıcıları kapıya götürün."] = "BU İŞTE LOCKE'UN TALİMATLARINA UYSAK İYİ OLUR. PATLAYICILARI KAPIYA GÖTÜRÜN.",
["Bu işte Mendoza'nın dişlerini söktük. O silahları yok ettiğimiz için artık ısıramayacak, sadece havlayacak. Eminim Hector bizi kesin daha büyük işlere taşır."] = "BU İŞTE MENDOZA'NIN DİŞLERİNİ SÖKTÜK. O SİLAHLARI YOK ETTİĞİMİZ İÇİN ARTIK ISIRAMAYACAK, SADECE HAVLAYACAK. EMİNİM HECTOR BİZİ KESİN DAHA BÜYÜK İŞLERE TAŞIR.",
["Bu işte Money Thrower'ı yanınıza almak isteyebilirsiniz. Söylemiş olayım."] = "BU İŞTE MONEY THROWER'I YANINIZA ALMAK İSTEYEBİLİRSİNİZ. SÖYLEMİŞ OLAYIM.",
["Bu işte bekçilik yapıyoruz. Kalın ceket giyin, daha ağır silahlar taşıyın. Hector'ın nakliyelerine saldırıldığını biliyoruz. Kamyonun arkasında gideceksiniz. Kokainin bir yere gitmesine izin vermeyin."] = "BU İŞTE BEKÇİLİK YAPIYORUZ. KALIN CEKET GİYİN, DAHA AĞIR SİLAHLAR TAŞIYIN. HECTOR'IN NAKLİYELERİNE SALDIRILDIĞINI BİLİYORUZ. KAMYONUN ARKASINDA GİDECEKSİNİZ. KOKAİNİN BİR YERE GİTMESİNE İZİN VERMEYİN.",
["Bu işte bekçilik yapıyoruz. Sağlam bir ceket giyin, daha da sağlam silahlar getirin. Hector'ın sevkiyatlarının saldırıya uğradığını biliyoruz. Kamyonun arkasında gideceksiniz. Kokainin hiçbir yere kaybolmasına izin vermeyin."] = "BU İŞTE BEKÇİLİK YAPIYORUZ. SAĞLAM BİR CEKET GİYİN, DAHA DA SAĞLAM SİLAHLAR GETİRİN. HECTOR'IN SEVKİYATLARININ SALDIRIYA UĞRADIĞINI BİLİYORUZ. KAMYONUN ARKASINDA GİDECEKSİNİZ. KOKAİNİN HİÇBİR YERE KAYBOLMASINA İZİN VERMEYİN.",
["Bu işte bir terslik var. Bir... bir şey..."] = "BU İŞTE BİR TERSLİK VAR. BİR... BİR ŞEY...",
["Bu işte bir tuhaflık var ama bilmiyorum. Tabloları masaya koyun, örümcek hislerinizi açık tutun."] = "BU İŞTE BİR TUHAFLIK VAR AMA BİLMİYORUM. TABLOLARI MASAYA KOYUN, ÖRÜMCEK HİSLERİNİZİ AÇIK TUTUN.",
["Bu işte biraz kokain kaybettik ama daha kötü olabilirdi. Kurtarabildiğimizi kurtardığımız için Hector yine de memnun kalacak."] = "BU İŞTE BİRAZ KOKAİN KAYBETTİK AMA DAHA KÖTÜ OLABİLİRDİ. KURTARABİLDİĞİMİZİ KURTARDIĞIMIZ İÇİN HECTOR YİNE DE MEMNUN KALACAK.",
["Bu işte biraz kokain kaybettik ama daha kötü olabilirdi. Kurtarabildiğimizi kurtardığımız için Hector yine memnun olur."] = "BU İŞTE BİRAZ KOKAİN KAYBETTİK AMA DAHA KÖTÜ OLABİLİRDİ. KURTARABİLDİĞİMİZİ KURTARDIĞIMIZ İÇİN HECTOR YİNE MEMNUN OLUR.",
["Bu işte fena intikam alacağız gibi geliyor dostlar."] = "BU İŞTE FENA İNTİKAM ALACAĞIZ GİBİ GELİYOR DOSTLAR.",
["Bu işte güç için mi varım? Elbette; aksini söylesem yalan olur. Ama gücü, doğru olanı yapmak istediğim için arıyorum."] = "BU İŞTE GÜÇ İÇİN Mİ VARIM? ELBETTE; AKSİNİ SÖYLESEM YALAN OLUR. AMA GÜCÜ, DOĞRU OLANI YAPMAK İSTEDİĞİM İÇİN ARIYORUM.",
["Bu işte tuhaf boklar dönüyor."] = "BU İŞTE TUHAF BOKLAR DÖNÜYOR.",
["Bu işte yanımıza üç çanta almalıyız."] = "BU İŞTE YANIMIZA ÜÇ ÇANTA ALMALIYIZ.",
["Bu işte şehrin lüks otomobil galerilerinden birini vuracağız. Teuer otomobil bayisini."] = "BU İŞTE ŞEHRİN LÜKS OTOMOBİL GALERİLERİNDEN BİRİNİ VURACAĞIZ. TEUER OTOMOBİL BAYİSİNİ.",
["Bu işten en azından biraz ek para çıkarmak iyi olur, gidip o testereyi bulun, tamam mı?"] = "BU İŞTEN EN AZINDAN BİRAZ EK PARA ÇIKARMAK İYİ OLUR, GİDİP O TESTEREYİ BULUN, TAMAM MI?",
["Bu işten kaçmak yok. Bain'in başlattığını bitireceğiz."] = "BU İŞTEN KAÇMAK YOK. BAIN'İN BAŞLATTIĞINI BİTİRECEĞİZ.",
["Bu işten konuşarak kurtulabiliriz sanmıyorum!"] = "BU İŞTEN KONUŞARAK KURTULABİLİRİZ SANMIYORUM!",
["Bu kabin Kang'ın. Bilmek iyi oldu."] = "BU KABİN KANG'IN. BİLMEK İYİ OLDU.",
["Bu kabuğun altında delilik mi var? Takan kişiyi mi temsil ediyor, yoksa soyguncuların kanuna duyduğu küçümsemenin bir yansıması mı?"] = "BU KABUĞUN ALTINDA DELİLİK Mİ VAR? TAKAN KİŞİYİ Mİ TEMSİL EDİYOR, YOKSA SOYGUNCULARIN KANUNA DUYDUĞU KÜÇÜMSEMENİN BİR YANSIMASI MI?",
["Bu kadar aptal olduğuna inanamıyorum."] = "BU KADAR APTAL OLDUĞUNA İNANAMIYORUM.",
["Bu kadar büyük bir para yığınını vicdanınız rahat bir şekilde yakmak her gün nasip olmaz, ha?"] = "BU KADAR BÜYÜK BİR PARA YIĞININI VİCDANINIZ RAHAT BİR ŞEKİLDE YAKMAK HER GÜN NASİP OLMAZ, HA?",
["Bu kadar erken eve dönmem..."] = "BU KADAR ERKEN EVE DÖNMEM...",
["Bu kadar gösterişli bir silahşor toprağın altını hak etmez! Sombrerona toprak bulaşır! Düellolarla ilgili küçük bir sır: Vurulmak kaybettiğin anlamına gelmez. Yalnızca yeniden kalkamazsan kaybedersin."] = "BU KADAR GÖSTERİŞLİ BİR SİLAHŞOR TOPRAĞIN ALTINI HAK ETMEZ! SOMBRERONA TOPRAK BULAŞIR! DÜELLOLARLA İLGİLİ KÜÇÜK BİR SIR: VURULMAK KAYBETTİĞİN ANLAMINA GELMEZ. YALNIZCA YENİDEN KALKAMAZSAN KAYBEDERSİN.",
["Bu kadar ilerledikten sonra fark edilmek istemezsiniz. Yanından gizlice geçmeye çalışın."] = "BU KADAR İLERLEDİKTEN SONRA FARK EDİLMEK İSTEMEZSİNİZ. YANINDAN GİZLİCE GEÇMEYE ÇALIŞIN.",
["Bu kadar ilerleyeceğimizi hiç düşünür müydünüz, sizi otuzbirciler?"] = "BU KADAR İLERLEYECEĞİMİZİ HİÇ DÜŞÜNÜR MÜYDÜNÜZ, SİZİ OTUZBİRCİLER?",
["Bu kadar küçük alanda bu kadar büyük değer."] = "BU KADAR KÜÇÜK ALANDA BU KADAR BÜYÜK DEĞER.",
["Bu kadar parayı bu kadar çabuk harcamamalıydık."] = "BU KADAR PARAYI BU KADAR ÇABUK HARCAMAMALIYDIK.",
["Bu kadar sandık varsa buralarda bir yerde levye de olmalı."] = "BU KADAR SANDIK VARSA BURALARDA BİR YERDE LEVYE DE OLMALI.",
["Bu kadar yeter..."] = "BU KADAR YETER...",
["Bu kadar çok paranın ziyan olduğunu hiç GÖRMEDİM! Hadi, son kalanları alın!"] = "BU KADAR ÇOK PARANIN ZİYAN OLDUĞUNU HİÇ GÖRMEDİM! HADİ, SON KALANLARI ALIN!",
["Bu kadar! Daha fazla kalamam!"] = "BU KADAR! DAHA FAZLA KALAMAM!",
["Bu kadar! Şimdi gidiyorum!"] = "BU KADAR! ŞİMDİ GİDİYORUM!",
["Bu kadar. Bir ekip göndermem ve polise haber vermem gerekiyor."] = "BU KADAR. BİR EKİP GÖNDERMEM VE POLİSE HABER VERMEM GEREKİYOR.",
["Bu kadarı yeter domuzcuk. Yeter."] = "BU KADARI YETER DOMUZCUK. YETER.",
["Bu kadarıyla idare edeceğiz. Yakında Jiu Feng'in adamının sürdüğü bir mini yükleyici var. Vlad'ın kovaya binmesine yardım edin."] = "BU KADARIYLA İDARE EDECEĞİZ. YAKINDA JIU FENG'İN ADAMININ SÜRDÜĞÜ BİR MİNİ YÜKLEYİCİ VAR. VLAD'IN KOVAYA BİNMESİNE YARDIM EDİN.",
["Bu kamyonlardan biri aradığımız. İpuçlarını aramayı bitirince hedef sandığınız kamyona cihazı takın. Tek şansınız var, emin olun."] = "BU KAMYONLARDAN BİRİ ARADIĞIMIZ. İPUÇLARINI ARAMAYI BİTİRİNCE HEDEF SANDIĞINIZ KAMYONA CİHAZI TAKIN. TEK ŞANSINIZ VAR, EMİN OLUN.",
["Bu kaplamayı silmek istediğinden emin misin?"] = "BU KAPLAMAYI SİLMEK İSTEDİĞİNDEN EMİN MİSİN?",
["Bu kapüşonlunun rengi sarı olabilir ama cesareti tam!"] = "BU KAPÜŞONLUNUN RENGİ SARI OLABİLİR AMA CESARETİ TAM!",
["Bu kapüşonluyu artık kimse giymiyor bile."] = "BU KAPÜŞONLUYU ARTIK KİMSE GİYMİYOR BİLE.",
["Bu kapı bir tür manyetik mekanizmayla kilitli. Açmanın bir yolunu bulun!"] = "BU KAPI BİR TÜR MANYETİK MEKANİZMAYLA KİLİTLİ. AÇMANIN BİR YOLUNU BULUN!",
["Bu kapı cehennem gibi sağlam. GenSec işini biliyor."] = "BU KAPI CEHENNEM GİBİ SAĞLAM. GENSEC İŞİNİ BİLİYOR.",
["Bu kapıdan geçmek için Anahtar Kartı gerekiyor. Ana binanın içine bak."] = "BU KAPIDAN GEÇMEK İÇİN ANAHTAR KARTI GEREKİYOR. ANA BİNANIN İÇİNE BAK.",
["Bu kapıdan geçmek için Anahtar Kartı gerekiyor. Ana binayı ara."] = "BU KAPIDAN GEÇMEK İÇİN ANAHTAR KARTI GEREKİYOR. ANA BİNAYI ARA.",
["Bu kapıdan geçmek için pürmüz kullanmanız gerekecek. Çabuk olun."] = "BU KAPIDAN GEÇMEK İÇİN PÜRMÜZ KULLANMANIZ GEREKECEK. ÇABUK OLUN.",
["Bu kapıdan para baskı kalıplarına ulaşabiliriz. "] = "BU KAPIDAN PARA BASKI KALIPLARINA ULAŞABİLİRİZ. ",
["Bu kapıları açmak için Anahtar Kartı kullanabilirsiniz."] = "BU KAPILARI AÇMAK İÇİN ANAHTAR KARTI KULLANABİLİRSİNİZ.",
["Bu kapının Anahtar Kartı, Buluc'un özel korumalarından birinde. Duyduğuma göre pek parlak değillermiş. Kimde olduğunu unutmamak için bir yere yazıyorlardır muhtemelen."] = "BU KAPININ ANAHTAR KARTI, BULUC'UN ÖZEL KORUMALARINDAN BİRİNDE. DUYDUĞUMA GÖRE PEK PARLAK DEĞİLLERMİŞ. KİMDE OLDUĞUNU UNUTMAMAK İÇİN BİR YERE YAZIYORLARDIR MUHTEMELEN.",
["Bu kapının diziliminin Buluc'un evdeki ‘mahrem mabedinde’ bulunabileceğini öğrendim. İşe koyulun, çabuk çabuk."] = "BU KAPININ DİZİLİMİNİN BULUC'UN EVDEKİ ‘MAHREM MABEDİNDE’ BULUNABİLECEĞİNİ ÖĞRENDİM. İŞE KOYULUN, ÇABUK ÇABUK.",
["Bu kapının iki aşamalı güvenlik protokolü var. İlk aşama Anahtar Kartını kullanmak. O yüzden... buyurun lütfen."] = "BU KAPININ İKİ AŞAMALI GÜVENLİK PROTOKOLÜ VAR. İLK AŞAMA ANAHTAR KARTINI KULLANMAK. O YÜZDEN... BUYURUN LÜTFEN.",
["Bu kapının sistemini kırmanız gerekiyor!"] = "BU KAPININ SİSTEMİNİ KIRMANIZ GEREKİYOR!",
["Bu kapıya Anahtar Kartı gerekiyor gibi. Bir tane bulun, millet!"] = "BU KAPIYA ANAHTAR KARTI GEREKİYOR GİBİ. BİR TANE BULUN, MİLLET!",
["Bu kapıyı açan bir şifre var. Buluc'un iç mabedinde bulunabileceğini öğrenebildim, artık her neyse."] = "BU KAPIYI AÇAN BİR ŞİFRE VAR. BULUC'UN İÇ MABEDİNDE BULUNABİLECEĞİNİ ÖĞRENEBİLDİM, ARTIK HER NEYSE.",
["Bu kapıyı açmalıyım. Bir dakika verin!"] = "BU KAPIYI AÇMALIYIM. BİR DAKİKA VERİN!",
["Bu kapıyı açmam gerek. Bir dakika verin!"] = "BU KAPIYI AÇMAM GEREK. BİR DAKİKA VERİN!",
["Bu kapıyı geçemiyorum. Otomatik gibi, kontrol panosunu bulup kilidini aşın."] = "BU KAPIYI GEÇEMİYORUM. OTOMATİK GİBİ, KONTROL PANOSUNU BULUP KİLİDİNİ AŞIN.",
["Bu karakter henüz yüklü değil."] = "BU KARAKTER HENÜZ YÜKLÜ DEĞİL.",
["Bu karlı piçler fena vuruyor! En azından papyonları sevimli, değil mi?"] = "BU KARLI PİÇLER FENA VURUYOR! EN AZINDAN PAPYONLARI SEVİMLİ, DEĞİL Mİ?",
["Bu karmaşanın arkasında kim varsa birazdan ağır bir darbe yiyecek. Birini soymak için adını bilmen gerekmez. Biz hep yapıyoruz."] = "BU KARMAŞANIN ARKASINDA KİM VARSA BİRAZDAN AĞIR BİR DARBE YİYECEK. BİRİNİ SOYMAK İÇİN ADINI BİLMEN GEREKMEZ. BİZ HEP YAPIYORUZ.",
["Bu kartel adamları işi şansa bırakmıyor. Kapıya elektrik bağlamışlar."] = "BU KARTEL ADAMLARI İŞİ ŞANSA BIRAKMIYOR. KAPIYA ELEKTRİK BAĞLAMIŞLAR.",
["Bu kasa dairesi nakitle dolu! Altından kalkabilirseniz hepsini alabilirsiniz!"] = "BU KASA DAİRESİ NAKİTLE DOLU! ALTINDAN KALKABİLİRSENİZ HEPSİNİ ALABİLİRSİNİZ!",
["Bu kasa dairesi tipini biliyorum... Öylece açamayız."] = "BU KASA DAİRESİ TİPİNİ BİLİYORUM... ÖYLECE AÇAMAYIZ.",
["Bu kasa dairesi çetin ceviz ama iyi bir aletin çözemeyeceği şey yok. Çatıya gidip bir çelik halat kurun."] = "BU KASA DAİRESİ ÇETİN CEVİZ AMA İYİ BİR ALETİN ÇÖZEMEYECEĞİ ŞEY YOK. ÇATIYA GİDİP BİR ÇELİK HALAT KURUN.",
["Bu kasa devre dışı bırakıldı!"] = "BU KASA DEVRE DIŞI BIRAKILDI!",
["Bu katta girebileceğiniz bir kapı olmalı... Testere kullanırsanız tabii, ha?"] = "BU KATTA GİREBİLECEĞİNİZ BİR KAPI OLMALI... TESTERE KULLANIRSANIZ TABİİ, HA?",
["Bu kattaki kapılardan birini testereyle kesip geçebilirsiniz büyük ihtimalle, ha?"] = "BU KATTAKİ KAPILARDAN BİRİNİ TESTEREYLE KESİP GEÇEBİLİRSİNİZ BÜYÜK İHTİMALLE, HA?",
["Bu kavanoz iyi bir Hafif Makineli Silahın yıkıcı işinin kanıtını içeriyor."] = "BU KAVANOZ İYİ BİR HAFİF MAKİNELİ SİLAHIN YIKICI İŞİNİN KANITINI İÇERİYOR.",
["Bu kaçış biraz çılgınca olabilir, dostlar. Önce ilk iş: Lokomotifimize yakıt doldurup vagondan ayırın."] = "BU KAÇIŞ BİRAZ ÇILGINCA OLABİLİR, DOSTLAR. ÖNCE İLK İŞ: LOKOMOTİFİMİZE YAKIT DOLDURUP VAGONDAN AYIRIN.",
["Bu kaçışı adım adım yapacağız. Birinci adım: Lokomotife yakıt doldurun ve vagonlarla bağlantısını ayırın."] = "BU KAÇIŞI ADIM ADIM YAPACAĞIZ. BİRİNCİ ADIM: LOKOMOTİFE YAKIT DOLDURUN VE VAGONLARLA BAĞLANTISINI AYIRIN.",
["Bu kaçışı başarırsanız ‘tren soygunu’ kavramını yepyeni bir seviyeye taşıyacaksınız."] = "BU KAÇIŞI BAŞARIRSANIZ ‘TREN SOYGUNU’ KAVRAMINI YEPYENİ BİR SEVİYEYE TAŞIYACAKSINIZ.",
["Bu kesin federalleri getirir. Keçileri buradan çıkarmanın yolunu düşünmem gerek."] = "BU KESİN FEDERALLERİ GETİRİR. KEÇİLERİ BURADAN ÇIKARMANIN YOLUNU DÜŞÜNMEM GEREK.",
["Bu kesin işimize yarayacak. Şimdi dönüp yakarak açın."] = "BU KESİN İŞİMİZE YARAYACAK. ŞİMDİ DÖNÜP YAKARAK AÇIN.",
["Bu kesin kasa dairesi."] = "BU KESİN KASA DAİRESİ.",
["Bu kesin oy makinelerinden birine benziyor. Demokrasiyi öldürmeye hazır olduğunuzda sistemi kırmaya başlayın. Kimse görmesin."] = "BU KESİN OY MAKİNELERİNDEN BİRİNE BENZİYOR. DEMOKRASİYİ ÖLDÜRMEYE HAZIR OLDUĞUNUZDA SİSTEMİ KIRMAYA BAŞLAYIN. KİMSE GÖRMESİN.",
["Bu kesinlikle Anahtar Kartı. Alın!"] = "BU KESİNLİKLE ANAHTAR KARTI. ALIN!",
["Bu kesinlikle OVERKILL'di! Neyse, tırmanma vakti beyler!"] = "BU KESİNLİKLE OVERKILL'Dİ! NEYSE, TIRMANMA VAKTİ BEYLER!",
["Bu kesinlikle tünel girişi."] = "BU KESİNLİKLE TÜNEL GİRİŞİ.",
["Bu kez odaklanın. Basın!"] = "BU KEZ ODAKLANIN. BASIN!",
["Bu kez yanlış adamlara bulaştılar amına koyayım..."] = "BU KEZ YANLIŞ ADAMLARA BULAŞTILAR AMINA KOYAYIM...",
["Bu keşmekeşi geride bırakma vakti! HEMEN çıkın oradan!"] = "BU KEŞMEKEŞİ GERİDE BIRAKMA VAKTİ! HEMEN ÇIKIN ORADAN!",
["Bu kitapların pek değerli olduğunu sanmıyorum. En azından bizim için."] = "BU KİTAPLARIN PEK DEĞERLİ OLDUĞUNU SANMIYORUM. EN AZINDAN BİZİM İÇİN.",
["Bu klasik parça isabeti ve dengeyi artırır ama bastırmayı etkiler."] = "BU KLASİK PARÇA İSABETİ VE DENGEYİ ARTIRIR AMA BASTIRMAYI ETKİLER.",
["Bu kod sergi kutusunun kilidini açacak!"] = "BU KOD SERGİ KUTUSUNUN KİLİDİNİ AÇACAK!",
["Bu kokain artık terörü finanse etmeyecek. Sadece eski usul Amerikan suçunu."] = "BU KOKAİN ARTIK TERÖRÜ FİNANSE ETMEYECEK. SADECE ESKİ USUL AMERİKAN SUÇUNU.",
["Bu kokaini kaybedersem Noel bütçem sikilir. Benim için bulun!"] = "BU KOKAİNİ KAYBEDERSEM NOEL BÜTÇEM SİKİLİR. BENİM İÇİN BULUN!",
["Bu kolay bir iş. Girin, kokaini alın ve çıkın."] = "BU KOLAY BİR İŞ. GİRİN, KOKAİNİ ALIN VE ÇIKIN.",
["Bu kolluk kuvvetleri fena kararlı amına koyayım!"] = "BU KOLLUK KUVVETLERİ FENA KARARLI AMINA KOYAYIM!",
["Bu konuda bana biraz katlanın. Döner tablayı kapattılar ama sahadaki yük vinci hâlâ çalışıyor. Lokomotifimizi açık bir raya kaldırabileceğinden... yüzde yetmiş eminim. Kumandalara gidin de öğrenelim!"] = "BU KONUDA BANA BİRAZ KATLANIN. DÖNER TABLAYI KAPATTILAR AMA SAHADAKİ YÜK VİNCİ HÂLÂ ÇALIŞIYOR. LOKOMOTİFİMİZİ AÇIK BİR RAYA KALDIRABİLECEĞİNDEN... YÜZDE YETMİŞ EMİNİM. KUMANDALARA GİDİN DE ÖĞRENELİM!",
["Bu konuda gerçekten biraz okuyup bilgi edinmeliyim, değil mi?"] = "BU KONUDA GERÇEKTEN BİRAZ OKUYUP BİLGİ EDİNMELİYİM, DEĞİL Mİ?",
["Bu konuları biraz okumam gerek, ha?"] = "BU KONULARI BİRAZ OKUMAM GEREK, HA?",
["Bu kullanıma hazır, güçlü bir patlayıcı; nazik davranın."] = "BU KULLANIMA HAZIR, GÜÇLÜ BİR PATLAYICI; NAZİK DAVRANIN.",
["Bu kullanışlı ve rahat takımın beyaz çeşidi."] = "BU KULLANIŞLI VE RAHAT TAKIMIN BEYAZ ÇEŞİDİ.",
["Bu kullanışlı ve rahat takımın kırmızı çeşidi."] = "BU KULLANIŞLI VE RAHAT TAKIMIN KIRMIZI ÇEŞİDİ.",
["Bu kullanışlı ve rahat takımın siyah çeşidi."] = "BU KULLANIŞLI VE RAHAT TAKIMIN SİYAH ÇEŞİDİ.",
["Bu kutularda ne var?"] = "BU KUTULARDA NE VAR?",
["Bu kutuları riske atmam. Hepsini arayın."] = "BU KUTULARI RİSKE ATMAM. HEPSİNİ ARAYIN.",
["Bu kuyruğu atlatamıyorum!"] = "BU KUYRUĞU ATLATAMIYORUM!",
["Bu kuş düşüyor galiba. Üzgünüm patron!"] = "BU KUŞ DÜŞÜYOR GALİBA. ÜZGÜNÜM PATRON!",
["Bu kâğıtların arasında olmalı. Bakalım. Bu B7040, bu değil. Bir FU5000. Hayır, aramaya devam edeyim..."] = "BU KÂĞITLARIN ARASINDA OLMALI. BAKALIM. BU B7040, BU DEĞİL. BİR FU5000. HAYIR, ARAMAYA DEVAM EDEYİM...",
["Bu küçük alışveriş merkezindeki dükkânları yağmalayın."] = "BU KÜÇÜK ALIŞVERİŞ MERKEZİNDEKİ DÜKKÂNLARI YAĞMALAYIN.",
["Bu küçük alışveriş sırasındaki dükkânları yağmalayın."] = "BU KÜÇÜK ALIŞVERİŞ SIRASINDAKİ DÜKKÂNLARI YAĞMALAYIN.",
["Bu küçük oyuncakçı dükkânını işleten serseriler bunlar. Yaramaz çocuklardı. İndirin ve içeri girin."] = "BU KÜÇÜK OYUNCAKÇI DÜKKÂNINI İŞLETEN SERSERİLER BUNLAR. YARAMAZ ÇOCUKLARDI. İNDİRİN VE İÇERİ GİRİN.",
["Bu kırmızı alın bandını takan askerin kimliği gizli. Sızan raporlar, gerilla taktiklerinde uzman bir savaş gazisinden ve eski bir U.S. Army Special Forces askerinden söz ediyor. Silah arkadaşları onu sert, gözü kara ve aşırı saldırgan diye tanımlıyordu. İzini bulup katlettiği üst düzey subay sayısına bakılırsa otoriteyle ciddi bir sorunu olabilir..."] = "BU KIRMIZI ALIN BANDINI TAKAN ASKERİN KİMLİĞİ GİZLİ. SIZAN RAPORLAR, GERİLLA TAKTİKLERİNDE UZMAN BİR SAVAŞ GAZİSİNDEN VE ESKİ BİR U.S. ARMY SPECIAL FORCES ASKERİNDEN SÖZ EDİYOR. SİLAH ARKADAŞLARI ONU SERT, GÖZÜ KARA VE AŞIRI SALDIRGAN DİYE TANIMLIYORDU. İZİNİ BULUP KATLETTİĞİ ÜST DÜZEY SUBAY SAYISINA BAKILIRSA OTORİTEYLE CİDDİ BİR SORUNU OLABİLİR...",
["Bu kıyafet, dövüş tarzını uygularken hız ve hareket özgürlüğü sağlar. Belalı zarafeti de inkâr edilemez."] = "BU KIYAFET, DÖVÜŞ TARZINI UYGULARKEN HIZ VE HAREKET ÖZGÜRLÜĞÜ SAĞLAR. BELALI ZARAFETİ DE İNKÂR EDİLEMEZ.",
["Bu kıyafet, yeraltı dünyasının bir generaline yaraşır. İki farklı görünüşü vardır. Gururla giy ve dünyaya izini bırak."] = "BU KIYAFET, YERALTI DÜNYASININ BİR GENERALİNE YARAŞIR. İKİ FARKLI GÖRÜNÜŞÜ VARDIR. GURURLA GİY VE DÜNYAYA İZİNİ BIRAK.",
["Bu kıyafetin beyaz ipliklerinin simgelediği ölüm, günahları peşlerine düştüğünde bütün kartel liderlerinin varacağı yerdir."] = "BU KIYAFETİN BEYAZ İPLİKLERİNİN SİMGELEDİĞİ ÖLÜM, GÜNAHLARI PEŞLERİNE DÜŞTÜĞÜNDE BÜTÜN KARTEL LİDERLERİNİN VARACAĞI YERDİR.",
["Bu laboratuvar fareleri tabii ki geç saate kadar çalışıyor. İdari binada anons sistemi olmalı. Onunla dışarı çıkaralım."] = "BU LABORATUVAR FARELERİ TABİİ Kİ GEÇ SAATE KADAR ÇALIŞIYOR. İDARİ BİNADA ANONS SİSTEMİ OLMALI. ONUNLA DIŞARI ÇIKARALIM.",
["Bu lanet bir polis pususu!"] = "BU LANET BİR POLİS PUSUSU!",
["Bu lanet kapı çok sağlam, matkaba fazla gelir. Açacak bir şey için cephaneliğe baksanız iyi olur."] = "BU LANET KAPI ÇOK SAĞLAM, MATKABA FAZLA GELİR. AÇACAK BİR ŞEY İÇİN CEPHANELİĞE BAKSANIZ İYİ OLUR.",
["Bu lanet yer labirent gibi."] = "BU LANET YER LABİRENT GİBİ.",
["Bu lanet yerden geçemeyiz. Dışarıda bir iskele var. İkinci katta zayıf bir nokta bulmaya çalışın, tamam mı?"] = "BU LANET YERDEN GEÇEMEYİZ. DIŞARIDA BİR İSKELE VAR. İKİNCİ KATTA ZAYIF BİR NOKTA BULMAYA ÇALIŞIN, TAMAM MI?",
["Bu lobiden ayrılmak istediğinden emin misin?"] = "BU LOBİDEN AYRILMAK İSTEDİĞİNDEN EMİN MİSİN?",
["Bu mahallede polis var. Davetsiz parti misafirlerini sevmezler."] = "BU MAHALLEDE POLİS VAR. DAVETSİZ PARTİ MİSAFİRLERİNİ SEVMEZLER.",
["Bu makineler çerez parası. Biz daha büyük bir ödül için buradayız."] = "BU MAKİNELER ÇEREZ PARASI. BİZ DAHA BÜYÜK BİR ÖDÜL İÇİN BURADAYIZ.",
["Bu makineler üç kuruş peşinde koşan enayiler için. Vaktinizi boşa harcamayın."] = "BU MAKİNELER ÜÇ KURUŞ PEŞİNDE KOŞAN ENAYİLER İÇİN. VAKTİNİZİ BOŞA HARCAMAYIN.",
["Bu malları yeniden gördüğüme sevindim. İyi kurtardınız çocuklar."] = "BU MALLARI YENİDEN GÖRDÜĞÜME SEVİNDİM. İYİ KURTARDINIZ ÇOCUKLAR.",
["Bu malzeme tehlikeli. Çıkarmaya çalışın ama asıl hedefi unutmayın."] = "BU MALZEME TEHLİKELİ. ÇIKARMAYA ÇALIŞIN AMA ASIL HEDEFİ UNUTMAYIN.",
["Bu malzemeden kanı yıkayıp çıkarmak çok kolay!"] = "BU MALZEMEDEN KANI YIKAYIP ÇIKARMAK ÇOK KOLAY!",
["Bu mangal için tutuşturucu sıvı lazım!"] = "BU MANGAL İÇİN TUTUŞTURUCU SIVI LAZIM!",
["Bu manyağın ini ileride olmalı."] = "BU MANYAĞIN İNİ İLERİDE OLMALI.",
["Bu maske antik taştan yapılmış. Önceki sahiplerinin her birinden kalma oymalar ve muazzam güç yayan bir simge taşıyor. Kenarındaki yazının da söylediği gibi, onu takana karşı gelenler için sonun başlangıcıdır."] = "BU MASKE ANTİK TAŞTAN YAPILMIŞ. ÖNCEKİ SAHİPLERİNİN HER BİRİNDEN KALMA OYMALAR VE MUAZZAM GÜÇ YAYAN BİR SİMGE TAŞIYOR. KENARINDAKİ YAZININ DA SÖYLEDİĞİ GİBİ, ONU TAKANA KARŞI GELENLER İÇİN SONUN BAŞLANGICIDIR.",
["Bu maske baştan ayağa tam bir soygun kıyafetinin parçası olarak tasarlandı. Ama saha testleri, gösterişli spandeks kıyafetin mermiye, bıçağa veya el bombasına karşı koruma sağlamadığını ortaya koydu. Maskeyse hafif, dayanıklı ve şık bulundu. Soygun zamanı!"] = "BU MASKE BAŞTAN AYAĞA TAM BİR SOYGUN KIYAFETİNİN PARÇASI OLARAK TASARLANDI. AMA SAHA TESTLERİ, GÖSTERİŞLİ SPANDEKS KIYAFETİN MERMİYE, BIÇAĞA VEYA EL BOMBASINA KARŞI KORUMA SAĞLAMADIĞINI ORTAYA KOYDU. MASKEYSE HAFİF, DAYANIKLI VE ŞIK BULUNDU. SOYGUN ZAMANI!",
["Bu maske derinlere kök salmış bir psikolojik sorunun yansıması mı? Belki çoklu kişilik bozukluğu? Şizofreni? Bozulmuş bir ruhun travması? Yoksa bunların yansıması değil de doğrudan sebebi mi?"] = "BU MASKE DERİNLERE KÖK SALMIŞ BİR PSİKOLOJİK SORUNUN YANSIMASI MI? BELKİ ÇOKLU KİŞİLİK BOZUKLUĞU? ŞİZOFRENİ? BOZULMUŞ BİR RUHUN TRAVMASI? YOKSA BUNLARIN YANSIMASI DEĞİL DE DOĞRUDAN SEBEBİ Mİ?",
["Bu maske sanki muzip bir kötülük yayıyor. Ona bakan çoğu kişinin içine anında bir huzursuzluk çöküyor; banka soyarken de tam böyle bir şeye ihtiyacın var!"] = "BU MASKE SANKİ MUZİP BİR KÖTÜLÜK YAYIYOR. ONA BAKAN ÇOĞU KİŞİNİN İÇİNE ANINDA BİR HUZURSUZLUK ÇÖKÜYOR; BANKA SOYARKEN DE TAM BÖYLE BİR ŞEYE İHTİYACIN VAR!",
["Bu maske yuvasını kuşandığında tercih ettiğin karakterin maskesini takarsın."] = "BU MASKE YUVASINI KUŞANDIĞINDA TERCİH ETTİĞİN KARAKTERİN MASKESİNİ TAKARSIN.",
["Bu maske, ailesinde nesillerdir saklanan yaşlı bir çiftçide bulundu. Adam satmayı reddedince Buluc’un adamları büyük bir zalimlikle çiftliğini ve geçim kaynağını yakıp onu mecbur bıraktı. Umarız bu tarihî eserin gelecekteki sahiplerinin talihi daha iyi olur ve daha az barbarca davranırlar."] = "BU MASKE, AİLESİNDE NESİLLERDİR SAKLANAN YAŞLI BİR ÇİFTÇİDE BULUNDU. ADAM SATMAYI REDDEDİNCE BULUC’UN ADAMLARI BÜYÜK BİR ZALİMLİKLE ÇİFTLİĞİNİ VE GEÇİM KAYNAĞINI YAKIP ONU MECBUR BIRAKTI. UMARIZ BU TARİHÎ ESERİN GELECEKTEKİ SAHİPLERİNİN TALİHİ DAHA İYİ OLUR VE DAHA AZ BARBARCA DAVRANIRLAR.",
["Bu maske, onu takan adamın tam tersine güç ve kaba kuvvet saçıyor. Palyaçoya özgü hüzün ile gönülsüz öfkeyi eşit ölçüde taşıyarak, biraz istemeye istemeye soygunculuğu seçmiş birinin ruh hâlini kusursuzca yansıtıyor."] = "BU MASKE, ONU TAKAN ADAMIN TAM TERSİNE GÜÇ VE KABA KUVVET SAÇIYOR. PALYAÇOYA ÖZGÜ HÜZÜN İLE GÖNÜLSÜZ ÖFKEYİ EŞİT ÖLÇÜDE TAŞIYARAK, BİRAZ İSTEMEYE İSTEMEYE SOYGUNCULUĞU SEÇMİŞ BİRİNİN RUH HÂLİNİ KUSURSUZCA YANSITIYOR.",
["Bu maske, tuhaf Dr Rudolf Mastaba’nın deneylerine dayanıyor. Çağdaş bir Prometheus olan doktor, Sanayi Devrimi teknolojisini kullanarak ölüleri diriltmeye çalıştı. Söylentiye göre kısmen başardı da: Ölüler dirildi ama buğdaya, arpaya ve mısıra karşı doymak bilmez bir iştahları vardı."] = "BU MASKE, TUHAF DR RUDOLF MASTABA’NIN DENEYLERİNE DAYANIYOR. ÇAĞDAŞ BİR PROMETHEUS OLAN DOKTOR, SANAYİ DEVRİMİ TEKNOLOJİSİNİ KULLANARAK ÖLÜLERİ DİRİLTMEYE ÇALIŞTI. SÖYLENTİYE GÖRE KISMEN BAŞARDI DA: ÖLÜLER DİRİLDİ AMA BUĞDAYA, ARPAYA VE MISIRA KARŞI DOYMAK BİLMEZ BİR İŞTAHLARI VARDI.",
["Bu maske, uzak bir yerden gelen gizemli bir savaşçıya aitti. Sezgileriyle yol bulup dünyadaki kötücül güçleri avlayarak diyarları dolaşırdı. Zindanlara girip karşılaştığı binlerce kötü varlığı öldürdü. Sonunda gelecek neslin yolunu sürdüreceğini bilerek huzur buldu."] = "BU MASKE, UZAK BİR YERDEN GELEN GİZEMLİ BİR SAVAŞÇIYA AİTTİ. SEZGİLERİYLE YOL BULUP DÜNYADAKİ KÖTÜCÜL GÜÇLERİ AVLAYARAK DİYARLARI DOLAŞIRDI. ZİNDANLARA GİRİP KARŞILAŞTIĞI BİNLERCE KÖTÜ VARLIĞI ÖLDÜRDÜ. SONUNDA GELECEK NESLİN YOLUNU SÜRDÜRECEĞİNİ BİLEREK HUZUR BULDU.",
["Bu maskenin dehşetini salıp hem polislere hem sivillere 1960’ların bir korku filminde olduklarını düşündür."] = "BU MASKENİN DEHŞETİNİ SALIP HEM POLİSLERE HEM SİVİLLERE 1960’LARIN BİR KORKU FİLMİNDE OLDUKLARINI DÜŞÜNDÜR.",
["Bu maskenin içinde imza yok. Demek ki Eduardo Maquevera’nın kendisi değil, çıraklarından biri yapmış."] = "BU MASKENİN İÇİNDE İMZA YOK. DEMEK Kİ EDUARDO MAQUEVERA’NIN KENDİSİ DEĞİL, ÇIRAKLARINDAN BİRİ YAPMIŞ.",
["Bu maskenin kilidini açmak için Aldstone’s Heritage işlerinden \"Sommelier en herbe\" görevini tamamla."] = "BU MASKENİN KİLİDİNİ AÇMAK İÇİN ALDSTONE’S HERİTAGE İŞLERİNDEN \"SOMMELİER EN HERBE\" GÖREVİNİ TAMAMLA.",
["Bu maskenin kilidini açmak için Aldstone’s Heritage işlerinden \"The Briefcase\" görevini tamamla."] = "BU MASKENİN KİLİDİNİ AÇMAK İÇİN ALDSTONE’S HERİTAGE İŞLERİNDEN \"THE BRİEFCASE\" GÖREVİNİ TAMAMLA.",
["Bu maskenin kilidini açmak için Aldstone’s Heritage işlerinden \"The Historical Reports\" görevini tamamla."] = "BU MASKENİN KİLİDİNİ AÇMAK İÇİN ALDSTONE’S HERİTAGE İŞLERİNDEN \"THE HİSTORİCAL REPORTS\" GÖREVİNİ TAMAMLA.",
["Bu maskenin kilidini açmak için Aldstone’s Heritage işlerinden \"The War Room\" görevini tamamla."] = "BU MASKENİN KİLİDİNİ AÇMAK İÇİN ALDSTONE’S HERİTAGE İŞLERİNDEN \"THE WAR ROOM\" GÖREVİNİ TAMAMLA.",
["Bu maskenin yanında, yapımcısı Eduardo Maquevera’nın el yazısıyla yazdığı bir mektup vardı. Maskenin ilhamını, ormanda yolculuk ederken yaşadığı ve karşılaştığı hayvanların kendisiyle konuştuğu bir peyote rüyasından aldığını anlatıyordu."] = "BU MASKENİN YANINDA, YAPIMCISI EDUARDO MAQUEVERA’NIN EL YAZISIYLA YAZDIĞI BİR MEKTUP VARDI. MASKENİN İLHAMINI, ORMANDA YOLCULUK EDERKEN YAŞADIĞI VE KARŞILAŞTIĞI HAYVANLARIN KENDİSİYLE KONUŞTUĞU BİR PEYOTE RÜYASINDAN ALDIĞINI ANLATIYORDU.",
["Bu maskeyi tak, banka kasalarını üfleyerek yık ve bütün küçük domuzların ödünü kopar."] = "BU MASKEYİ TAK, BANKA KASALARINI ÜFLEYEREK YIK VE BÜTÜN KÜÇÜK DOMUZLARIN ÖDÜNÜ KOPAR.",
["Bu maskeyi takarken polislere attığın el bombalarını fıçı sayabilirsin. Onlar hoşlanmaz ama bir şeyleri patlatmanın tekdüzeliğini belki bozar!"] = "BU MASKEYİ TAKARKEN POLİSLERE ATTIĞIN EL BOMBALARINI FIÇI SAYABİLİRSİN. ONLAR HOŞLANMAZ AMA BİR ŞEYLERİ PATLATMANIN TEKDÜZELİĞİNİ BELKİ BOZAR!",
["Bu maskeyi usta maske yapımcısı Eduardo Maquevera, San Diego’daki atölyesinde yaptı. Gerçekten ünlü bir zanaatkâr olarak film sektörünün büyük bölümüne maske ve aksesuar sağlıyor."] = "BU MASKEYİ USTA MASKE YAPIMCISI EDUARDO MAQUEVERA, SAN DİEGO’DAKİ ATÖLYESİNDE YAPTI. GERÇEKTEN ÜNLÜ BİR ZANAATKÂR OLARAK FİLM SEKTÖRÜNÜN BÜYÜK BÖLÜMÜNE MASKE VE AKSESUAR SAĞLIYOR.",
