["Bu oyun artık mevcut değil. Başka bir oyun dene."] = "BU OYUN ARTIK MEVCUT DEĞİL. BAŞKA BİR OYUN DENE.",
["Bu oyun doldu. Lütfen başka birini dene."] = "BU OYUN DOLDU. LÜTFEN BAŞKA BİRİNİ DENE.",
["Bu oyun gerçekten öldüyse bu yazıyı kimse okumayacak. O zaman hemen her istediğimi söyleyebilirim. Hmm... En iyi patates kızartması incecik olandır. Kusura bakmayın ama elma dilim ve kalın kesim patatesler fazla yoğun. Bildiğin patates isteseydim patates söylerdim. Ben kızartma istiyorum. İnce olsun istiyorum. Çıtır olsun istiyorum. Düşünmek bile acıktırıyor. Tamam. Bunu nasıl bitireceğimden emin değilim. Son?"] = "BU OYUN GERÇEKTEN ÖLDÜYSE BU YAZIYI KİMSE OKUMAYACAK. O ZAMAN HEMEN HER İSTEDİĞİMİ SÖYLEYEBİLİRİM. HMM... EN İYİ PATATES KIZARTMASI İNCECİK OLANDIR. KUSURA BAKMAYIN AMA ELMA DİLİM VE KALIN KESİM PATATESLER FAZLA YOĞUN. BİLDİĞİN PATATES İSTESEYDİM PATATES SÖYLERDİM. BEN KIZARTMA İSTİYORUM. İNCE OLSUN İSTİYORUM. ÇITIR OLSUN İSTİYORUM. DÜŞÜNMEK BİLE ACIKTIRIYOR. TAMAM. BUNU NASIL BİTİRECEĞİMDEN EMİN DEĞİLİM. SON?",
["Bu oyun salonu The Golden Grin'in kalbi."] = "BU OYUN SALONU THE GOLDEN GRİN'İN KALBİ.",
["Bu oyuna kimlerin katılabileceğini belirle. Herkese açık oyuna herkes katılabilir; yalnızca arkadaşlara açık oyuna ise sadece arkadaşların katılabilir. Özel oyunlara yalnızca davetle girilir."] = "BU OYUNA KİMLERİN KATILABİLECEĞİNİ BELİRLE. HERKESE AÇIK OYUNA HERKES KATILABİLİR; YALNIZCA ARKADAŞLARA AÇIK OYUNA İSE SADECE ARKADAŞLARIN KATILABİLİR. ÖZEL OYUNLARA YALNIZCA DAVETLE GİRİLİR.",
["Bu oyuna kimlerin katılabileceğini belirle. Herkese açık oyunlara herkes katılabilir. Arkadaşlar ve Favoriler seçeneğinde yalnızca arkadaşların veya favorilerin katılabilir. Özel oyunlara ise yalnızca davetle katılınabilir."] = "BU OYUNA KİMLERİN KATILABİLECEĞİNİ BELİRLE. HERKESE AÇIK OYUNLARA HERKES KATILABİLİR. ARKADAŞLAR VE FAVORİLER SEÇENEĞİNDE YALNIZCA ARKADAŞLARIN VEYA FAVORİLERİN KATILABİLİR. ÖZEL OYUNLARA İSE YALNIZCA DAVETLE KATILINABİLİR.",
["Bu oyuncunun sosyal merkez üzerinden bağlanmasını engelle."] = "BU OYUNCUNUN SOSYAL MERKEZ ÜZERİNDEN BAĞLANMASINI ENGELLE.",
["Bu oyuncuyu sosyal merkezdeki Favori Soyguncularından çıkar."] = "BU OYUNCUYU SOSYAL MERKEZDEKİ FAVORİ SOYGUNCULARINDAN ÇIKAR.",
["Bu oyuncuyu sosyal merkezdeki Favoriler listene ekle."] = "BU OYUNCUYU SOSYAL MERKEZDEKİ FAVORİLER LİSTENE EKLE.",
["Bu oyunun çevrim içi bölümlerine erişmek için ağ bağlantısı gerekiyor."] = "BU OYUNUN ÇEVRİM İÇİ BÖLÜMLERİNE ERİŞMEK İÇİN AĞ BAĞLANTISI GEREKİYOR.",
["Bu paha biçilemez!"] = "BU PAHA BİÇİLEMEZ!",
["Bu paralı askerlerin buralarda kullanabileceğimiz C4 falan olmalı."] = "BU PARALI ASKERLERİN BURALARDA KULLANABİLECEĞİMİZ C4 FALAN OLMALI.",
["Bu paramparça olmuş, duman çıkarıyor. Laboratuvardan yenisini getirin."] = "BU PARAMPARÇA OLMUŞ, DUMAN ÇIKARIYOR. LABORATUVARDAN YENİSİNİ GETİRİN.",
["Bu parti hazır. Bir parti daha pişirmek istiyorsan biraz daha efedrin hapı ekle. Yoksa battaniyeyle örtülü varilin üstünde yakılmaya hazır bir işaret fişeği var. Kaçış aracı gelip seni almak için sinyali bekliyor."] = "BU PARTİ HAZIR. BİR PARTİ DAHA PİŞİRMEK İSTİYORSAN BİRAZ DAHA EFEDRİN HAPI EKLE. YOKSA BATTANİYEYLE ÖRTÜLÜ VARİLİN ÜSTÜNDE YAKILMAYA HAZIR BİR İŞARET FİŞEĞİ VAR. KAÇIŞ ARACI GELİP SENİ ALMAK İÇİN SİNYALİ BEKLİYOR.",
["Bu parti pek doğru olmamış gibi. Başka bir numuneyi test edin."] = "BU PARTİ PEK DOĞRU OLMAMIŞ GİBİ. BAŞKA BİR NUMUNEYİ TEST EDİN.",
["Bu partiyi başlatma vakti geldi, ha?"] = "BU PARTİYİ BAŞLATMA VAKTİ GELDİ, HA?",
