["Bu parça dengeyi artırır."] = "BU PARÇA DENGEYİ ARTIRIR.",
["Bu parça gizlenebilirliği biraz azaltır."] = "BU PARÇA GİZLENEBİLİRLİĞİ BİRAZ AZALTIR.",
["Bu parça isabeti ve gizliliği artırır."] = "BU PARÇA İSABETİ VE GİZLİLİĞİ ARTIRIR.",
["Bu patlamadan sonra haftalarca kristal yağacak. "] = "BU PATLAMADAN SONRA HAFTALARCA KRİSTAL YAĞACAK. ",
["Bu pek doğru gelmedi. Kontrol etmesi için bir memur göndersem iyi olur."] = "BU PEK DOĞRU GELMEDİ. KONTROL ETMESİ İÇİN BİR MEMUR GÖNDERSEM İYİ OLUR.",
["Bu petrol gayet işe yarar!"] = "BU PETROL GAYET İŞE YARAR!",
["Bu petrol platformunu patlatmak istiyorsak Sondaj Kulesine gitmemiz gerekiyor."] = "BU PETROL PLATFORMUNU PATLATMAK İSTİYORSAK SONDAJ KULESİNE GİTMEMİZ GEREKİYOR.",
["Bu petrol platformunu son damlasına kadar boşaltalım! Nakil hortumunu kurun."] = "BU PETROL PLATFORMUNU SON DAMLASINA KADAR BOŞALTALIM! NAKİL HORTUMUNU KURUN.",
["Bu pilotka, Almanya’daki Müritz Gölü yakınında bir cesedin üzerinde bulundu. Zavallı ölü askerin başına iple bağlanmıştı. Adsız adamın yanında başka ceset yoktu. Pilotka Rus yapımı olduğundan onun da aynı ülkeden geldiği varsayılabilir. Pek çok tahmin vardı, hiçbiri doğru değildi. Ama en ilham verici hikâye, vatanıyla öylesine gurur duyan bir askerin ölmeden önce pilotkasını başına bağlamasıydı."] = "BU PİLOTKA, ALMANYA’DAKİ MÜRİTZ GÖLÜ YAKININDA BİR CESEDİN ÜZERİNDE BULUNDU. ZAVALLI ÖLÜ ASKERİN BAŞINA İPLE BAĞLANMIŞTI. ADSIZ ADAMIN YANINDA BAŞKA CESET YOKTU. PİLOTKA RUS YAPIMI OLDUĞUNDAN ONUN DA AYNI ÜLKEDEN GELDİĞİ VARSAYILABİLİR. PEK ÇOK TAHMİN VARDI, HİÇBİRİ DOĞRU DEĞİLDİ. AMA EN İLHAM VERİCİ HİKÂYE, VATANIYLA ÖYLESİNE GURUR DUYAN BİR ASKERİN ÖLMEDEN ÖNCE PİLOTKASINI BAŞINA BAĞLAMASIYDI.",
["Bu pislikler ölmeli!"] = "BU PİSLİKLER ÖLMELİ!",
["Bu pislikleri indirme vakti."] = "BU PİSLİKLERİ İNDİRME VAKTİ.",
["Bu piçler beni zincirledi! Çıkarın şu boku üstümden!"] = "BU PİÇLER BENİ ZİNCİRLEDİ! ÇIKARIN ŞU BOKU ÜSTÜMDEN!",
