["Bu piçler kene gibi yapıştı bize!"] = "BU PİÇLER KENE GİBİ YAPIŞTI BİZE!",
["Bu piçler kim!?"] = "BU PİÇLER KİM!?",
["Bu piçler kim?"] = "BU PİÇLER KİM?",
