["Bu piçlerin sürücü kursuna gittiği belli. Orası kesin!"] = "BU PİÇLERİN SÜRÜCÜ KURSUNA GİTTİĞİ BELLİ. ORASI KESİN!",
["Bu platformdaki her şeyi bir güvenlik ağı yönetiyor ve sıkı sıkıya kilitli. Beni sunucu odasına bağlarsanız hallederim."] = "BU PLATFORMDAKİ HER ŞEYİ BİR GÜVENLİK AĞI YÖNETİYOR VE SIKI SIKIYA KİLİTLİ. BENİ SUNUCU ODASINA BAĞLARSANIZ HALLEDERİM.",
["Bu polisler yak osuruğu bile etmez."] = "BU POLİSLER YAK OSURUĞU BİLE ETMEZ.",
["Bu polisleri atlatamıyoruz... Zor yoldan yapmalıyız!"] = "BU POLİSLERİ ATLATAMIYORUZ... ZOR YOLDAN YAPMALIYIZ!",
["Bu radarları yok etmek en iyisi olur. Değil mi?"] = "BU RADARLARI YOK ETMEK EN İYİSİ OLUR. DEĞİL Mİ?",
["Bu rafların arkasında bir şey olmalı."] = "BU RAFLARIN ARKASINDA BİR ŞEY OLMALI.",
["Bu ray canavarı makul bir denge artışı sağlar ve gizlenebilirliği azaltır."] = "BU RAY CANAVARI MAKUL BİR DENGE ARTIŞI SAĞLAR VE GİZLENEBİLİRLİĞİ AZALTIR.",
["Bu saat diliminde nakil planlanmamış. Ne oluyor lan?"] = "BU SAAT DİLİMİNDE NAKİL PLANLANMAMIŞ. NE OLUYOR LAN?",
