["Bu savaş, savaşta da biz kazanırız!"] = "BU SAVAŞ, SAVAŞTA DA BİZ KAZANIRIZ!",
["Bu savaşın sürmesi için silah lazım. Şimdi benim olan FBI'da. Para gitti ama teçhizat hâlâ havaalanında. Gidip şu lanet silah sandıklarını geri alın."] = "BU SAVAŞIN SÜRMESİ İÇİN SİLAH LAZIM. ŞİMDİ BENİM OLAN FBI'DA. PARA GİTTİ AMA TEÇHİZAT HÂLÂ HAVAALANINDA. GİDİP ŞU LANET SİLAH SANDIKLARINI GERİ ALIN.",
["Bu sağlam deri eldivenlerin dikişleri saf altından. Dünyanın en iyi dokumacıları sekiz ayrı ipliği örerek yaptı. Bir soyguncunun elleri daha azını hak etmez; hele işte geçen sekiz şanlı yıl kutlanıyorsa."] = "BU SAĞLAM DERİ ELDİVENLERİN DİKİŞLERİ SAF ALTINDAN. DÜNYANIN EN İYİ DOKUMACILARI SEKİZ AYRI İPLİĞİ ÖREREK YAPTI. BİR SOYGUNCUNUN ELLERİ DAHA AZINI HAK ETMEZ; HELE İŞTE GEÇEN SEKİZ ŞANLI YIL KUTLANIYORSA.",
["Bu sefer arkanızı kolladım ama bundan sonra böyle ‘özel’ iyilikler için para ödemeniz gerekecek. Bağlantılarım iyi insanlardır ve karşılığında iyi para beklerler."] = "BU SEFER ARKANIZI KOLLADIM AMA BUNDAN SONRA BÖYLE ‘ÖZEL’ İYİLİKLER İÇİN PARA ÖDEMENİZ GEREKECEK. BAĞLANTILARIM İYİ İNSANLARDIR VE KARŞILIĞINDA İYİ PARA BEKLERLER.",
["Bu sefer başardık sanmıştım. Lanet olsun, saymayı unuttum. Gidip bir tane daha alın."] = "BU SEFER BAŞARDIK SANMIŞTIM. LANET OLSUN, SAYMAYI UNUTTUM. GİDİP BİR TANE DAHA ALIN.",
["Bu sefer bizi alt etmiş olabilirsiniz pislikler ama sonunda sizi yakalayacağız!"] = "BU SEFER BİZİ ALT ETMİŞ OLABİLİRSİNİZ PİSLİKLER AMA SONUNDA SİZİ YAKALAYACAĞIZ!",
["Bu sefer doğru anahtarı alın!"] = "BU SEFER DOĞRU ANAHTARI ALIN!",
["Bu sefer istediğiniz her şeyi almış olabilirsiniz palyaçolar. Ama sizin de gününüz gelecek."] = "BU SEFER İSTEDİĞİNİZ HER ŞEYİ ALMIŞ OLABİLİRSİNİZ PALYAÇOLAR. AMA SİZİN DE GÜNÜNÜZ GELECEK.",
["Bu sefer işe yaramasını gerçekten umuyorum."] = "BU SEFER İŞE YARAMASINI GERÇEKTEN UMUYORUM.",
["Bu sefer ne yaptığınızı bilmek bile istemiyorum. Koordinatları verin yeter."] = "BU SEFER NE YAPTIĞINIZI BİLMEK BİLE İSTEMİYORUM. KOORDİNATLARI VERİN YETER.",
["Bu sefer sıçmak yok. Bırak!"] = "BU SEFER SIÇMAK YOK. BIRAK!",
["Bu senaryoda iyi adamların biz olduğunu savunabiliriz, değil mi? "] = "BU SENARYODA İYİ ADAMLARIN BİZ OLDUĞUNU SAVUNABİLİRİZ, DEĞİL Mİ? ",
["Bu senaryonun tamamı fazla tanıdık."] = "BU SENARYONUN TAMAMI FAZLA TANIDIK.",
["Bu sersemleten küçük güzellik herkesin nefesini kesecek, onları öldürmek için gereken fazladan birkaç saniyeyi sana verecek."] = "BU SERSEMLETEN KÜÇÜK GÜZELLİK HERKESİN NEFESİNİ KESECEK, ONLARI ÖLDÜRMEK İÇİN GEREKEN FAZLADAN BİRKAÇ SANİYEYİ SANA VERECEK.",
["Bu sikik işi kim aldı?"] = "BU SİKİK İŞİ KİM ALDI?",
