["Bu silah için yerden mühimmat toplanamaz."] = "BU SİLAH İÇİN YERDEN MÜHİMMAT TOPLANAMAZ.",
["Bu silah kaplaması bir Başarım Ödülüdür; takas edilemez veya satılamaz."] = "BU SİLAH KAPLAMASI BİR BAŞARIM ÖDÜLÜDÜR; TAKAS EDİLEMEZ VEYA SATILAMAZ.",
["Bu silah kaplaması kendi silah modifikasyonu setini içerir ve mevcut yapılandırmanın yerini alır."] = "BU SİLAH KAPLAMASI KENDİ SİLAH MODİFİKASYONU SETİNİ İÇERİR VE MEVCUT YAPILANDIRMANIN YERİNİ ALIR.",
["Bu silah kaplamasını kullanmak için önce 1000 Başarım Dönüm Noktasını açmalısın."] = "BU SİLAH KAPLAMASINI KULLANMAK İÇİN ÖNCE 1000 BAŞARIM DÖNÜM NOKTASINI AÇMALISIN.",
["Bu silah susturuculudur ve pompalı tüfeklerin itme özelliğine sahiptir."] = "BU SİLAH SUSTURUCULUDUR VE POMPALI TÜFEKLERİN İTME ÖZELLİĞİNE SAHİPTİR.",
["Bu silah susturuculudur."] = "BU SİLAH SUSTURUCULUDUR.",
["Bu silah tüm PAYDAY 2 oyuncuları için ücretsizdir."] = "BU SİLAH TÜM PAYDAY 2 OYUNCULARI İÇİN ÜCRETSİZDİR.",
["Bu silahlardan güzel para kazanacağız. Alın da gidelim."] = "BU SİLAHLARDAN GÜZEL PARA KAZANACAĞIZ. ALIN DA GİDELİM.",
["Bu silahı Duke olarak bilinen soyguncu taşıyordu. Altın görünümüyle dikkat çekiyordu; sürgüsünde \"The Duke önünde diz çök\" yazısı kazılı."] = "BU SİLAHI DUKE OLARAK BİLİNEN SOYGUNCU TAŞIYORDU. ALTIN GÖRÜNÜMÜYLE DİKKAT ÇEKİYORDU; SÜRGÜSÜNDE \"THE DUKE ÖNÜNDE DİZ ÇÖK\" YAZISI KAZILI.",
["Bu silahın kilidini açmak için Aldstone’s Heritage işlerinden \"Knife Legislation\" görevini tamamla."] = "BU SİLAHIN KİLİDİNİ AÇMAK İÇİN ALDSTONE’S HERİTAGE İŞLERİNDEN \"KNİFE LEGİSLATİON\" GÖREVİNİ TAMAMLA.",
["Bu silahın kilidini açmak için Aldstone’s Heritage işlerinden \"Prepare for War\" görevini tamamla."] = "BU SİLAHIN KİLİDİNİ AÇMAK İÇİN ALDSTONE’S HERİTAGE İŞLERİNDEN \"PREPARE FOR WAR\" GÖREVİNİ TAMAMLA.",
["Bu silahın kilidini açmak için Aldstone’s Heritage işlerinden \"Rapid Retribution\" görevini tamamla."] = "BU SİLAHIN KİLİDİNİ AÇMAK İÇİN ALDSTONE’S HERİTAGE İŞLERİNDEN \"RAPİD RETRİBUTİON\" GÖREVİNİ TAMAMLA.",
["Bu silahın kilidini açmak için RAID: World War II topluluk grubuna katıl."] = "BU SİLAHIN KİLİDİNİ AÇMAK İÇİN RAID: WORLD WAR II TOPLULUK GRUBUNA KATIL.",
["Bu sistem basit olacak şekilde yapılmış. Tek yapmanız gereken bir kasa dairesi seçip düğmeye basmak. Kolay, değil mi? Kesinlikle."] = "BU SİSTEM BASİT OLACAK ŞEKİLDE YAPILMIŞ. TEK YAPMANIZ GEREKEN BİR KASA DAİRESİ SEÇİP DÜĞMEYE BASMAK. KOLAY, DEĞİL Mİ? KESİNLİKLE.",
["Bu sistemlerin büyük bir zayıflığı var: Zararlı yazılımlara kolay yeniliyorlar. Ben de biraz vereceğim."] = "BU SİSTEMLERİN BÜYÜK BİR ZAYIFLIĞI VAR: ZARARLI YAZILIMLARA KOLAY YENİLİYORLAR. BEN DE BİRAZ VERECEĞİM.",
["Bu site başka bir şey söylüyor... Klorür, soda, hidrojen karışımı. Bilmiyorum, bir şey deneyin."] = "BU SİTE BAŞKA BİR ŞEY SÖYLÜYOR... KLORÜR, SODA, HİDROJEN KARIŞIMI. BİLMİYORUM, BİR ŞEY DENEYİN.",
["Bu siteye bakıyorum... Bu adımda asit kullanılır diyor... Tuz ruhumuz var, değil mi?"] = "BU SİTEYE BAKIYORUM... BU ADIMDA ASİT KULLANILIR DİYOR... TUZ RUHUMUZ VAR, DEĞİL Mİ?",
["Bu siviller işinizi umursayacak kadar para almıyor. Onları korkutmayın."] = "BU SİVİLLER İŞİNİZİ UMURSAYACAK KADAR PARA ALMIYOR. ONLARI KORKUTMAYIN.",
["Bu siyah beyaz birleşimi muhtemelen çamurda yuvarlanmayı sevmeyen soygunculara daha uygun."] = "BU SİYAH BEYAZ BİRLEŞİMİ MUHTEMELEN ÇAMURDA YUVARLANMAYI SEVMEYEN SOYGUNCULARA DAHA UYGUN.",
["Bu size biraz zaman kazandırdı."] = "BU SİZE BİRAZ ZAMAN KAZANDIRDI.",
["Bu slot makineleri ağa bağlı. Sistemlerini kırmak işe yarar. Kontrol odasını bulun."] = "BU SLOT MAKİNELERİ AĞA BAĞLI. SİSTEMLERİNİ KIRMAK İŞE YARAR. KONTROL ODASINI BULUN.",
["Bu son gösterimiz, duydunuz mu? Gümbür gümbür bitsin."] = "BU SON GÖSTERİMİZ, DUYDUNUZ MU? GÜMBÜR GÜMBÜR BİTSİN.",
["Bu soygun efsaneye dönüşecek. Viki maddesini yazıyorum bile. 'Hassiktir!' diye başlıyor."] = "BU SOYGUN EFSANEYE DÖNÜŞECEK. VİKİ MADDESİNİ YAZIYORUM BİLE. 'HASSİKTİR!' DİYE BAŞLIYOR.",
["Bu soygun titiz planlama gerektirecek."] = "BU SOYGUN TİTİZ PLANLAMA GEREKTİRECEK.",
["Bu soygun şiddete dönüşebilir. Öyle olursa ek mühimmat, o şiddeti etkili bir şekilde uygulamanızı sağlar."] = "BU SOYGUN ŞİDDETE DÖNÜŞEBİLİR. ÖYLE OLURSA EK MÜHİMMAT, O ŞİDDETİ ETKİLİ BİR ŞEKİLDE UYGULAMANIZI SAĞLAR.",
["Bu soygun şu anda VR'da oynanamıyor."] = "BU SOYGUN ŞU ANDA VR'DA OYNANAMIYOR.",
["Bu soyguna sahip değilsin ve bu sunucuya katılamazsın."] = "BU SOYGUNA SAHİP DEĞİLSİN VE BU SUNUCUYA KATILAMAZSIN.",
["Bu soygunu atlarsan kariyer modunda geri dönüp oynayamazsın. Ayrıca ödüllerin yalnızca yarısını alırsın."] = "BU SOYGUNU ATLARSAN KARİYER MODUNDA GERİ DÖNÜP OYNAYAMAZSIN. AYRICA ÖDÜLLERİN YALNIZCA YARISINI ALIRSIN.",
["Bu sunucuda sırlar, kayıtlar, dünyayı değiştirecek veriler var. Bir de bütün oyun kayıtlarım. Evet, kesinlikle."] = "BU SUNUCUDA SIRLAR, KAYITLAR, DÜNYAYI DEĞİŞTİRECEK VERİLER VAR. BİR DE BÜTÜN OYUN KAYITLARIM. EVET, KESİNLİKLE.",
["Bu sürücü, soygundan başarıyla kaçmanı sağlayacak"] = "BU SÜRÜCÜ, SOYGUNDAN BAŞARIYLA KAÇMANI SAĞLAYACAK",
["Bu sürüm daha sade; kalabalığa karışmak istediğin zamanlar için ideal."] = "BU SÜRÜM DAHA SADE; KALABALIĞA KARIŞMAK İSTEDİĞİN ZAMANLAR İÇİN İDEAL.",
["Bu takipçiyi bir türlü atlatamıyorum!"] = "BU TAKİPÇİYİ BİR TÜRLÜ ATLATAMIYORUM!",
["Bu taktik kıyafetin neredeyse tamamen siyah çeşidi."] = "BU TAKTİK KIYAFETİN NEREDEYSE TAMAMEN SİYAH ÇEŞİDİ.",
["Bu taktik takımın beyaz çeşidi."] = "BU TAKTİK TAKIMIN BEYAZ ÇEŞİDİ.",
["Bu taktik takımın canlı kızıl çeşidi."] = "BU TAKTİK TAKIMIN CANLI KIZIL ÇEŞİDİ.",
["Bu taktik takımın gök mavisi çeşidi."] = "BU TAKTİK TAKIMIN GÖK MAVİSİ ÇEŞİDİ.",
["Bu takımın gösterişsiz tonlarını beğenmek için dindar, hatta maneviyata önem veren biri olmana gerek yok."] = "BU TAKIMIN GÖSTERİŞSİZ TONLARINI BEĞENMEK İÇİN DİNDAR, HATTA MANEVİYATA ÖNEM VEREN BİRİ OLMANA GEREK YOK.",
["Bu takımın yumuşak pamuklu kumaşının bir hikâyesi var. Dokuyan adam, ölmüş kızının anısına Ölüler Günü’nden önce bitirebilmesi için bekleyen terziye zamanında ulaşmak üzere katır sırtında beş gün yol gitti. Azıcık yiyeceğini ve suyunu yük hayvanıyla paylaşıp zorlu yollarla, fırtınalarla, haydutlarla savaştı; sonunda varacağı yere ulaştı. Ardından gelen kutlamalarda dokumacı, havada kızının kahkahasını duyduğuna yemin etti."] = "BU TAKIMIN YUMUŞAK PAMUKLU KUMAŞININ BİR HİKÂYESİ VAR. DOKUYAN ADAM, ÖLMÜŞ KIZININ ANISINA ÖLÜLER GÜNÜ’NDEN ÖNCE BİTİREBİLMESİ İÇİN BEKLEYEN TERZİYE ZAMANINDA ULAŞMAK ÜZERE KATIR SIRTINDA BEŞ GÜN YOL GİTTİ. AZICIK YİYECEĞİNİ VE SUYUNU YÜK HAYVANIYLA PAYLAŞIP ZORLU YOLLARLA, FIRTINALARLA, HAYDUTLARLA SAVAŞTI; SONUNDA VARACAĞI YERE ULAŞTI. ARDINDAN GELEN KUTLAMALARDA DOKUMACI, HAVADA KIZININ KAHKAHASINI DUYDUĞUNA YEMİN ETTİ.",
["Bu tanklardan biri petrol numunemizle eşleşmeli. Borulara bağlayın, sonra kolu çekin."] = "BU TANKLARDAN BİRİ PETROL NUMUNEMİZLE EŞLEŞMELİ. BORULARA BAĞLAYIN, SONRA KOLU ÇEKİN.",
["Bu taraftan dostlarım, bütün hızınızla."] = "BU TARAFTAN DOSTLARIM, BÜTÜN HIZINIZLA.",
["Bu taraftan geçemeyecekler!"] = "BU TARAFTAN GEÇEMEYECEKLER!",
["Bu tasarım zihnini boşaltıp odaklanarak işi bitirmen gereken anlar için."] = "BU TASARIM ZİHNİNİ BOŞALTIP ODAKLANARAK İŞİ BİTİRMEN GEREKEN ANLAR İÇİN.",
["Bu tasarım, bir doz fazla zekâ ilacı almış, kafası bozuk bir Silikon Vadisi dâhisinin eseri. Onun yanmış beyninden kazançlı çıkan sensin."] = "BU TASARIM, BİR DOZ FAZLA ZEKÂ İLACI ALMIŞ, KAFASI BOZUK BİR SİLİKON VADİSİ DÂHİSİNİN ESERİ. ONUN YANMIŞ BEYNİNDEN KAZANÇLI ÇIKAN SENSİN.",
["Bu teknolojiyi daha önce gördüm. Şu ordu sersemleri konsollarını bir anahtar üreteci paneline bağlamış. Bulabilirseniz bize erişim kodunu verir."] = "BU TEKNOLOJİYİ DAHA ÖNCE GÖRDÜM. ŞU ORDU SERSEMLERİ KONSOLLARINI BİR ANAHTAR ÜRETECİ PANELİNE BAĞLAMIŞ. BULABİLİRSENİZ BİZE ERİŞİM KODUNU VERİR.",
["Bu terminallerde Moretta'nın iletişim frekansı olduğunu tahmin ediyorum. Bakmaya değer."] = "BU TERMİNALLERDE MORETTA'NIN İLETİŞİM FREKANSI OLDUĞUNU TAHMİN EDİYORUM. BAKMAYA DEĞER.",
["Bu terminallerde muhtemelen Moretta hakkında bilgi vardır. İsterseniz araştırabilirsiniz. İstihbarat her zaman işe yarar."] = "BU TERMİNALLERDE MUHTEMELEN MORETTA HAKKINDA BİLGİ VARDIR. İSTERSENİZ ARAŞTIRABİLİRSİNİZ. İSTİHBARAT HER ZAMAN İŞE YARAR.",
["Bu transferde fazladan sıfır var! Ama şifre yok. Başkasını deneyin."] = "BU TRANSFERDE FAZLADAN SIFIR VAR! AMA ŞİFRE YOK. BAŞKASINI DENEYİN.",
["Bu trenin zırhı sağlam görünüyor ama biraz aşırı ısıyla aşabiliriz bence. Gemma, depoda pürmüz tuttuklarını söylüyor. Tam ihtiyacımız olan şey."] = "BU TRENİN ZIRHI SAĞLAM GÖRÜNÜYOR AMA BİRAZ AŞIRI ISIYLA AŞABİLİRİZ BENCE. GEMMA, DEPODA PÜRMÜZ TUTTUKLARINI SÖYLÜYOR. TAM İHTİYACIMIZ OLAN ŞEY.",
["Bu tuhaf boktan bir daha olursa alarmı çalarım."] = "BU TUHAF BOKTAN BİR DAHA OLURSA ALARMI ÇALARIM.",
["Bu tuhaf, millet. Panolar deli gibi yanıp sönüyor. Bir terslik var... Sanırım büyük bela geliyor. Lanet olsun, bu işin karanlık olduğunu biliyordum."] = "BU TUHAF, MİLLET. PANOLAR DELİ GİBİ YANIP SÖNÜYOR. BİR TERSLİK VAR... SANIRIM BÜYÜK BELA GELİYOR. LANET OLSUN, BU İŞİN KARANLIK OLDUĞUNU BİLİYORDUM.",
["Bu tür durumlar genellikle değişkendir. İyi tepki verdiniz. Kararlı davrandınız. Bu kazancın tadını çıkarın. Vakti gelince benden haber alacaksınız."] = "BU TÜR DURUMLAR GENELLİKLE DEĞİŞKENDİR. İYİ TEPKİ VERDİNİZ. KARARLI DAVRANDINIZ. BU KAZANCIN TADINI ÇIKARIN. VAKTİ GELİNCE BENDEN HABER ALACAKSINIZ.",
["Bu ufak siyaset mühendisliğini yıllarca okutmalılar. Muhteşem, ekip. Muhteşem!"] = "BU UFAK SİYASET MÜHENDİSLİĞİNİ YILLARCA OKUTMALILAR. MUHTEŞEM, EKİP. MUHTEŞEM!",
["Bu vagonlar sağlam ama termit kolayca eritir."] = "BU VAGONLAR SAĞLAM AMA TERMİT KOLAYCA ERİTİR.",
["Bu vagonlarda değerli bir şey olabilir. Bir baksanız mı?"] = "BU VAGONLARDA DEĞERLİ BİR ŞEY OLABİLİR. BİR BAKSANIZ MI?",
["Bu vitrinlerde güzel ganimet var. Ama ucuz, sahte ıvır zıvır da var. Alarmları arayın. İyi parçaları öyle bulursunuz."] = "BU VİTRİNLERDE GÜZEL GANİMET VAR. AMA UCUZ, SAHTE IVIR ZIVIR DA VAR. ALARMLARI ARAYIN. İYİ PARÇALARI ÖYLE BULURSUNUZ.",
["Bu vurgun silahlı çatışmaya *dönerse* şuradaki fotokopi makinesinde ekipman saklı. "] = "BU VURGUN SİLAHLI ÇATIŞMAYA *DÖNERSE* ŞURADAKİ FOTOKOPİ MAKİNESİNDE EKİPMAN SAKLI. ",
["Bu vurguna buradan başlayacaksınız."] = "BU VURGUNA BURADAN BAŞLAYACAKSINIZ.",
["Bu vurgunu bitirme vakti! Kaçış noktasına gidin. Mavi konteynerleri takip edin!"] = "BU VURGUNU BİTİRME VAKTİ! KAÇIŞ NOKTASINA GİDİN. MAVİ KONTEYNERLERİ TAKİP EDİN!",
["Bu yanlış anahtar amına koyayım!"] = "BU YANLIŞ ANAHTAR AMINA KOYAYIM!",
["Bu yaptığın yanına kalmayacak orospu çocuğu!"] = "BU YAPTIĞIN YANINA KALMAYACAK OROSPU ÇOCUĞU!",
["Bu yaptığınız yanınıza kalmayacak!"] = "BU YAPTIĞINIZ YANINIZA KALMAYACAK!",
["Bu yerde ne tür boklar bulacağız acaba?"] = "BU YERDE NE TÜR BOKLAR BULACAĞIZ ACABA?",
["Bu yere düşmelerin bazılarına göz yumabiliriz."] = "BU YERE DÜŞMELERİN BAZILARINA GÖZ YUMABİLİRİZ.",
["Bu yeter! Çıkarmaya başlayıp kamyona yükleyin!"] = "BU YETER! ÇIKARMAYA BAŞLAYIP KAMYONA YÜKLEYİN!",
["Bu yeter. Kaydı alıp çıkın."] = "BU YETER. KAYDI ALIP ÇIKIN.",
["Bu yeter. Şimdi sunucu odasını bulalım."] = "BU YETER. ŞİMDİ SUNUCU ODASINI BULALIM.",
["Bu yeterince iyi. Yaklaşıyorum."] = "BU YETERİNCE İYİ. YAKLAŞIYORUM.",
["Bu yeterli olmalı! Harika! Hadi Commissar... Ara..."] = "BU YETERLİ OLMALI! HARİKA! HADİ COMMİSSAR... ARA...",
["Bu yeterli olmalı. Şimdi aşırı ısınıp yeniden başlatmayı tetikleyecekler."] = "BU YETERLİ OLMALI. ŞİMDİ AŞIRI ISINIP YENİDEN BAŞLATMAYI TETİKLEYECEKLER.",
["Bu yeterli olmalı. Şimdi zaman kilidini yeniden başlatın. Umarım işe yaramıştır."] = "BU YETERLİ OLMALI. ŞİMDİ ZAMAN KİLİDİNİ YENİDEN BAŞLATIN. UMARIM İŞE YARAMIŞTIR.",
["Bu yetmez, her şey şifreli. Daha fazla şifre lazım!"] = "BU YETMEZ, HER ŞEY ŞİFRELİ. DAHA FAZLA ŞİFRE LAZIM!",
["Bu yolculukta iyi mal toplayacağız."] = "BU YOLCULUKTA İYİ MAL TOPLAYACAĞIZ.",
["Bu yoldan yukarı çıkılmıyor. Etrafa bakın. Başka yol olmalı."] = "BU YOLDAN YUKARI ÇIKILMIYOR. ETRAFA BAKIN. BAŞKA YOL OLMALI.",
["Bu yükleme yeterince hızlı gitmiyor, lanet olsun!"] = "BU YÜKLEME YETERİNCE HIZLI GİTMİYOR, LANET OLSUN!",
["Bu yükseltme, Tuzak Mayınlarının patlama gücünü ve etki alanını artırır."] = "BU YÜKSELTME, TUZAK MAYINLARININ PATLAMA GÜCÜNÜ VE ETKİ ALANINI ARTIRIR.",
["Bu yüz korumasını takan soyguncudan kusursuz bir saat mekanizması gibi dijital hassasiyet akar. Karşısına dikildiğinde her düşman az da olsa ürperir."] = "BU YÜZ KORUMASINI TAKAN SOYGUNCUDAN KUSURSUZ BİR SAAT MEKANİZMASI GİBİ DİJİTAL HASSASİYET AKAR. KARŞISINA DİKİLDİĞİNDE HER DÜŞMAN AZ DA OLSA ÜRPERİR.",
["Bu yıl yaramaz mıydın? O zaman Krampus’un ziyaretini bekleyebilirsin. Ya da Bain’den telefon."] = "BU YIL YARAMAZ MIYDIN? O ZAMAN KRAMPUS’UN ZİYARETİNİ BEKLEYEBİLİRSİN. YA DA BAIN’DEN TELEFON.",
["Bu zamanı iyileşmek için kullanın. Kokaini bırakıp bir Doktor Çantası yerleştirin."] = "BU ZAMANI İYİLEŞMEK İÇİN KULLANIN. KOKAİNİ BIRAKIP BİR DOKTOR ÇANTASI YERLEŞTİRİN.",
["Bu zavallı insanlar niye bana sürekli bir şey soruyor?"] = "BU ZAVALLI İNSANLAR NİYE BANA SÜREKLİ BİR ŞEY SORUYOR?",
["Bu zehirli gazı yeni yuvasına götürelim. Tüpü Gabriel'ın havalandırma kanallarından birine bağlayın."] = "BU ZEHİRLİ GAZI YENİ YUVASINA GÖTÜRELİM. TÜPÜ GABRİEL'IN HAVALANDIRMA KANALLARINDAN BİRİNE BAĞLAYIN.",
["Bu zor bir iş olacak ama halledersiniz."] = "BU ZOR BİR İŞ OLACAK AMA HALLEDERSİNİZ.",
["Bu zırh giyildiğinde Öğütücü avantaj destesi devre dışı kalır"] = "BU ZIRH GİYİLDİĞİNDE ÖĞÜTÜCÜ AVANTAJ DESTESİ DEVRE DIŞI KALIR",
["Bu zırhı gerçekten istiyordun. Her şeyden çok."] = "BU ZIRHI GERÇEKTEN İSTİYORDUN. HER ŞEYDEN ÇOK.",
["Bu çantalar epey hırpalanmış görünüyor. Ne yaptınız bunlarla?"] = "BU ÇANTALAR EPEY HIRPALANMIŞ GÖRÜNÜYOR. NE YAPTINIZ BUNLARLA?",
["Bu çantalar epey hırpalanmış... Bunlarla ne yaptınız?"] = "BU ÇANTALAR EPEY HIRPALANMIŞ... BUNLARLA NE YAPTINIZ?",
["Bu çantalar fena dağılmış... Malımıza saygı göstermeniz lazım!"] = "BU ÇANTALAR FENA DAĞILMIŞ... MALIMIZA SAYGI GÖSTERMENİZ LAZIM!",
["Bu çantalar mahvolmuş. Mallarımıza saygılı davranmıyorsunuz, ha?"] = "BU ÇANTALAR MAHVOLMUŞ. MALLARIMIZA SAYGILI DAVRANMIYORSUNUZ, HA?",
["Bu çekici parça seni şehrin diline düşürecek. \"TASER’LARI GÖNDERİN!\", \"POLİS! ELLERİNİZ HAVADA DIŞARI ÇIKIN!\" veya \"BU ADAMLAR KİM, ESKİ ASKER Mİ?!\" gibi şeyler duyman garanti."] = "BU ÇEKİCİ PARÇA SENİ ŞEHRİN DİLİNE DÜŞÜRECEK. \"TASER’LARI GÖNDERİN!\", \"POLİS! ELLERİNİZ HAVADA DIŞARI ÇIKIN!\" VEYA \"BU ADAMLAR KİM, ESKİ ASKER Mİ?!\" GİBİ ŞEYLER DUYMAN GARANTİ.",
["Bu çerçeveler, Ay’a inişin hayal edildiği, bütün hayallerin mümkün olduğu ve herkesin biraz daha şık giyindiği zamanları hatırlatıyor."] = "BU ÇERÇEVELER, AY’A İNİŞİN HAYAL EDİLDİĞİ, BÜTÜN HAYALLERİN MÜMKÜN OLDUĞU VE HERKESİN BİRAZ DAHA ŞIK GİYİNDİĞİ ZAMANLARI HATIRLATIYOR.",
["Bu çetrefilli bir iş çocuklar. Nasıl yaklaşacağınız size kalmış."] = "BU ÇETREFİLLİ BİR İŞ ÇOCUKLAR. NASIL YAKLAŞACAĞINIZ SİZE KALMIŞ.",
["Bu çeşit gece soygunları için kusursuz."] = "BU ÇEŞİT GECE SOYGUNLARI İÇİN KUSURSUZ.",
["Bu çeşit, açık ve koyu tonları iyi harmanlıyor."] = "BU ÇEŞİT, AÇIK VE KOYU TONLARI İYİ HARMANLIYOR.",
["Bu çok zor olmamalı. Merak etme, arkanı kollayacağım ve her adımı anlatacağım. Hem bu hayata hâlâ hazır olduğundan emin olmama fırsat verir."] = "BU ÇOK ZOR OLMAMALI. MERAK ETME, ARKANI KOLLAYACAĞIM VE HER ADIMI ANLATACAĞIM. HEM BU HAYATA HÂLÂ HAZIR OLDUĞUNDAN EMİN OLMAMA FIRSAT VERİR.",
["Bu çöp kutusu Bush iktidardayken beri boşaltılmamış galiba. Baba Bush'tan beri!"] = "BU ÇÖP KUTUSU BUSH İKTİDARDAYKEN BERİ BOŞALTILMAMIŞ GALİBA. BABA BUSH'TAN BERİ!",
["Bu çöplük, Commissar gibi bir sıçanın saklanması için biçilmiş kaftan."] = "BU ÇÖPLÜK, COMMİSSAR GİBİ BİR SIÇANIN SAKLANMASI İÇİN BİÇİLMİŞ KAFTAN.",
["Bu çılgınlığı bırakın ve silahlarınızı indirin!"] = "BU ÇILGINLIĞI BIRAKIN VE SİLAHLARINIZI İNDİRİN!",
["Bu ölü oyunu hayatta tutan güzel soygunculara selam olsun!"] = "BU ÖLÜ OYUNU HAYATTA TUTAN GÜZEL SOYGUNCULARA SELAM OLSUN!",
["Bu özel bir silah kaplamasıdır. Uyguluyken silahın yapılandırmasını veya özel adını değiştiremezsin."] = "BU ÖZEL BİR SİLAH KAPLAMASIDIR. UYGULUYKEN SİLAHIN YAPILANDIRMASINI VEYA ÖZEL ADINI DEĞİŞTİREMEZSİN.",
["Bu ücretsiz güncellemede oyuna dört küçük soygun ekledik. İkisi çatışmaya, diğer ikisi gizliliğe odaklanıyor. Bu soygunları tasarlarken amacımız yeni oyunculara oyunun temel mekaniklerini öğretmek, PAYDAY 2’ye daha rahat başlamalarını sağlamak ve seviye atladıkça karşılaşacakları daha zorlu soygunlara onları hazırlamaktı."] = "BU ÜCRETSİZ GÜNCELLEMEDE OYUNA DÖRT KÜÇÜK SOYGUN EKLEDİK. İKİSİ ÇATIŞMAYA, DİĞER İKİSİ GİZLİLİĞE ODAKLANIYOR. BU SOYGUNLARI TASARLARKEN AMACIMIZ YENİ OYUNCULARA OYUNUN TEMEL MEKANİKLERİNİ ÖĞRETMEK, PAYDAY 2’YE DAHA RAHAT BAŞLAMALARINI SAĞLAMAK VE SEVİYE ATLADIKÇA KARŞILAŞACAKLARI DAHA ZORLU SOYGUNLARA ONLARI HAZIRLAMAKTI.",
["Bu ücretsiz."] = "BU ÜCRETSİZ.",
["Bu İz Bırakır!"] = "BU İZ BIRAKIR!",
["Bu İşte Rock Yıldızıyız"] = "BU İŞTE ROCK YILDIZIYIZ",
["Bu Şehri Elektronik Progresif House Müzikle Kurduk"] = "BU ŞEHRİ ELEKTRONİK PROGRESİF HOUSE MÜZİKLE KURDUK",
["Bu şaibeli pislikler o sunucuda ne saklıyormuş görmek için sabırsızlanıyorum."] = "BU ŞAİBELİ PİSLİKLER O SUNUCUDA NE SAKLIYORMUŞ GÖRMEK İÇİN SABIRSIZLANIYORUM.",
["Bu şapka normal, standart bir M43 arazi şapkası gibi görünebilir. Wolfgang kadar kendini beğenmiş bir adam için böylesine mütevazı bir başlığın tuhaf bir seçim olduğunu da düşünebilirsin. Ama bu şapkanın onun için özel bir anlamı var. Wolfgang’ın gerçekten sevebildiğine şaşırabilirsin. İçine, uğruna savaştığı sevgilisinin fotoğrafı iliştirilmiş."] = "BU ŞAPKA NORMAL, STANDART BİR M43 ARAZİ ŞAPKASI GİBİ GÖRÜNEBİLİR. WOLFGANG KADAR KENDİNİ BEĞENMİŞ BİR ADAM İÇİN BÖYLESİNE MÜTEVAZI BİR BAŞLIĞIN TUHAF BİR SEÇİM OLDUĞUNU DA DÜŞÜNEBİLİRSİN. AMA BU ŞAPKANIN ONUN İÇİN ÖZEL BİR ANLAMI VAR. WOLFGANG’IN GERÇEKTEN SEVEBİLDİĞİNE ŞAŞIRABİLİRSİN. İÇİNE, UĞRUNA SAVAŞTIĞI SEVGİLİSİNİN FOTOĞRAFI İLİŞTİRİLMİŞ.",
["Bu şapkada ilk bakışta görünenden fazlası var. Başta iddiasız görünür ama zihnin gerisinde şiddetli bir iz bırakır. Bunca kırmızı... Kanlı bir alamet. Yoluna çıkana Tanrı yardım etsin."] = "BU ŞAPKADA İLK BAKIŞTA GÖRÜNENDEN FAZLASI VAR. BAŞTA İDDİASIZ GÖRÜNÜR AMA ZİHNİN GERİSİNDE ŞİDDETLİ BİR İZ BIRAKIR. BUNCA KIRMIZI... KANLI BİR ALAMET. YOLUNA ÇIKANA TANRI YARDIM ETSİN.",
["Bu şartlarda olabileceği kadar iyi gitti. Birkaç telefon açacağım... Locke'a gerçekte ne olduğunu öğreneceğim."] = "BU ŞARTLARDA OLABİLECEĞİ KADAR İYİ GİTTİ. BİRKAÇ TELEFON AÇACAĞIM... LOCKE'A GERÇEKTE NE OLDUĞUNU ÖĞRENECEĞİM.",
["Bu şehir mücevher elden çıkarmak için harika. Satması kolay. Diplomatlar ve zengin adamların genç eşleri sorgusuz sualsiz alıyor. Çocuk oyuncağı olacak. Başlayalım."] = "BU ŞEHİR MÜCEVHER ELDEN ÇIKARMAK İÇİN HARİKA. SATMASI KOLAY. DİPLOMATLAR VE ZENGİN ADAMLARIN GENÇ EŞLERİ SORGUSUZ SUALSİZ ALIYOR. ÇOCUK OYUNCAĞI OLACAK. BAŞLAYALIM.",
["Bu şehir, mücevher elden çıkarmak için harika bir yer. Kolayca satılıyorlar. Diplomatlar ve zengin kocaların genç eşleri, hiç soru sormadan alıyor. Çocuk oyuncağı olacak. Hadi gidelim."] = "BU ŞEHİR, MÜCEVHER ELDEN ÇIKARMAK İÇİN HARİKA BİR YER. KOLAYCA SATILIYORLAR. DİPLOMATLAR VE ZENGİN KOCALARIN GENÇ EŞLERİ, HİÇ SORU SORMADAN ALIYOR. ÇOCUK OYUNCAĞI OLACAK. HADİ GİDELİM.",
["Bu şehrin Nixon'dan beri gördüğü en büyük siyasi geri dönüşe imza atma şansımız var. Girin içeri palyaçolar."] = "BU ŞEHRİN NİXON'DAN BERİ GÖRDÜĞÜ EN BÜYÜK SİYASİ GERİ DÖNÜŞE İMZA ATMA ŞANSIMIZ VAR. GİRİN İÇERİ PALYAÇOLAR.",
["Bu şehrin balıkları ceset yiye yiye semiriyor."] = "BU ŞEHRİN BALIKLARI CESET YİYE YİYE SEMİRİYOR.",
["Bu şehrin otobüsleri vaktinde gelmez diyen kimmiş! Ganimeti taşımaya başlayın."] = "BU ŞEHRİN OTOBÜSLERİ VAKTİNDE GELMEZ DİYEN KİMMİŞ! GANİMETİ TAŞIMAYA BAŞLAYIN.",
["Bu şey Keegan Oil'i dünyaya tanıtacak! Nobel Ödülü kazanabiliriz. İsveç'i hep görmek istemişimdir. Köfteleri çok iyiymiş."] = "BU ŞEY KEEGAN OİL'İ DÜNYAYA TANITACAK! NOBEL ÖDÜLÜ KAZANABİLİRİZ. İSVEÇ'İ HEP GÖRMEK İSTEMİŞİMDİR. KÖFTELERİ ÇOK İYİYMİŞ.",
["Bu şeyde hükûmeti devirebilecek sırlar var. Başkanın \"Beyefendi İlgi Alanları\" adlı klasörde ne sakladığını görmek ister misiniz? Evet, istersiniz, kesinlikle!"] = "BU ŞEYDE HÜKÛMETİ DEVİREBİLECEK SIRLAR VAR. BAŞKANIN \"BEYEFENDİ İLGİ ALANLARI\" ADLI KLASÖRDE NE SAKLADIĞINI GÖRMEK İSTER MİSİNİZ? EVET, İSTERSİNİZ, KESİNLİKLE!",
["Bu şeyler için risk almaya gerek yok. Yere koyup burada yakın gitsin."] = "BU ŞEYLER İÇİN RİSK ALMAYA GEREK YOK. YERE KOYUP BURADA YAKIN GİTSİN.",
["Bu şifre kırıcılar bazen çökebilir. İşlerini bitirene kadar yanlarında durun."] = "BU ŞİFRE KIRICILAR BAZEN ÇÖKEBİLİR. İŞLERİNİ BİTİRENE KADAR YANLARINDA DURUN.",
["Bu şık el ısıtıcılarıyla dünyanın dört bir yanındaki büyük kedilerin yaşadığı zorluklara karşı dayanışmanı göster."] = "BU ŞIK EL ISITICILARIYLA DÜNYANIN DÖRT BİR YANINDAKİ BÜYÜK KEDİLERİN YAŞADIĞI ZORLUKLARA KARŞI DAYANIŞMANI GÖSTER.",
["Bu, Buluc’un maske koleksiyonunda Maya kökenli su altı harabesinden çıkarılan ikinci maske. O da ağır bedellerle bulundu; onu getiren keşif ekibinin tek sağ kalanı, lanetli olduğunu söylüyor. Buluc bu tür düşünceleri de emrindeki insanların kaybını da umursamıyor. Onu getirmek için kullanılan küçük ahşap teknenin enkazı, Buluc’un malikanesi yakınındaki bir kumsalda çürüyor."] = "BU, BULUC’UN MASKE KOLEKSİYONUNDA MAYA KÖKENLİ SU ALTI HARABESİNDEN ÇIKARILAN İKİNCİ MASKE. O DA AĞIR BEDELLERLE BULUNDU; ONU GETİREN KEŞİF EKİBİNİN TEK SAĞ KALANI, LANETLİ OLDUĞUNU SÖYLÜYOR. BULUC BU TÜR DÜŞÜNCELERİ DE EMRİNDEKİ İNSANLARIN KAYBINI DA UMURSAMIYOR. ONU GETİRMEK İÇİN KULLANILAN KÜÇÜK AHŞAP TEKNENİN ENKAZI, BULUC’UN MALİKANESİ YAKININDAKİ BİR KUMSALDA ÇÜRÜYOR.",
["Bu, CSO'nun günlük ajandası. Artık hareketlerini takip edebiliriz."] = "BU, CSO'NUN GÜNLÜK AJANDASI. ARTIK HAREKETLERİNİ TAKİP EDEBİLİRİZ.",
["Bu, Chains’in silahlı bir darbeden sonra Orta Amerika’da VIP korumalığı yaparak geçirdiği iki uzun, sıkıcı ayın anısına sakladığı eski bir hatıra. Ona paralı askerliği bıraktıran askerî tekdüzeliği hatırlatıyor."] = "BU, CHAINS’İN SİLAHLI BİR DARBEDEN SONRA ORTA AMERİKA’DA VIP KORUMALIĞI YAPARAK GEÇİRDİĞİ İKİ UZUN, SIKICI AYIN ANISINA SAKLADIĞI ESKİ BİR HATIRA. ONA PARALI ASKERLİĞİ BIRAKTIRAN ASKERÎ TEKDÜZELİĞİ HATIRLATIYOR.",
["Bu, Champ maskesi. Dallas’ın kötü bir gününden esinlendi. Ne kadar kötü mü? Profesyonel bir boksörün karşısında on üç raunt yumruk yediğini düşün. Şişmiş kaş, kırık burun, patlamış dudak, morarmış göz, ezikler, beyin sarsıntısı, çıkık çene; ne ararsan bu maskede var. Evet, Dallas için gerçekten kötü bir gün."] = "BU, CHAMP MASKESİ. DALLAS’IN KÖTÜ BİR GÜNÜNDEN ESİNLENDİ. NE KADAR KÖTÜ MÜ? PROFESYONEL BİR BOKSÖRÜN KARŞISINDA ON ÜÇ RAUNT YUMRUK YEDİĞİNİ DÜŞÜN. ŞİŞMİŞ KAŞ, KIRIK BURUN, PATLAMIŞ DUDAK, MORARMIŞ GÖZ, EZİKLER, BEYİN SARSINTISI, ÇIKIK ÇENE; NE ARARSAN BU MASKEDE VAR. EVET, DALLAS İÇİN GERÇEKTEN KÖTÜ BİR GÜN.",
["Bu, Duke'un köşesinde kesin güzel durur! Belki almalısınız!"] = "BU, DUKE'UN KÖŞESİNDE KESİN GÜZEL DURUR! BELKİ ALMALISINIZ!",
["Bu, Golden Dagger'ı en utanç verici biçimde yıkımın eşiğine getirecek!"] = "BU, GOLDEN DAGGER'I EN UTANÇ VERİCİ BİÇİMDE YIKIMIN EŞİĞİNE GETİRECEK!",
["Bu, Murky'lerin dişlerini dökmeye yeter."] = "BU, MURKY'LERİN DİŞLERİNİ DÖKMEYE YETER.",
["Bu, belirtilen yerde olacak."] = "BU, BELİRTİLEN YERDE OLACAK.",
["Bu, bildiğiniz sıradan bir kuyumcu soygunu. Öyle bir şey varsa tabii."] = "BU, BİLDİĞİNİZ SIRADAN BİR KUYUMCU SOYGUNU. ÖYLE BİR ŞEY VARSA TABİİ.",
["Bu, bilgisayar ağlarına darbe vurup başarı şansınızı artıracak."] = "BU, BİLGİSAYAR AĞLARINA DARBE VURUP BAŞARI ŞANSINIZI ARTIRACAK.",
["Bu, burnunu sokan piçlerin işimizi gözetlemesini engeller. Güzel."] = "BU, BURNUNU SOKAN PİÇLERİN İŞİMİZİ GÖZETLEMESİNİ ENGELLER. GÜZEL.",
["Bu, bütün yerleşkeye yayın yapan bir anons sistemi gibi! Belki laboratuvarı boşaltmak için kullanabiliriz."] = "BU, BÜTÜN YERLEŞKEYE YAYIN YAPAN BİR ANONS SİSTEMİ GİBİ! BELKİ LABORATUVARI BOŞALTMAK İÇİN KULLANABİLİRİZ.",
["Bu, değil mi? Neyi özel anlamıyorum ama buraya bunun için geldik. Lindenhurst'ın bulduğu yazının aynısı."] = "BU, DEĞİL Mİ? NEYİ ÖZEL ANLAMIYORUM AMA BURAYA BUNUN İÇİN GELDİK. LİNDENHURST'IN BULDUĞU YAZININ AYNISI.",
["Bu, en azından... bir milyar dolar kazanma şansın olabilirdi!"] = "BU, EN AZINDAN... BİR MİLYAR DOLAR KAZANMA ŞANSIN OLABİLİRDİ!",
["Bu, gecenin çocuklarının o tatlı müziği değil."] = "BU, GECENİN ÇOCUKLARININ O TATLI MÜZİĞİ DEĞİL.",
["Bu, geçen yılki LA işinde açtığınızla aynı tür Kasa Dairesi. Ama buna sızmamız gerekecek."] = "BU, GEÇEN YILKİ LA İŞİNDE AÇTIĞINIZLA AYNI TÜR KASA DAİRESİ. AMA BUNA SIZMAMIZ GEREKECEK.",
["Bu, girişiminizde size kesinlikle yardımcı olacak."] = "BU, GİRİŞİMİNİZDE SİZE KESİNLİKLE YARDIMCI OLACAK.",
["Bu, girişinizi kolaylaştıracak."] = "BU, GİRİŞİNİZİ KOLAYLAŞTIRACAK.",
["Bu, girişinizi çok kolaylaştıracak."] = "BU, GİRİŞİNİZİ ÇOK KOLAYLAŞTIRACAK.",
["Bu, görev çizelgesindeki güvenlikçi sayısını azaltacak."] = "BU, GÖREV ÇİZELGESİNDEKİ GÜVENLİKÇİ SAYISINI AZALTACAK.",
["Bu, görevdeki muhafız sayısını etkili biçimde azaltacak."] = "BU, GÖREVDEKİ MUHAFIZ SAYISINI ETKİLİ BİÇİMDE AZALTACAK.",
["Bu, gözetleme sisteminin etkisini büyük ölçüde azaltacak."] = "BU, GÖZETLEME SİSTEMİNİN ETKİSİNİ BÜYÜK ÖLÇÜDE AZALTACAK.",
["Bu, gözetleme sistemlerinin etkisini azaltacak."] = "BU, GÖZETLEME SİSTEMLERİNİN ETKİSİNİ AZALTACAK.",
["Bu, güvenlik duvarlarını halleder."] = "BU, GÜVENLİK DUVARLARINI HALLEDER.",
["Bu, güvenlik işlerini sekteye uğratacak."] = "BU, GÜVENLİK İŞLERİNİ SEKTEYE UĞRATACAK.",
["Bu, güvenlikçilerin dikkatini etkili biçimde dağıtacak."] = "BU, GÜVENLİKÇİLERİN DİKKATİNİ ETKİLİ BİÇİMDE DAĞITACAK.",
["Bu, hayatındaki son hata olacak..."] = "BU, HAYATINDAKİ SON HATA OLACAK...",
["Bu, içeri girmenin etkili bir yolu."] = "BU, İÇERİ GİRMENİN ETKİLİ BİR YOLU.",
["Bu, içeri girmenizi sağlayacak."] = "BU, İÇERİ GİRMENİZİ SAĞLAYACAK.",
["Bu, işlemi başlatmalı."] = "BU, İŞLEMİ BAŞLATMALI.",
["Bu, işlere hiç iyi gelmez!"] = "BU, İŞLERE HİÇ İYİ GELMEZ!",
["Bu, kasa dairesinin Anahtar Kartlarından biri ama bir tane daha lazım. Aramaya devam edin."] = "BU, KASA DAİRESİNİN ANAHTAR KARTLARINDAN BİRİ AMA BİR TANE DAHA LAZIM. ARAMAYA DEVAM EDİN.",
["Bu, klasik el bombasının yenilenmiş sürümü. Orijinal parça tesirli el bombası hâlâ kullanılsa da bu yeni, zarif tasarım her patlamaya OVERKILL dokunuşu katacak. Hâlâ aynı derecede ucuz, hâlâ aynı derecede etkili."] = "BU, KLASİK EL BOMBASININ YENİLENMİŞ SÜRÜMÜ. ORİJİNAL PARÇA TESİRLİ EL BOMBASI HÂLÂ KULLANILSA DA BU YENİ, ZARİF TASARIM HER PATLAMAYA OVERKILL DOKUNUŞU KATACAK. HÂLÂ AYNI DERECEDE UCUZ, HÂLÂ AYNI DERECEDE ETKİLİ.",
["Bu, mahkûm naklini durdurur, değil mi? Hadi ilerleyelim!"] = "BU, MAHKÛM NAKLİNİ DURDURUR, DEĞİL Mİ? HADİ İLERLEYELİM!",
["Bu, muhafızları meşgul edecek ve varlığınızı fark etmelerini çok daha zorlaştıracak."] = "BU, MUHAFIZLARI MEŞGUL EDECEK VE VARLIĞINIZI FARK ETMELERİNİ ÇOK DAHA ZORLAŞTIRACAK.",
["Bu, muhafızları oyalar."] = "BU, MUHAFIZLARI OYALAR.",
["Bu, muhafızların dikkatini eminim çok işinize yarayacak şekilde dağıtacak."] = "BU, MUHAFIZLARIN DİKKATİNİ EMİNİM ÇOK İŞİNİZE YARAYACAK ŞEKİLDE DAĞITACAK.",
["Bu, ne yaptığımızı görmelerini engeller. Güzel."] = "BU, NE YAPTIĞIMIZI GÖRMELERİNİ ENGELLER. GÜZEL.",
["Bu, o sersem Wang'ı fena rezil edecek! Bankadaki paramız biraz artacak, Vlad da hak ettiği intikamı alacak."] = "BU, O SERSEM WANG'I FENA REZİL EDECEK! BANKADAKİ PARAMIZ BİRAZ ARTACAK, VLAD DA HAK ETTİĞİ İNTİKAMI ALACAK.",
["Bu, pişirmeyi başlatmalı."] = "BU, PİŞİRMEYİ BAŞLATMALI.",
["Bu, planınızın başarıya ulaşmasını kolaylaştıracak."] = "BU, PLANINIZIN BAŞARIYA ULAŞMASINI KOLAYLAŞTIRACAK.",
["Bu, sahile kadar gidiyor, ekip!"] = "BU, SAHİLE KADAR GİDİYOR, EKİP!",
["Bu, silonun yanına inecek, duydunuz mu?"] = "BU, SİLONUN YANINA İNECEK, DUYDUNUZ MU?",
["Bu, soyguncunun seçili zırhla giydiği varsayılan kıyafettir."] = "BU, SOYGUNCUNUN SEÇİLİ ZIRHLA GİYDİĞİ VARSAYILAN KIYAFETTİR.",
["Bu, standart donanım parçasıdır."] = "BU, STANDART DONANIM PARÇASIDIR.",
["Bu, tek başına yaptığı cesur soygunlarla tanınan efsanevi Meksikalı banka soyguncusu El Toro Furioso’nun bir zamanlar kullandığı silah."] = "BU, TEK BAŞINA YAPTIĞI CESUR SOYGUNLARLA TANINAN EFSANEVİ MEKSİKALI BANKA SOYGUNCUSU EL TORO FURIOSO’NUN BİR ZAMANLAR KULLANDIĞI SİLAH.",
["Bu, varışınız sırasında güvenlik personelinin sayısını azaltacak."] = "BU, VARIŞINIZ SIRASINDA GÜVENLİK PERSONELİNİN SAYISINI AZALTACAK.",
["Bu, yalnızca E3 için yapılmış kısa bir Golden Grin Casino Heist demosudur."] = "BU, YALNIZCA E3 İÇİN YAPILMIŞ KISA BİR GOLDEN GRIN CASINO HEIST DEMOSUDUR.",
["Bu, yani, epey büyük bir patlamaydı."] = "BU, YANİ, EPEY BÜYÜK BİR PATLAMAYDI.",
["Bu, yapacağın son hata..."] = "BU, YAPACAĞIN SON HATA...",
["Bu, çatışmada daha uzun kalmanızı sağlayacak."] = "BU, ÇATIŞMADA DAHA UZUN KALMANIZI SAĞLAYACAK.",
["Bu, öyle malzeme değil; bu nano-termit! Benim için İsveç'ten kaçırıldı. Ekstra güçlü."] = "BU, ÖYLE MALZEME DEĞİL; BU NANO-TERMİT! BENİM İÇİN İSVEÇ'TEN KAÇIRILDI. EKSTRA GÜÇLÜ.",
["Bu... Eski aile meseleleri. Siz ona bakmayın..."] = "BU... ESKİ AİLE MESELELERİ. SİZ ONA BAKMAYIN...",
["Bu... bayağı çok prototip. Çalışan olanı lazım."] = "BU... BAYAĞI ÇOK PROTOTİP. ÇALIŞAN OLANI LAZIM.",
["Bu... nükleer savaş başlığı mı!? Ben... Şey... Bakın, alın işte. Dikkatlice!"] = "BU... NÜKLEER SAVAŞ BAŞLIĞI MI!? BEN... ŞEY... BAKIN, ALIN İŞTE. DİKKATLİCE!",
["Bu... tuhaf, değil mi?"] = "BU... TUHAF, DEĞİL Mİ?",
["Bu... Çok para. Galiba artık met ticaretindeyiz. Ama o bilgi gerçekten lazımdı. Hatırladınız mı? Hazırlanın, bilgi olsa da olmasa da o pislikleri alalım."] = "BU... ÇOK PARA. GALİBA ARTIK MET TİCARETİNDEYİZ. AMA O BİLGİ GERÇEKTEN LAZIMDI. HATIRLADINIZ MI? HAZIRLANIN, BİLGİ OLSA DA OLMASA DA O PİSLİKLERİ ALALIM.",
["Bubi tuzağı kurmuşlar!"] = "BUBİ TUZAĞI KURMUŞLAR!",
["Buccaneers Ahoy!’da bu kılıç sallayan yaşayan ölü soyguncular, yıllarca Karayipler’in hazine dolu kalyonlarına dehşet saçtı. Böylece korsanların sonsuza dek çooook havalı olduğunu kanıtladılar."] = "BUCCANEERS AHOY!’DA BU KILIÇ SALLAYAN YAŞAYAN ÖLÜ SOYGUNCULAR, YILLARCA KARAYİPLER’İN HAZİNE DOLU KALYONLARINA DEHŞET SAÇTI. BÖYLECE KORSANLARIN SONSUZA DEK ÇOOOOK HAVALI OLDUĞUNU KANITLADILAR.",
["Bueno, biz gittik dostum."] = "BUENO, BİZ GİTTİK DOSTUM.",
["Bugün"] = "BUGÜN",
["Bugün Değil"] = "BUGÜN DEĞİL",
["Bugün GenSec'e çok çektirdiniz. Gürültülü yaptığınız için dünya da öğrendi. Bu iyi."] = "BUGÜN GENSEC'E ÇOK ÇEKTİRDİNİZ. GÜRÜLTÜLÜ YAPTIĞINIZ İÇİN DÜNYA DA ÖĞRENDİ. BU İYİ.",
["Bugün Green Bridge'de havai fişek gösterisi yapacağız."] = "BUGÜN GREEN BRIDGE'DE HAVAİ FİŞEK GÖSTERİSİ YAPACAĞIZ.",
["Bugün ana aletimiz Apollonious kesici olacak. Daxter'ın eski ekibinden kalan ufak bir miras."] = "BUGÜN ANA ALETİMİZ APOLLONİOUS KESİCİ OLACAK. DAXTER'IN ESKİ EKİBİNDEN KALAN UFAK BİR MİRAS.",
["Bugün biraz formsuzum dostlar. Yazılım güvenlik duvarının yedeğini atlamışım. Doğru bilgisayarı bulup kapatabilir misiniz?"] = "BUGÜN BİRAZ FORMSUZUM DOSTLAR. YAZILIM GÜVENLİK DUVARININ YEDEĞİNİ ATLAMIŞIM. DOĞRU BİLGİSAYARI BULUP KAPATABİLİR MİSİNİZ?",
["Bugün daha iyi olabilirdi, millet. Ama Locke'la eninde sonunda hesaplaşacağız. Sadece bizden kaçıyor olmayacak."] = "BUGÜN DAHA İYİ OLABİLİRDİ, MİLLET. AMA LOCKE'LA ENİNDE SONUNDA HESAPLAŞACAĞIZ. SADECE BİZDEN KAÇIYOR OLMAYACAK.",
["Bugün de günlerden o gün olacak... orası kesin."] = "BUGÜN DE GÜNLERDEN O GÜN OLACAK... ORASI KESİN.",
["Bugün de pek ateşliyiz, ha?"] = "BUGÜN DE PEK ATEŞLİYİZ, HA?",
["Bugün dilediğiniz kadar yiyebileceğiniz açık büfemizi denemeyi düşünüyor musunuz diye soracaktım."] = "BUGÜN DİLEDİĞİNİZ KADAR YİYEBİLECEĞİNİZ AÇIK BÜFEMİZİ DENEMEYİ DÜŞÜNÜYOR MUSUNUZ DİYE SORACAKTIM.",
["Bugün güzel para geliyor."] = "BUGÜN GÜZEL PARA GELİYOR.",
["Bugün iyi bir şey yaptınız dostlarım. Sanırım Coyopa'ların işi bitti ve Dentist, Meksika'daki bütün nüfuzunu kaybedecek. Artık oradan ona yardım gelmeyecek. Bunu Hajrudin'e anlatacağım, sevinecek. Belki biraz da kendine çeki düzen verir. Belki de vermez. Artık Vlad size borçlu ve çok yakında karşılığını vereceğim. Şimdi ilgilenmem gereken yeni işler var. Tekrar görüşene dek! Şerefe, hoşça kalın."] = "BUGÜN İYİ BİR ŞEY YAPTINIZ DOSTLARIM. SANIRIM COYOPA'LARIN İŞİ BİTTİ VE DENTİST, MEKSİKA'DAKİ BÜTÜN NÜFUZUNU KAYBEDECEK. ARTIK ORADAN ONA YARDIM GELMEYECEK. BUNU HAJRUDİN'E ANLATACAĞIM, SEVİNECEK. BELKİ BİRAZ DA KENDİNE ÇEKİ DÜZEN VERİR. BELKİ DE VERMEZ. ARTIK VLAD SİZE BORÇLU VE ÇOK YAKINDA KARŞILIĞINI VERECEĞİM. ŞİMDİ İLGİLENMEM GEREKEN YENİ İŞLER VAR. TEKRAR GÖRÜŞENE DEK! ŞEREFE, HOŞÇA KALIN.",
["Bugün yaşanan onca boktan sonra bile fena değil."] = "BUGÜN YAŞANAN ONCA BOKTAN SONRA BİLE FENA DEĞİL.",
["Bugün şanslı günümüz değil galiba... O muhafız sunucu odasını gözetliyor. Ondan kurtulun."] = "BUGÜN ŞANSLI GÜNÜMÜZ DEĞİL GALİBA... O MUHAFIZ SUNUCU ODASINI GÖZETLİYOR. ONDAN KURTULUN.",
["Bugün şanslı günümüz. Havaalanından bu bankaya nakit geliyor, her türlü kupürden... O yüzden kendi para değişimimizi yapmayı öneriyorum."] = "BUGÜN ŞANSLI GÜNÜMÜZ. HAVAALANINDAN BU BANKAYA NAKİT GELİYOR, HER TÜRLÜ KUPÜRDEN... O YÜZDEN KENDİ PARA DEĞİŞİMİMİZİ YAPMAYI ÖNERİYORUM.",
["Bugüne kadar bir sürü belalıyla kapıştık. Murkywater. The Golden Dagger Triad. FBI'ı bile soyduk. "] = "BUGÜNE KADAR BİR SÜRÜ BELALIYLA KAPIŞTIK. MURKYWATER. THE GOLDEN DAGGER TRIAD. FBI'I BİLE SOYDUK. ",
["Bugünkü gündemimizin sıradaki maddesi, erkekler tuvaletine yeni kapı menteşeleri takılacak olması. Lütfen gelecekte menteşelere gereksiz yük bindirmekten kaçının. Ajan Johnson'ın kapıların yere kadar uzatılması yönündeki dilekçesi gelecek bütçe dönemimiz için değerlendiriliyor."] = "BUGÜNKÜ GÜNDEMİMİZİN SIRADAKİ MADDESİ, ERKEKLER TUVALETİNE YENİ KAPI MENTEŞELERİ TAKILACAK OLMASI. LÜTFEN GELECEKTE MENTEŞELERE GEREKSİZ YÜK BİNDİRMEKTEN KAÇININ. AJAN JOHNSON'IN KAPILARIN YERE KADAR UZATILMASI YÖNÜNDEKİ DİLEKÇESİ GELECEK BÜTÇE DÖNEMİMİZ İÇİN DEĞERLENDİRİLİYOR.",
["Bugünün para özeti:"] = "BUGÜNÜN PARA ÖZETİ:",
["Bugünün toplumunun her lifine işleyen çürümüş yozlaşmaya sert bir karşılık vermek gerekiyor. Kendini kandırmaya, sahte bir güvenlik duygusu için çırpınmaya. Ama güvende değilsin; ne şimdi ne de hiçbir zaman. Amerikan Rüyası, zavallı ruhları yoldan çıkarmak için kılık değiştirmiş, korkunç yaralarla dolu bir kâbus. İhtiyacını al; geleceğini boğazından yakala, hırsını boğulana kadar boğazından aşağı tık. Geçtiğin yerleri arkanda bıraktığın cesetlerle işaretle."] = "BUGÜNÜN TOPLUMUNUN HER LİFİNE İŞLEYEN ÇÜRÜMÜŞ YOZLAŞMAYA SERT BİR KARŞILIK VERMEK GEREKİYOR. KENDİNİ KANDIRMAYA, SAHTE BİR GÜVENLİK DUYGUSU İÇİN ÇIRPINMAYA. AMA GÜVENDE DEĞİLSİN; NE ŞİMDİ NE DE HİÇBİR ZAMAN. AMERİKAN RÜYASI, ZAVALLI RUHLARI YOLDAN ÇIKARMAK İÇİN KILIK DEĞİŞTİRMİŞ, KORKUNÇ YARALARLA DOLU BİR KÂBUS. İHTİYACINI AL; GELECEĞİNİ BOĞAZINDAN YAKALA, HIRSINI BOĞULANA KADAR BOĞAZINDAN AŞAĞI TIK. GEÇTİĞİN YERLERİ ARKANDA BIRAKTIĞIN CESETLERLE İŞARETLE.",
["Bugünün şifresi 559732. Bu kadar sürdüğü için kusura bakmayın."] = "BUGÜNÜN ŞİFRESİ 559732. BU KADAR SÜRDÜĞÜ İÇİN KUSURA BAKMAYIN.",
