["Burada işimiz bitti!"] = "BURADA İŞİMİZ BİTTİ!",
["Burada işimiz bitti. Binanın öbür tarafında minibüs bekliyor. Geçin, arabayı yükleyin, iş bitsin."] = "BURADA İŞİMİZ BİTTİ. BİNANIN ÖBÜR TARAFINDA MİNİBÜS BEKLİYOR. GEÇİN, ARABAYI YÜKLEYİN, İŞ BİTSİN.",
