["Burada lanet Rahibe Teresa gibiyim."] = "BURADA LANET RAHİBE TERESA GİBİYİM.",
["Burada malzeme azalıyor. Daha fazla malzeme almak istiyorsanız işaret fişeğiyle helikoptere haber verin. Pilotun ücreti saate göre, geldiğine değsin. Ya da kaçabilirsiniz. Karar sizin."] = "BURADA MALZEME AZALIYOR. DAHA FAZLA MALZEME ALMAK İSTİYORSANIZ İŞARET FİŞEĞİYLE HELİKOPTERE HABER VERİN. PİLOTUN ÜCRETİ SAATE GÖRE, GELDİĞİNE DEĞSİN. YA DA KAÇABİLİRSİNİZ. KARAR SİZİN.",
["Burada milyonlarca dosya var, hepsi de şifreli. Onu yeniden konuşturun!"] = "BURADA MİLYONLARCA DOSYA VAR, HEPSİ DE ŞİFRELİ. ONU YENİDEN KONUŞTURUN!",
