["Buradaki işim bitti! Gidiyorum."] = "BURADAKİ İŞİM BİTTİ! GİDİYORUM.",
["Buradaki işimiz bitti. Eve dönme vakti!"] = "BURADAKİ İŞİMİZ BİTTİ. EVE DÖNME VAKTİ!",
["Buradaki işimiz bitti. Tahliye noktasına gidin!"] = "BURADAKİ İŞİMİZ BİTTİ. TAHLİYE NOKTASINA GİDİN!",
["Buradaki işimiz bitti. Çıkma vakti."] = "BURADAKİ İŞİMİZ BİTTİ. ÇIKMA VAKTİ.",
["Buradaki işiniz bitince Neo-2'yi Keegan Oil icadı olarak patentlemek için gereken her şey elimde olacak. Beni rakiplerimin ışık yılları önüne geçirecek."] = "BURADAKİ İŞİNİZ BİTİNCE NEO-2'Yİ KEEGAN OİL İCADI OLARAK PATENTLEMEK İÇİN GEREKEN HER ŞEY ELİMDE OLACAK. BENİ RAKİPLERİMİN IŞIK YILLARI ÖNÜNE GEÇİRECEK.",
["Buradaki işçilerden biri Keegan'ın adamı. Gabriel'in odasına giden havalandırma fanını sıkıştırmak için bir alet bırakmış. Hemen bulun."] = "BURADAKİ İŞÇİLERDEN BİRİ KEEGAN'IN ADAMI. GABRİEL'İN ODASINA GİDEN HAVALANDIRMA FANINI SIKIŞTIRMAK İÇİN BİR ALET BIRAKMIŞ. HEMEN BULUN.",
